SELECT 'moj-all-verified-judgments-review-002-chunk-166' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"768c6da8-5713-53d2-be80-0591d00151d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -التملك الصوري للعقار -صندوق التنمية العقاري -اتفاق على سداد أقساط قرض -سداد أجرة سكن عائلي مشترك -صورية متلك العقار -شهادة غير منتجه يف الدعوى -ضم صورة صك سابق إلى الدعوى القائمة -حتول العقد الصوري إلى حقيقي - صرف النظر عن الدعوى ما أستند إليه القاضي من املبادئ العامة وقواعد العدالة يف تسبيب","document_number":"33473941","case_number":"5048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/20","year":"1434","subject":"عقار -التملك الصوري للعقار -صندوق التنمية العقاري -اتفاق على سداد أقساط قرض -سداد أجرة سكن عائلي مشترك -صورية متلك العقار -شهادة غير منتجه يف الدعوى -ضم صورة صك سابق إلى الدعوى القائمة -حتول العقد الصوري إلى حقيقي - صرف النظر عن الدعوى ما أستند إليه القاضي من املبادئ العامة وقواعد العدالة يف تسبيب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33473941:‬تاريخه ‪1433/12/20:‬هـ‬\n                              ‫رقم الدعوى ‪5048 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3362490‬تاريخه‪1433/02/06 :‬هـ‬\n\n\n       ‫عقــار ‪ -‬التملــك الصــوري للعقــار ‪ -‬صنــدوق التنميــة العقــاري ‪ -‬اتفــاق‬\n       ‫على ســداد أقســاط قرض ‪ -‬ســداد أجرة ســكن عائلي مشــترك ‪ -‬صورية‬\n       ‫متلــك العقــار ‪ -‬شــهادة غيــر منتجــه يف الدعــوى ‪ -‬ضــم صــورة صــك‬\n       ‫ســابق إلــى الدعــوى القائمــة ‪ -‬حتــول العقــد الصــوري إلــى حقيقــي ‪-‬‬\n                                                       ‫صــرف النظــر عــن الدعــوى‬\n\n\n\n\n       ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                             ‫حكمه‬\n\n\n\n       ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه «شــقيقه» بــأن مــن اجلــاري يف‬\n       ‫ملكــه البيــت املســجل باســمه مبوجــب صــك شــرعي وقــد نــال ألجلــه‬\n       ‫قرضــا مــن صنــدوق التنميــة العقــاري وكان يعمــل يف مدينــة أخــرى‬\n       ‫ووالــده وبعــض أخوتــه يســكنون يف البيــت محــل النــزاع ومــن بينهــم‬\n       ‫املدعــى عليــه ويف عــام ‪1410‬ه ـ اتفــق خمســة مــن اإلخــوة ومعهــم املدعــى‬\n       ‫عليــه علــى أن يقومــوا باملشــاركة يف دفــع جــزء مــن قســط القــرض‬\n       ‫الســنوي ويكــون علــى كل واحــد منهــم ألفــان وأربعمئــة ريــال يدفعهــا‬\n       ‫كل ســنة وألن املدعــى عليــه بقــي يف العقــار أحــدى عشــرة ســنة فيطلــب‬\n       ‫إلزامــه بدفــع أربعــة وعشــرين ألــف ريــال ‪ ،‬أنكــر املدعــى عليــه الدعــوى‬\n‫‪309‬‬\n\f‫ودفــع بــأن املنــزل ملــك لوالــده حقيقــة آلــت أرضــه إليــه مبنحــة مــن األمانة‬\n‫وألنــه ســبق وأن اقتــرض مــن صنــدوق التنميــة فقــد طلــب مــن املدعــي أن‬\n‫يتقــدم بطلــب قــرض عليهــا فجــرى تســجيل األرض باســمه صوريــا وإال‬\n‫فــإن مــن بنــاه والــده وقــد دفــع قســطني وأعفــي مــن قســطني ولــو طلــب‬\n‫والــده منــه دفــع أي مبلــغ لوافــق ويف أزمــة اخلليــج وملــا كثــرت العوائــل يف‬\n‫البيــت طلــب والــده مــن اإلخــوة أن يرســل كل منهــم ألفــن وخمســمئة‬\n‫ريــال شــهريا فاجتمــع لديــه مبلغــا وطلــب املدعــي الــزواج فدفــع لــه‬\n‫ســتني ألــف ريــال ثــم طلــب مــن والــده تســليمه الصــك فلمــا ســلمه لــم‬\n‫يــرده إليــه حتــى اآلن حتــى قــام والــده بإقامــة دعــوى ضــده إلثبــات متلــك‬\n‫البيــت ‪ -‬حضــر والــد املتداعيــن وقــرر بــأن مــا ورد يف دعــوى املدعــي‬\n‫غيــر صحيــح وأن الصحيــح بــأن أوالده قامــوا بإعطائــه مــاال أيــام أزمــة‬\n‫اخلليــج عــدا املدعــي فلــم يســلمه شــيئا بــل وهبــه ســتني ألــف ريــال لزواجــه‬\n‫وأنــه مــن قــام ببنــاء البيــت بــا مشــاركة مــن املدعــي ‪ -‬أحضــر املدعــي‬\n‫شــاهدا أحــد إخوتــه وشــهد باتفــاق اإلخــوة علــى أن يدفــع كل واحــد‬\n‫منهــم ألفــن وأربعمئــة ريــال لســداد القــرض عــن املدعــي ‪ -‬بعــرض‬\n‫الشــهادة علــى املدعــى عليــه أنكرهــا ‪ -‬جــرى اطــاع الدائــرة علــى‬\n‫صــورة صــك املتضمــن دعــوى والــد املدعــي ضــده وقــد أقــر فيــه صراحــة‬\n‫بــأن اإلفــراغ لــه كان صوريــا وأحيلــت املعاملــة ملكتــب الصلــح وتضمــن‬\n‫ثبــوت الصلــح بينهمــا علــى إبقــاء العقــار مســجال باســم املدعــي مقابــل‬\n‫مئــة ألــف ريــال ‪ -‬عليــه وحيــث حضــر والــد املتداعيــن وأفــاد أن أصــل‬\n‫متلــك البيــت احلقيقــي لــه ومتلــك املدعــي للعقــار متلــكا صوريــا وصــادق‬\n‫املدعــي علــى ذلــك بــل اصطلــح مــع أبيــه علــى أن يدفــع لــه مئــة ألــف ريــال‬\n‫ودفعهــا لــذا لــم حتصــل ملكيــة املدعــي للبيــت متلــكا حقيقيــا إال بعــد‬\n\n\n                                                                                        ‫‪310‬‬\n\f      ‫الصلــح وألن مطالبــة املدعــي باســتحقاق املبلــغ املدعــى بــه قبــل متلكــه‬\n      ‫للبيــت متلــكا حقيقــا لذلــك كلــه فقــد قــررت الدائــرة صــرف النظــر‬\n      ‫عــن دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه مــن هــذه القضيــة ‪ -‬قــرر‬\n      ‫املدعــي االعتــراض فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باخلــرج برقــم ‪ 5048‬وتاريــخ ‪ 1431/08/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3120003‬وتاريــخ ‪ 1431/08/01‬ه ـ ففــي‬\n      ‫يــوم االربعــاء املوافــق‪ 1432/04/25‬ه ـ أفتتحــت اجللســة وفيهــا حضــر‬\n      ‫‪ ................‬سعودي اجلنسية مبوجب السجل املدني رقم ……………‪.‬‬\n      ‫وادعــى علــى احلاضــر معه ‪ ................... /‬ســجله املدني رقــم ‪...................‬‬\n      ‫قائــا يف دعــواه إن مــن اجلــاري يف ملكــي وحتــت تصــريف كامــل البيــت‬\n      ‫الفيــا مكونــة مــن دوريــن مســتقلني يقــع يف حــي الســعودية يف اخلــرج‬\n      ‫اململوكــة لــي بالصــك الصــادر مــن كتابــة عــدل اخلــرج برقــم ‪1/230‬‬\n      ‫يف ‪1403/4/11‬ه ـ وقــد اقترضــت عليهــا مــن صنــدوق التنميــة العقاريــة‬\n      ‫مبلغــا قــدره ثالثمائــة ألــف ريــال وكنــت أعمــل يف املنطقــة الشــرقية‬\n      ‫وقــد رغــب والــدي ســكن الفيــا وطلــب مــن أخوتــي الســكن معــه ومــن‬\n      ‫ضمنهــم املدعــى عليــه ويف عــام ‪1410‬ه ـ اتفقنــا نحــن األخــوة اخلمســة‬\n      ‫أنــا ‪ ...........‬واملدعــى عليــه و‪ ...........‬و‪ .......‬و‪ .........‬و‪ ............‬علــى تقســيم‬\n      ‫القســط الســنوي لصنــدوق التنميــة العقاريــة البالــغ اثنــا عشــر ألــف ريــال‬\n\n‫‪311‬‬\n\f‫علينــا نحــن اخلمســة فبلــغ نصيــب الواحــد ألفــان وأربعمائــة ريــال يدفعهــا‬\n‫كل شــخص عــن كل ســنة وقــد بقــي املدعــى عليــه يف الســكن مــن‬\n‫عــام ‪1410‬ه ـ إلــى عــام ‪1421‬ه ـ وبلــغ إجمالــي ماعليــه عشــر ســنني أي‬\n‫أربعــة وعشــرون ألــف ريــال وصنــدوق التنميــة العقاريــة الزال يطالبنــي‬\n‫أطلــب احلكــم علــى املدعــى عليــه وإلزامــه بــأن يدفــع هــذا املبلــغ لــي‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه قــال ال صحــة جلميــع ماذكــره‬\n‫املدعــي جملــة وتفصيــا وذلــك أن البيــت يف األســاس لوالدنــا وأرضــه‬\n‫منحــه عــن طريــق بلديــة اخلــرج كغيرهــا مــن أراضــي حــي الســعودية‬\n‫وســبق للوالــد أن أقتــرض مــن صنــدوق التنميــة العقاريــة يف املدينــة (‬\n‫محافظــة خيبــر) وألن املدعــي يف ذلــك الوقــت يحمــل بطاقــة األحــوال‬\n‫جعــل والدنــا البيــت بإســم املدعــي صوريــا ووالــدي هــو الــذي يدفــع‬\n‫قــرض صنــدوق التنميــة ودفــع قســطني وأعفــي مــن قســطني وهــو الــذي‬\n‫يتصــرف يف البيــت ولــو طلــب منــا دفــع أي مبلــغ دفعنــاه وقــد اجتمعــت‬\n‫عوائلنــا يف البيــت عــام ‪1410‬ه ـ يف بدايــة أزمــة اخلليــج األولــى ولــم أكــن‬\n‫وقتهــا متزوج ـ ًا وحــن كثــرت العائلــة يف املنــزل حيــث أنــا أربعــة أخــوة‬\n‫يف اجلبهــة وعوائــل أخوانــي عنــد والــدي طلــب منــا الوالــد أن يرســل كل‬\n‫واحــد منــا شــهريا ألفــن وخمســمائة ريــال واجتمــع عنــد والدنــا مبلغــا‬\n‫وقــد طلــب املدعــي الــزواج فدفــع عنــه الوالــد ســتني ألــف ريــال ثــم أن‬\n‫املدعــي طلــب مــن والــدي أن يســلم صــك البيــت مــن أجــل أن يســقط‬\n‫قــرض الصنــدوق فســلمه لــه ولــم يعــده لوالــدي حتــى أقــام والــدي دعــوى‬\n‫ضــد املدعــي وذلــك مــن أجــل إثبــات متلكــه للبيــت متلــك ًا حقيقيــا حيــث‬\n‫أن متلــك املدعــي متلــكا صوريــا هكــذا اجاب كماحضــر ‪................. /‬‬\n‫ســجله املدنــي رقــم ‪ ..................‬وهــو والــد املدعــي واملدعــى عليــه وجــرى‬\n\n\n                                                                                         ‫‪312‬‬\n\f      ‫ســؤاله عمــا لديــه فقــال إن جميــع أقــوال املدعــي غيــر صحيحــة وأنــا‬\n      ‫حــن كنــت يف البيــت قــام األخــوة األربعــة ‪ ...‬و‪...‬و‪ ...‬و‪...‬مبواصلتــي باملــال‬\n      ‫وقــت األزمــة أمــا املدعــي فإنــه مقيــم مــع عائلتــه يف الشــرقية ولــم يدفــع‬\n      ‫ولــو ريــاال واحــدا بــل إننــي دفعــت عنــه يف زواجــه ســتني ألــف ريــال وأنــا‬\n      ‫الــذي قمــت ببنــاء العقــار ووقــف عنــد العظــم وهــو بإســم املدعــي ألننــي‬\n      ‫ســبق أن اقترضــت مــن صنــدوق التنميــة العقاريــة والأرى املدعي يســتحق‬\n      ‫املبلــغ الــذي يطالــب بــه ألنــه لــم يخســر ولــو ريــاال واحــدا وبعرضــه علــى‬\n      ‫املدعــي قــال الصحيــح ماذكــرت ولــدي البينــة علــى ذلــك أخــي ‪........‬‬\n      ‫وســبق حضــوره ‪ ........‬يف يــوم لــم يحــدد فيــه جلســة ومت تدويــن شــهادته‬\n      ‫يف حينــه ووعــد باحلضــور هــذا اليــوم وهــذا نــص شــهادته أشــهد هلل أننــا‬\n      ‫اجتمعنــا نحــن األخــوة أنــا ‪ ........‬و‪ .........‬و‪ ..........‬و‪ ............‬و‪ ...........‬عــام‬\n      ‫‪1410‬ه ـ واتفقنــا علــى أن يدفــع كل واحــد منــا يف كل ســنة ألفــن‬\n      ‫وأربعمائــة ريــال لســداد قــرض صنــدوق التنميــة العقاريــة علــى املنــزل‬\n      ‫الــذي نســكن فيــه مــع والدنــا والقــرض بإســم املدعــي ‪ .......‬ويف عــام‬\n      ‫‪1425‬ه ـ ورد لنــا إنــذار مــن صنــدوق التنميــة لإلســراع بســداد قــرض‬\n      ‫الصنــدوق وبلــغ إجمالــي األقســاط احلالــة مئتــان وثالثــون ألــف ريــال ولــم‬\n      ‫يســدد القــرض إلــى اآلن هــذا مالــدي وبــه أشــهد) ويف الســاعة الواحــدة‬\n      ‫وخمســة وثالثــن دقيقــة أحضــر ‪ ......................‬وجــرى ســؤال املدعــى‬\n      ‫عليــه عــن شــهادة الشــاهد فقــال الأقــول يف الشــاهد شــيئا وشــهادته‬\n      ‫غيــر صحيحــة ألنــه متعاطــف ومتاليــن مــع املدعــي ولــم جنتمــع ولــم نتفــق‬\n      ‫علــى دفــع مبلــغ معــن ولضيــق الوقــت والتأمــل رفعــت اجللســة وعليــه‬\n      ‫حصــل التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/04/25‬ه ـ‬\n\n\n‫‪313‬‬\n\f‫ويف يــوم الثالثــاء املوافــق‪ 1433/04/13‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــر املدعــي وحضــر حلضــوره املدعــى عليــه وجــرى اإلطــاع علــى‬\n‫أوراق املعاملــة ومــن بينهــا صــورة الصــك الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 42/8/54‬يف ‪1428/8/12‬ه ـ ويتضمــن إقامــة دعــوى مــن والــد‬\n‫املدعــي (هنــا) ‪ .....................‬ضــد املدعــي ويطلــب املدعــي مــن املدعــى‬\n‫عليــه أن يفــرغ الصــك رقــم ‪ 3/230‬يف ‪1403/4/11‬ه ـ الصــادر مــن‬\n‫كتابــة عــدل اخلــرج لــه ألن بقــاء الصــك بإســم املدعــى عليــه (املدعــي‬\n‫هنــا) كان صوريــا وقــد أجــاب املدعــى عليــه بقولــه صحيــح أن اإلفــراغ‬\n‫بإســمي صوريــا وأحيلــت املعاملــة ملكتــب الصلــح وذيــل الصــك بــأن‬\n‫املدعــي واملدعــى عليــه اصطلحــا علــى أن يدفــع املدعــى عليــه (املدعــي‬\n‫هنــا ) ألبيــه مائــة ألــف ريــال ويبقــى الصــك بإســم املدعــى عليــه (املدعــي‬\n‫هنــا) ومبناقشــة املدعــي عــن ذلــك قــال إن والــدي مت حتريضــة مــن‬\n‫املدعــى عليــه ‪ ...‬ورغبــة منــي يف عــدم اســتمرار الدعــوى بينــي وبــن‬\n‫والــدي اســتعديت بدفــع مائــة ألــف ريــال ودفعتهــا لــه وليــس لــدي بينــة‬\n‫ســوى أخــي ‪ ........‬ومســتعد بإحضــار معدلــن لــه وأكمــل بينتــي باليمــن‬\n‫علــى صحــة دعــواي وبعرضــه علــى املدعــى عليــه قــال كمــا ذكــرت أن‬\n‫شــهادة اخــي ‪ ......‬غيــر صحيحــة فســألته هــل لديــه طعــن يف اخيــه ‪.........‬‬\n‫فقــال ليــس لــدي بينــة غيــر بيــان والــدي وألن القضيــة حتتــاج ملزيــد تأمــل‬\n‫رفعــت اجللســة وعليــه حصــل التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/13‬ه ـ‬\n‫ويف يــوم االثنــن املوافــق ‪1433/12/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي وحضــر حلضــوره املدعــى عليــه وجــرى تأمــل الدعــوى واإلجابــة‬\n‫وحيــث حضــر والــد املدعــي ووالــد املدعــى عليــه وأفــاد أن أصــل متلــك‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫البيــت احلقيقــي بإســمه هــو ومتلــك املدعــي متلــكا صوريــا وصــادق‬\n      ‫املدعــي علــى ذلــك بــل اصطلــح مــع أبيــه علــى أن يدفــع لــه مائــة ألــف‬\n      ‫ريــال ودفعهــا ولــم تتــم ملكيــة املدعــي للبيــت متلــكا حقيقيــا إال بعــد‬\n      ‫دفــع املبلــغ واملدعــي يطالــب بإســتحقاق املبلــغ املدعــى بــه قبــل متلكــه‬\n      ‫للبيــت متلــكا حقيقــا لذلــك كلــه فقــد صــرف النظــر عــن دعــوى‬\n      ‫املدعــي وأخليــت ســبيل املدعــى عليــه مــن هــذه القضيــة وبــه حكمــت‬\n      ‫حتريــرا يف ‪1433/12/20‬ه ـ وبعرضــه علــى الطرفــن قنــع املدعــى عليــه‬\n      ‫ولــم يقنــع املدعــي وطلــب رفعــه حملكمــة االســتئناف بالئحــة فأجيــب‬\n      ‫لطلبــه وأفهــم باملراجعــة هــذا اليــوم بإســتالم نســخة مــن احلكــم لتقــدمي‬\n      ‫الئحــة اعتــراض عليهــا يف مــدة اقصاهــا ثالثــون يومــا مــن التاريــخ‬\n      ‫املذكــور وإن لــم يتقــدم بإعتــراض خــال تلــك املــدة فيســقط حقــه يف‬\n      ‫االســتئناف ويكتســب احلكــم القطعيــة وصلــى اهلل علــى نبينــا محمــد‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/6/24‬ه ـ افتتحــت‬\n      ‫اجللســة بعــد أن عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقــرار‬\n      ‫رقــم ‪ 34173321‬يف ‪1434/3/28‬ه ـ واخلاصــة بدعــوى ‪ ...‬ضــد ‪ ...‬وجــاء‬\n      ‫فيــه بعــد املقدمــة وبدراســة الصــك وصــورة ضبطــه والالئحــة وأوراق‬\n      ‫املعاملــة لوحــظ أن املدعــي ذكــر يف الالئحــة اإلعتراضيــة وجــود حكــم‬\n      ‫مميــز باألجــرة فيناقــش عــن ذلــك وترفــق صــورة لهــذا الصــك ومــا عليــه‬\n      ‫مــن تظهيــرات واهلل املوفــق وجوبــا عليــه فقــد أفــاد املدعــي أن لــه دعــوى‬\n      ‫مماثلــة منظــورة لــدى فضيلــة الشــيخ ‪ . ...................‬املكتــب القضائــي‬\n      ‫العاشــر ضــد أخيــه ‪ ................‬وبنــاء عليــه فقــد جــرى منــا مخاطبــة‬\n      ‫فضيلة الشيخ ‪ ...........‬بإرفاق ما لديه وذلك بخطابنا رقم ‪341509806‬‬\n      ‫وتاريــخ ‪1434/6/21‬ه ـ فوردنــا جــواب فضيلتــه برقــم ‪341509806‬‬\n\n\n‫‪315‬‬\n\f‫وتاريــخ ‪1434/6/24‬ه ـ املرفــق بــه صــورة مــن الصــك الصــادر منــه برقــم‬\n‫‪ 32146958‬وتاريــخ ‪1432/6/28‬ه ـ كمــا أرفــق تظهيــر محكمــة‬\n‫االســتئناف بالقــرار رقــم ‪ 3362490‬وتاريــخ ‪1433/2/6‬ه ـ املتضمــن‬\n‫املصادقــة علــى احلكــم الصــادر منــه وبذلــك فإنــه لــم يظهــر لــي خــاف‬\n                                         ‫مــا حكمــت بــه واهلل املوفــق للصــواب ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n‫مــن رئيــس احملكمــة العامــة باخلــرج املكلــف الشــيخ‪........................../‬‬\n‫برقــم ‪ 34463597‬وتاريــخ ‪1434/6/25‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلتــه واملســجل برقــم ‪ 33473941‬وتاريــخ ‪1433/12/20‬ه ـ‬\n‫اخلــاص بدعــوى‪ ............../‬ضــد‪ .................../‬يف مبلــغ مالــي علــى الصفــة‬\n‫املوضحــة بالصــك واملتضمــن حكــم فضيلتــه كمــا هــو موضــح يف‬\n‫الصــك وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لــم يظهــر مايوجــب االعتــراض علــى احلكــم‪ .‬واهلل املوفق وصلى‬\n                                    ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                         ‫‪316‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":309,"source_page_end":316,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7850453ced637e1e9c0d69b1919e7c994a3d4a653499ebd2b8b75459a9d855d8","normalized_text_hash":"82ff9b6de07c33dc07f14a5f1d42e7c5925e93a85f9d18f0fbea6b9d54b5da17","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p309-33473941"},{"id":"7a2b8967-7d08-5acc-92e4-6fb6d5a6bf48","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -اعتداء على أرض بوضع كيبل -مطالبة باإلزالة والتعويض يف اتعاب التقاضي -دفع بوجود ترخيص من جهة مخولة وطلب الرجوع للجهة املانحة للترخيص -تقرير أهل اخلبرة -احلكم على املباشر واملستفيد -إلزام املدعى عليها باإلزالة والتعويض.","document_number":"34241641","case_number":"346844","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":"الدائرة احلقوقية الرابعة يف محكمة الاستئناف مبكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/14","year":"1434","subject":"عقار -اعتداء على أرض بوضع كيبل -مطالبة باإلزالة والتعويض يف اتعاب التقاضي -دفع بوجود ترخيص من جهة مخولة وطلب الرجوع للجهة املانحة للترخيص -تقرير أهل اخلبرة -احلكم على املباشر واملستفيد -إلزام املدعى عليها باإلزالة والتعويض.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34241641:‬تاريخه ‪1434/06/14:‬ه‬\n                           ‫رقم الدعوى ‪346844:‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34297233:‬تاريخه‪1434/08/15:‬هـ‬\n\n\n      ‫عقــار ‪ -‬اعتــداء علــى أرض بوضــع كيبــل ‪ -‬مطالبة باإلزالة والتعويض‬\n      ‫يف اتعــاب التقاضــي ‪ -‬دفــع بوجــود ترخيــص مــن جهــة مخولــة وطلــب‬\n      ‫الرجــوع للجهــة املانحــة للترخيــص ‪ -‬تقريــر أهــل اخلبــرة ‪ -‬احلكــم‬\n         ‫علــى املباشــر واملســتفيد ‪ -‬إلــزام املدعــى عليهــا باإلزالــة والتعويــض‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه‪.‬‬\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد أحــد مشــغلي شــبكة االتصــاالت بأنهــا‬\n      ‫اعتــدت علــى جهــة مــن أرضــه حيــث أدخلــت يف أرضــه كيبــا وطلــب‬\n      ‫إلــزام الشــركة بإزالتــه وتعويضــه عــن فتــرة بقــاء الكيبــل يف أرضــه‬\n      ‫وأجــرة أتعابــه يف القضيــة ‪ -‬أقــر وكيــل املدعــى عليهــا بوجــود الكيبــل‬\n      ‫ودفــع بــأن موكلتــه ال تقــوم بذلــك إال بنــاء علــى ترخيــص مــن وزارة‬\n      ‫النقــل وأنهــا ال تعلــم إن كان الكيبــل يختــرق أرضــه أم ال وأن عليــه‬\n      ‫أن يثبــت بــأن موكلتــه جتــاوزت حــدود الترخيــص املمنــوح لهــا ليســتحق‬\n      ‫مــا يدعيــه ‪ -‬أبــرز املدعــي صــك امللكيــة وجــرى االستفســار عــن ســجله‬\n      ‫فظهــر بأنــه ســاري املفعــول ‪ -‬جــرت الكتابــة لهيئــة اخلبــراء للتحقــق مــن‬\n\n‫‪317‬‬\n\f‫اختــراق الكيبــل ألرض املدعــي فعــادت اإلفــادة بأنــه جــرى الشــخوص‬\n‫للموقــع وبتطبيــق الصــك ظهــر بــأن الكيبــل يختــرق أرض املدعــي‬\n‫جــرى تقديــر األجــرة الشــهرية املســتحقة للمدعــي أمــا تقديــر أجــرة‬\n‫أتعابــه فيتعــذر عليهــم ذلــك حتــى االنتهــاء مــن القضيــة ‪ -‬بعــرض القــرار‬\n‫علــى املدعــي قــرر القناعــة بــه أمــا وكيــل املدعــى عليهــا فقــد طلــب‬\n‫صــرف النظــر عــن دعــوى املدعــي وإفهامــه بــأن لــه الرجــوع علــى اجلهــة‬\n‫املانحــة للترخيــص ‪ -‬قــرر املدعــي بأنــه يقصــر مطالبتــه بإزالــة الكيبــل‬\n‫وتعويضــه عــن الفتــرة املاضيــة ‪ -‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وملصادقــة املدعــى عليــه علــى أن الكيبــل يعــود ملوكلتــه وأنــه‬\n‫مت وضعــه يف املــدة التــي ذكــر املدعــي بنــاء علــى ترخيــص وزارة النقــل‬\n‫وملــا جــاء يف قــرار قســم اخلبــراء مــن أن الكيبــل ميــر بــأرض املدعــي‬\n‫بالطــول املذكــور يف التقريــر وتقديــر أجرتــه وألن املباشــر لالعتــداء‬\n‫واملســتفيد منــه هــي املدعــى عليهــا والكيبــل يعــود لهــا والعبــرة مبــن‬\n‫باشــر االعتــداء وباحتســاب املــدة املاضيــة وجــدت اثنــن وخمســن شــهر ًا‬\n‫حتــى تاريــخ ‪1434/06/15‬ه ـ وأجرتهــا مبلــغ مائــة وثالثــن ألــف ريــال‬\n‫لــذا فقــد أفهمــت املدعــى عليــه وكالــة أنــه يلــزم موكلتــه رفــع الكيبــل‬\n‫عــن أرض املدعــي موضــع الدعــوى يف موعــد أقصــاه ‪1434/6/15‬ه ـ‬\n‫ودفــع أجــرة املــدة املاضيــة وقدرهــا مائــة وثالثــون ألــف ريــال ويف حــال‬\n‫تأخرهــا عــن رفــع الكيبــل يف املوعــد احملــدد فيلزمهــا دفــع أجرة شــهرية‬\n‫قدرهــا ألفــان وخمســمائة ريــال شــهري ًا ومبــا تقــدم حكمــت ‪ -‬وبعــرض‬\n‫ذلــك علــى الطرفــن أبــدى املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه‬\n‫فلــم يقنــع باحلكــم فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف‪.‬‬\n\n\n                                                                                   ‫‪318‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬مســاعد رئيــس احملكمــة‬\n      ‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 346844‬وتاريــخ‬\n      ‫‪1434/01/05‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3431147‬وتاريــخ‬\n      ‫‪1434/1/5‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/01/20‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر (‪ )........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )........‬كمــا حضــر (‪)........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬بالوكالــة عــن (‪)........‬‬\n      ‫ا عــن (‪ )........‬و(‪ )........‬و(‪ )........‬و(‪)........‬‬\n                                                          ‫ا عــن نفســه ووكي ـ ً‬\n                                                                               ‫أصي ـ ً‬\n      ‫و(‪ )........‬و(‪ )........‬و(‪ )........‬و(‪ )........‬و(‪ )........‬بصفتهــم مــن أعضــاء‬\n      ‫مجلــس (‪ )........‬مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف‬\n      ‫بــوزارة التجــارة والصناعــة برقــم ‪ 6827‬وتاريــخ ‪1433/10/23‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح‬\n      ‫وحضــور اجللســات وإقامــة وســماع الدعــاوى وجــرى ســؤال املدعــي عــن‬\n      ‫دعــواه فقــال لقــد قامــت املدعــى عليهــا باالعتــداء علــى أرضــي الواقعــة‬\n      ‫يف (‪ )........‬باملدينــة اململوكــة لــي بالصــك الصــادر مــن كتابــة عــدل‬\n      ‫املدينــة برقــم ‪ 5/6/215‬وتاريــخ ‪1421/4/7‬ه ـ حيــث اعتــدت علــى اجلهة‬\n      ‫اجلنوبيــة مــن أرضــي احملــدودة بطريــق ينبــع املدينــة الســريع حيــث دخلــت‬\n      ‫يف أرضــي بعمــق ثالثــة أمتــار وبطــول أربعــن متــر ًا مــن أرضــي وذلــك‬\n      ‫بوضــع كيبــل أرضــي فيهــا بتاريــخ ‪1430/2/15‬ه ـ ومــن ذلــك التاريــخ‬\n      ‫وأنــا أطالبهــم برفــع يدهــم عــن أرضــي وتعويضــي عــن ذلــك وهــم يعدونــي‬\n\n‫‪319‬‬\n\f‫بذلــك لكــن لــم يلتزمــوا بــه أطلــب إلزامهــم برفــع يدهــم عــن أرضــي‬\n‫وترحيــل الكيبــل وتعويضــي عــن أجــرة األرض للمــدة املاضيــة وأجــرة‬\n‫أتعابــي يف مطالبتهــم هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى‬\n‫عليــه أبــرز ورقــة قــال إن جوابــي مــدون فيهــا وباالطــاع عليهــا وجــدت‬\n‫تتضمــن مــا يلــي أو ًال ‪ :‬إن موكلتنــا ال ميكــن أن تقــوم بأعمــال متديــد‬\n‫الكيبــات وحفــر األراضــي العامــة دون احلصــول علــى ترخيــص صــادر‬\n‫ـاء‬\n ‫مــن اجلهــات الرســمية حيــث مت إنشــاء الكيبــل محــل هــذه الدعــوى بنـ ً‬\n‫علــى ترخيــص صــادر مــن اإلدارة العامــة للطــرق والنقــل مبنطقــة املدينــة‬\n‫املنــورة بــوزارة النقــل برخصــة رقــم ‪ 1182/06‬وتاريــخ ‪1430/02/15‬ه ـ‬\n‫واملوقعــة مــن قبــل مديــر عــام إدارة الطــرق والنقــل مبنطقــة املدينــة املنــورة‬\n‫ثاني ًا ‪ :‬إن موكلتنا حريصة كل احلرص على إعطاء كل ذي حق حقه‬\n‫عنــد ثبــوت وقــوع تتجــاوز مــن طرفهــا وضــرر فعلــي علــى الغيــر وحيــث‬\n‫أن املدعــي لــم يقــدم البينــة علــى مــا ادعــاه مــن وقــوع تعــدي مــن قبــل‬\n‫موكلتنــا علــى األرض التــي يدعــي ملكيتهــا ولــم يقــدم أي مســتندات‬\n‫يثبــت فيهــا وقــوع التعــدي الــذي يدعيــه خــال املــدة التــي يدعيهــا وحيــث‬\n‫أن موكلتنــا ممنوحــة الترخيــص املرفــق مــن وزارة النقــل والــذي يخولهــا‬\n‫صالحيــة القيــام بأعمــال متديــدات محــل الدعــوى فــإن علــى املدعــي‬\n‫إثبــات وقــوع التعــدي وإثبــات جتــاوز موكلتنــا حلــدود الترخيــص املمنــوح‬\n‫لهــا و إال فليــس لــه وجــه حــق يف توجيــه هــذا اإلدعــاء علــى موكلتنــا‬\n‫وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه واملدعــى عليهــا‬\n‫قــد اعتــدت بالطــول الــذي ذكــرت علــى أرضــي التــي أملكهــا مبوجــب‬\n‫الصــك الــذي ذكــرت وأبــرز أصــل صــك امللكيــة الصــادر مــن كتابــة‬\n‫عــدل املدينــة برقــم ‪ 5/6/215‬وتاريخــه ‪1421/04/07‬ه ـ املتضمــن‬\n\n\n                                                                                         ‫‪320‬‬\n\f      ‫متلــك املدعــي للقطعــة رقــم ‪ 1855‬مــن املخطــط رقــم ‪/1‬ف‪/1411/‬ه ـ‬\n      ‫الواقــع يف (‪/ )........‬ه ـ واحملــدودة شــما ًال القطعــة رقــم ‪ 1856‬بطــول‬\n      ‫أربعــن متــر ًا وشــرق ًا شــارع‪ 2 0‬متــر ًا بطــول عشــرين متــر ًا وغربـ ًا البعــض‬\n      ‫القطعــة رقــم ‪ 1852‬والبعــض القطعــة رقــم ‪ 1851‬بطــول عشــرين متــر ًا‬\n      ‫ومجمــوع مســاحتها ثمامنائــة متــر مربــع واملهمــش عليــه بنــزع ملكيــة‬\n      ‫جــزء مــن العقــار واقــع يف اجلهــة اجلنوبيــة وحــدود وذرعــة اجلــزء املتبقــي‬\n      ‫مــن العقــار جنوبـ ًا البعــض طريــق املدينــة ينبــع الســريع بعــرض مائــة متــر‬\n      ‫والبعــض اجلــزء املتبقــي مــن القطعــة ‪ 1856‬بطــول مــن شــرق لغــرب تســعة‬\n      ‫وعشــرين متــر ًا وســتة وســتني ســنتيمتر ثــم عشــرة أمتــار وثالثــة وتســعني‬\n      ‫ســنتيمتر وشــما ًال القطعــة رقــم ‪ 1854‬بطــول أربعــن متــر ًا وشــرق ًا شــارع‬\n      ‫عــرض عشــرين متــر بطــول أربعــة عشــر متــر ًا وخمســة عشــر ســنتيمتر‬\n      ‫وغرب ـ ًا البعــض اجلــزء املتبقــي مــن القطعــة رقــم ‪ 1852‬والبعــض القطعــة‬\n      ‫رقــم ‪ 1851‬بطــول عشــرين متــر واملســاحة اإلجماليــة ســبعمائة وخمســة‬\n      ‫عشــر متــر ًا وخمســة ســنتيمترات مربعــة كمــا أضــاف املدعــي بــأن‬\n      ‫املدعــى عليهــا قــد انحرفــت عــن املســار املخصــص لهــا مــن قبــل وزارة‬\n      ‫النقــل وهــو داخــل حــرم الطريــق وخرجــت عــن ذلــك ودخلــت يف أرضــي‬\n      ‫بعمــق ثالثــة أمتــار هكــذا قــرر ثــم طلــب الطرفــان الكتابــة لقســم‬\n      ‫اخلبــراء للوقــوف علــى املوقــع وتطبيــق صــك املدعــي واإلفــادة عمــا ذكره‬\n      ‫املدعــي والتأكــد مــن مــكان الكيبــل وهــل هــو داخــل أرض املدعــي أم‬\n      ‫يف اجلــزء املنــزوع منــه لصالــح حــرم الطريــق ثــم يف جلســة أخــرى وردتنــا‬\n      ‫إفــادة قســم اخلبــراء رقــم ‪ 3431147‬وتاريــخ ‪1434/04/03‬ه ـ املتضمــن‬\n      ‫أنــه أثنــاء الوقــوف علــى الطبيعــة كان الكيبــل مدفون ـ ًا ومت حتديــد‬\n      ‫مســاره مــن قبــل منــدوب شــركة (‪ )........‬املشــارك واتضــح مــن ذلــك أنــه‬\n\n\n‫‪321‬‬\n\f‫ميــر داخــل أرض املدعــي وباالطــاع علــى طيــات املعاملــة وجــد خطــاب‬\n‫مديــر عــام إدارة الطــرق والنقــل مبنطقــة املدينــة املنــورة رقــم ‪672706‬‬\n‫يف ‪1432/01/25‬ه ـ املتضمــن أن الكيبــل مــدار الدعــوى يختــرق أرض‬\n‫املدعــي بعمــق ( ‪70‬ســم ) ومســافة ( ‪20‬م ) لــذا تقــدر األجــرة الشــهرية‬\n‫للجــزء املتعــدى عليــه مببلــغ وقــدره ألفــن وخمســمائة ريــال أمــا تقديــر‬\n‫األتعــاب يحتــاج إلــى معرفــة عــدد اجللســات التــي حضرهــا املدعــي أو‬\n‫وكيلــه حتــى انتهــت الدعــوى ليتــم التقديــر علــى ضــوء ذلــك حتري ـ ًا‬\n‫للدقــة وبــراءة لذمــة هــذا وبــاهلل التوفيــق وبعــرض ذلــك علــى الطرفــن‬\n‫قــال املدعــى عليــه ســأرجع ملوكلــي يف ذلــك وأجيبكــم يف اجللســة‬\n‫القادمــة وقــال املدعــي مــا ذكــره قســم اخلبــراء بنــاء علــى مــا جــاء يف‬\n‫خطــاب وزارة النقــل املشــار إليــه مــن أن مســافة الكيبــل عشــرين متــر ًا‬\n‫فقــط فهــذا غيــر صحيــح ألن أرضــي عبــارة عــن قطعتــن مجمــوع طولهــا‬\n‫أربعــن متــر ًا كمــا أنــه يدخــل يف أرضــي بعمــق ثالثــة أمتار تقريبـ ًا وليس‬\n‫كمــا ذكــر خطــاب وزارة النقــل الــذي اعتمــد عليــه قســم اخلبــراء لــذا‬\n‫أطلــب إعــادة النظــر يف ذلــك والتحقــق مــن ذلــك مــن قبــل قســم اخلبــراء‬\n‫ويف تقديــر األجــرة بنــاء علــى اختــاف املســاحة التــي اختزلهــا الكيبــل‬\n‫مــن أرضــي وللكتابــة لقســم اخلبــراء للتحقــق ممــا ذكــره املدعــي مــن‬\n‫طــول املســاحة التــي اختزلهــا الكيبــل مــن أرض املدعــي وإعــادة النظــر‬\n‫يف التقديــر بنــاء علــى ذلــك رفعــت اجللســة كذلــك كمــا طلبــت مــن‬\n‫املدعــى عليــه إحضــار مهنــدس مختــص لتحديــد مســار الكيبــل أثنــاء‬\n‫الوقــوف مــع قســم اخلبــراء فاســتعد بذلــك ثــم يف جلســة أخــرى حضــر‬\n‫الطرفــان وقــد جــرى االستفســار عــن ســريان مفعــول صــك املدعــي‬\n‫فوردنــا اجلــواب مــن كتابــة العــدل باملدينــة املنــورة برقــم ‪34485079‬‬\n\n\n                                                                                    ‫‪322‬‬\n\f      ‫وتاريــخ ‪1434/3/1‬ه ـ املتضمــن أن الصــك مطابــق لســجله وســاري‬\n      ‫املفعــول كمــا وردنــا خطــاب قســم اخلبــراء رقــم ‪ 34/31147‬وتاريــخ‬\n      ‫‪1434/5/27‬ه ـ املتضمــن أنــه مت الوقــوف مــرة أخــرى علــى املوقــع مــدار‬\n      ‫الدعــوى مــع املدعــي واملدعــى عليــه ميثلهــم مندوبهــم (‪)........‬حيــث أحضر‬\n      ‫جهــاز لتحديــد مســار الكيبــل وكذلــك قــام باحلفــر حتــى ظهــر الكيبل‬\n      ‫علــى الطبيعــة وتبــن لنــا أنــه ميــر داخــل احلــد اجلنوبــي وبطــول أربعــن متــر ًا‬\n      ‫علــى امتــداد احلــد إال أن التقديــر الــوارد يف القــرار الســابق املرفــق رقــم‬\n      ‫‪ 34/31147‬يف ‪1434/3/18‬ه ـ جــاء بعــد الوقــوف واملعاينــة مــع املدعــي‬\n      ‫ومنــدوب الشــركة وعمــل بذلــك محضــر معاينــة مرفــق موقــع مــن قبــل‬\n      ‫املشــاركني وكذلــك مت علــى أســاس مــا جــاء يف قرارنــا املرفــق املــؤرخ‬\n      ‫يف ‪1434/2/25‬ه ـ واعتــراف منــدوب شــركة (‪ )........‬وإشــارة احلســية‬\n      ‫التــي حــدد مبوجبهــا أن مســار الكيبــل يختــرق أرض املدعــي علــى طــول‬\n      ‫احلــد اجلنوبــي ولــم يتــم التقديــر علــى أن املســاحة عشــرون متــر ًا ‪ ،‬أمــا‬\n      ‫بالنســبة إلــى اإلشــارة إلــى خطــاب إدارة الطرق والنقــل رقم ‪ 672706‬يف‬\n      ‫‪1432/8/25‬ه ـ كمســتند أن الكيبــل ميــر بــأرض املدعــي ألن الكيبــل‬\n      ‫كان مدفون ـ ًا وال يوجــد آثــار للحفــر حــن الوقــوف لــذا نــرى أن مبلــغ‬\n      ‫ألفــن وخمســمائة ريــال أجــرة شــهرية لكامــل اجلــزء املتضــرر مــن أرض‬\n      ‫املدعــي مناســب وكايف واهلل املوفــق وبعــرض ذلــك علــى الطرفــن قــال‬\n      ‫املدعــي إننــي قانــع مبــا جــاء يف التقريــر وإن كنــت أراه أقــل مــن التقديــر‬\n      ‫املســتحق كمــا قــرر املدعــى عليه وكالــة أن موكلته ال اعتراض لديها‬\n      ‫علــى قيمــة التقديــر وموضــع الكيبــل وأنــه ميــر بــأرض املدعــي وأضــاف‬\n      ‫لكــن موكلتــي قامــت بتنفيــذ الكيبــل بنــاء علــى ترخيــص وزارة النقــل‬\n      ‫وتــرى أن دعــوى املدعــي تتوجــه علــى وزارة النقــل هكــذا أجــاب ثــم‬\n\n\n‫‪323‬‬\n\f‫قــال املدعــي إننــي أقصــر مطالبتــي يف الوقــت احلاضــر علــى طلــب رفــع‬\n‫الكيبــل عــن األرض ودفــع األجــرة للمــدة املاضيــة وأمــا املطالبــة بأجــرة‬\n‫أتعابــي يف مطالبتهــم فأرجئهــا حتــى انتهــاء القضيــة ألطالــب بهــا بدعــوى‬\n‫مســتقلة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة املدعــى‬\n‫عليــه علــى أن الكيبــل يعــود ملوكلتــه وأنــه مت وضعــه يف املــدة التــي‬\n‫ذكــر املدعــي بنــاء علــى ترخيــص وزارة النقــل وملــا جــاء يف قــرار قســم‬\n‫اخلبــراء مــن أن الكيبــل ميــر بــأرض املدعــي بالطول املذكــور يف التقرير‬\n‫وأن أجرتــه كمــا ذكــر بعاليــه وألن املباشــر لالعتــداء واملســتفيد منــه‬\n‫هــي املدعــى عليهــا والكيبــل يعــود لهــا والعبــرة مبــن باشــر االعتــداء‬\n‫وباحتســاب املــدة املاضيــة وجــدت اثنــن وخمســن شــهر ًا حتــى تاريــخ‬\n‫‪1434/06/15‬ه ـ وأجرتهــا مبلــغ مائــة وثالثــن ألــف ريــال لــذا فقــد‬\n‫أفهمــت املدعــى عليــه وكالــة أنــه يلــزم موكلتــه رفــع الكيبــل عــن‬\n‫أرض املدعــي موضــع الدعــوى يف موعــد أقصــاه ‪1434/6/15‬ه ـ ودفــع‬\n‫أجــرة املــدة املاضيــة وقدرهــا مائــة وثالثــون ألــف ريــال ويف حــال تأخرهــا‬\n‫عــن رفــع الكيبــل يف املوعــد احملــدد فيلزمهــا دفــع أجــرة شــهرية قدرهــا‬\n‫ألفــان وخمســمائة ريــال شــهري ًا ومبــا تقــدم حكمــت وبعــرض ذلــك علــى‬\n‫الطرفــن أبــدى املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه فلــم يقنــع‬\n‫باحلكــم وطلــب االســتئناف وأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/06/07‬ه‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ )........‬القاضــي باحملكمــة العامــة باملدينــة املنــورة والقائــم بعمــل‬\n‫املكتــب القضائــي الثانــي ففــي يــوم اخلميــس املوافــق ‪1434/09/17‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار الصــادر مــن‬\n\n\n                                                                                      ‫‪324‬‬\n\f      ‫الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫رقــم ‪ 34297233‬وتاريــخ ‪1434/08/15‬ه ـ املتضمــن مــا نصــه احلمــد‬\n      ‫هلل والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n      ‫رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫(‪ )........‬مســاعد رئيــس احملكمــة العامــة باملدينــة املنــورة ‪ /‬املســاعد‬\n      ‫واملســجل بعــدد ‪ 34241641‬وتاريــخ ‪1434/06/14‬ه ـ املتضمــن دعــوى‬\n      ‫(‪ )........‬ضــد شــركة (‪ )........‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم وبــاهلل التوفيــق اه ـ قاضــي اســتئناف (‪ )........‬قاضــي اســتئناف‬\n      ‫(‪ )........‬رئيــس الدائــرة (‪ )........‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/9/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ .:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ )........(/‬رئيــس احملكمــة العامــة باملدينــة املنورة‪/‬املســاعد‬\n      ‫واملســجل بعــدد ‪ 34241641‬وتاريــخ ‪1434/6/14‬ه ـ املتضمــن دعــوى‬\n      ‫(‪ )........‬ضــد شــركة (‪ )........‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n           ‫احلكــم‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪325‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":317,"source_page_end":325,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"be7220535e72e98ce15b2ac8b083b53da30e575251dacb980473faf3b47bc532","normalized_text_hash":"612dd7958e0663d60d1691d75089bb745391e8d63149cb2cc6e06921f308133f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p317-34241641"},{"id":"fbaed9bc-b0ed-5bd3-a7f6-9b86ae9b5c4f","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -مضاربة -مساهمة عقارية -االختاف يف احتساب نسبة األرباح يف املساهمة -بطان شرط مبلغ معن مع نسبة الربح -تكرار التخلف عن احلضور يعد قرينة على أن املتخلف عادم ا للبينة -احلكم برأس املال مع االرباح -التهميش على صك احلكم بالتنفيذ وانتهاء القضية .","document_number":"3337775","case_number":"32360972","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/13","year":"1434","subject":"عقار -مضاربة -مساهمة عقارية -االختاف يف احتساب نسبة األرباح يف املساهمة -بطان شرط مبلغ معن مع نسبة الربح -تكرار التخلف عن احلضور يعد قرينة على أن املتخلف عادم ا للبينة -احلكم برأس املال مع االرباح -التهميش على صك احلكم بالتنفيذ وانتهاء القضية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3337775 :‬تاريخه ‪1433/8/13 :‬ه ـ‬\n              ‫\t\t‬   ‫رقم الدعوى ‪32360972 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34217910‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫عقــار ‪ -‬مضاربــة ‪ -‬مســاهمة عقاريــة ‪ -‬االختــاف يف احتســاب نســبة‬\n‫األربــاح يف املســاهمة ‪ -‬بطــان شــرط مبلــغ معــن مــع نســبة الربــح‬\n‫‪ -‬تكــرار التخلــف عــن احلضــور يعــد قرينــة علــى أن املتخلــف عادم ـ ًا‬\n‫للبينــة ‪ -‬احلكــم بــرأس املــال مــع االربــاح ‪ -‬التهميــش علــى صــك‬\n                                    ‫احلكــم بالتنفيــذ وانتهــاء القضيــة ‪.‬‬\n\n\n\n\n                               ‫‪ -1‬املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n‫‪ -2‬قــال بــن قدامــه رحمــه اهلل يف املغنــى ‪ ( :‬متــى جعــل نصيــب احــد‬\n‫الشــركاء دراهــم معلومــة أو جعــل مــع نصيبــة دراهــم مثــل ان يشــترط‬\n                           ‫لنفســه جــزء وعشــرة دراهــم بطلــت الشــركة ‪).‬‬\n‫‪ -3‬قــال ابــن املنــذر ‪ ( :‬أجمــع كل مــن نحفــظ عنــه مــن اهــل العلــم علــى‬\n‫ابطــال القــراض يف املضاربــة اذا شــرط احدهمــا او كالهمــا لنفســه‬\n                                                              ‫دراهــم معلومــة )‪.‬‬\n‫‪ -4‬قــال شــيخ االســام ابــن تيميــة رحمــه اهلل ‪( :‬لــو شــرط يف املضاربــة‬\n‫لــرب املــال دراهــم معينــة فــإن هــذا االتفــاق ال يجــوز ألن املعاملــة مبناهــا‬\n‫علــى العــدل وهــذه املعامــات مــن جنــس املشــاركات واملشــاركة امنــا‬\n‫تكــون لــكل مــن الشــريكني جــزء شــائع يف الثلــث والنصــف فــإذا جعــل‬\n‫ألحدهمــا شــيء مقــدر لــم يكــن ذلــك عــد ًال بــل كان ظلمـ ًا ) ‪ .‬الفتاوى‬\n                                                                        ‫(‪.)83/28‬‬\n                                                                                        ‫‪326‬‬\n\f      ‫ادعــى املدعــى وكالــة علــى املدعــى عليــه وكالــة بــأن موكلــه ســاهم‬\n      ‫مــع املدعــى عليــه اصالــة مببلــغ أربعــة ماليــن ريــال يف مخطــط ‪.....‬‬\n      ‫مبكــة املكرمــة وبتاريــخ ‪1427/1/26‬ه ـ مت االتفــاق بــن الطرفــن‬\n      ‫علــى ان يبيــع املدعــى عليــه للمدعــى البلــك رقــم (‪ )50‬مببلــغ ثمانيــة‬\n      ‫ماليــن ومائتــي الــف وثمامنائــة وواحــد وخمســن ريــا ًال مــن مســاهمة‬\n      ‫املدعــى علــى أن يتــم االفــراغ لــه بعــد تصفيــة املســاهمة ‪ - .‬صفــى‬\n      ‫املدعــى عليــه املســاهمة مبوجــب االعــان علــى موقــع املكتــب وبلغــت‬\n      ‫نســبة األربــاح للعمــاء املســاهمني (‪ - )%167‬ذكــر املدعــى وكالــة ان‬\n      ‫ملوكلــه رأس املــال الــذي دفعــه اربعــة ماليــن ريــال مضافـ ًا إليهــا األربــاح‬\n      ‫ثمانيــة ماليــن وســتمائة واربعــة وثمانــن الــف ريــال يحســم منهــا قيمــة‬\n      ‫البلــك رقــم (‪ )50‬املذكــور وعليــه فــإن املتبقــي ملوكلــي يف ذمــة املدعــى‬\n      ‫عليــه اربعــة ماليــن واربعمائــة وثالثــة وثمانــون الفـ ًا ومائــة وأربعــون ريــاال‬\n      ‫طلــب الــزام املدعــى عليــه بســدادها ‪ - .‬اقــر املدعــى عليــه وكالــة بصحــة‬\n      ‫املســاهمة واملبلــغ املدفــوع مــن قبــل املدعــى البالــغ اربعــة ماليــن ريــال‬\n      ‫وعلــى شــراء املدعــى للبــك رقــم (‪ )50‬وعلــى نســبة األربــاح للمدعــى ‪%65‬‬\n      ‫‪ - .‬صــادق املدعــى عليــه وكالــة علــى أن نســبة األربــاح للمســاهمني‬\n      ‫بلغــت ‪ %167‬لكــن هــذه النســبة تســتحق للمســاهم الــذي ســاهم وحصــل‬\n                                     ‫علــى حصتــه نقــدا ولــم يحصــل علــى أرض ‪.‬‬\n      ‫أمــا املدعــى فقــد حصــل علــى جــزء مــن العقــار موضــع املســاهمة فهــو‬\n      ‫ال يســتحق ســوى حصتــه مــن األربــاح املتفــق عليهــا ‪ %65‬هــذا هــو‬\n      ‫املتبــع يف تصفيــة املســاهمة فــكل مــن ســاهم وحصــل علــى جــزء مــن‬\n\n‫‪327‬‬\n\f‫مســاهمته عقــار ًا مت احتســاب ارباحــه ‪ %50‬أمــا مــن حصــل علــى األربــاح‬\n‫نقــدا فنســبته ‪ - %167‬قــرر املدعــى عليــه وكالــة ان للمدعــى اصالــة‬\n‫رأس املــال الــذى دفعــه (‪ + )4.000.000‬األربــاح ‪)2.600.000(%65‬‬\n‫= (‪ )6.600.000‬يخصــم منهــا قيمــة البــك رقــم (‪ )50‬مبلغــا وقــدره‬\n‫(‪ )8.200.851‬وبالتالــي فاملســتحق للمدعــى عليــه يف ذمــة املدعــى‬\n‫(‪ - )1.600.851‬جــري ســؤال املدعــى عليــه وكالــة عــن ايضــاح ان‬\n‫نســبة االربــاح املذكــورة ‪ %167‬ال تشــمل املدعــى ‪ -‬فقــرر املدعــى عليــه‬\n‫وكالــة بقولــه ألن املدعــى أخــذ نصيبــه عقــارا ‪ -‬أنكــر املدعــى وكالــة‬\n‫ذلــك وقــرر بقولــه ان موكلــي يســتحق نســبة الربــح ‪ %167‬أســوه بقيــة‬\n‫املســاهمني ‪ -‬يف جلســة أخــري قــرر املدعــى وكالــة بــأن إجمالــي اربــاح‬\n‫املســاهمة بلغــت ‪ %334‬يســتحق املســاهمون منهــا ‪ %167‬علــى حســاب‬\n‫ان نصيبهــم هــو ‪ %50‬مــن االربــاح وموكلــي يســتحق مــن االربــاح ‪%217‬‬\n‫علــى حســاب ان نصيبــه هــو ‪ %65‬مــن األربــاح حســب االتفــاق بينــه وبــن‬\n‫املدعــى عليــه أصالــة ‪ -‬فموكلــي يســتحق نســبة الربــح مــن اجمــال‬\n‫االربــاح التــي حصلــت يف املســاهمة بخــاف مــا ذكــره املدعــى وكالــة‬\n‫أن نصيــب موكلــي ‪ %65‬مــن راس املــال ‪ -‬بعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة طلــب مهلــة للرجــوع ملوكلــه ‪ - .‬تكــرر تخلــف املدعــى‬\n‫عليــه ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه اصالــة بــان يدفــع للمدعــى‬\n‫أصالــة أربعــة ماليــن وأربعمائــة وتســعة وســبعني ألف ـ ًا ومائــة وتســعة‬\n‫وأربعــن ريــا ًال متثــل املبلــغ الباقــي بذمــة املدعــى عليــه للمدعــى مــن رأس‬\n‫املــال واألربــاح بعــد حســم قيمــة البلــك رقــم (‪ )50‬وصــرف النظــر عمــا‬\n‫زاد عــن ذلــك ممــا جــاء يف دعــوى املدعــى وكالــة ‪ -‬قــرر املدعــى وكالــة‬\n‫قناعتــه باحلكــم ‪ -‬قــدم املدعــى عليــه وكالــة الئحتــه االعتراضيــة ‪-‬‬\n\n\n                                                                                       ‫‪328‬‬\n\f      ‫صــدق احلكــم مــن محكمــة اإلســتئناف ‪ -‬ســدد املدعــى عليــه للمدعــى‬\n                ‫املبلــغ احملكــوم بــه مبوجــب شــيك وبذلــك انتهــت القضيــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32360972‬وتاريخ‪1432/08/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 321075501‬وتاريــخ ‪1432/08/19‬ه ـ حضــر‬\n      ‫‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬بالوكالــة عــن ‪...‬ســعودي بالســجل‬\n      ‫املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫ببريــدة برقــم ‪ 41261‬وتاريــخ ‪1432/08/08‬ه ـ واملخــول لــه فيهــا حــق‬\n      ‫املطالبــة واملخاصمــة واملدافعــة واملرافعــة وإقامــة الدعــاوى وحتريرهــا‬\n      ‫وقبــول احلكــم واالعتــراض عليــه وطلــب االســتئناف والصلــح كمــا‬\n      ‫حضــر حلضــوره ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬بالوكالــة عــن‬\n      ‫‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل الدرعيــة برقــم ‪ 3349075‬وتاريــخ ‪1433/01/26‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املدافعــة واملرافعــة واملخاصمــة وحضــور اجللســات‬\n      ‫وســماع الدعــاوى واإلقــرار واإلنــكار وتقــدمي البينــات وطلــب اليمــن‬\n      ‫ا (دفــع موكلــي‬   ‫واالســتئناف والقناعــة باألحــكام وادعــى األول قائ ـ ً‬\n      ‫للمدعــى عليــه مبلغ ـ ًا وقــدره أربعــة ماليــن ريــال مســاهمة يف مخطــط‬\n      ‫‪ .....‬الواقــع مبكــة املكرمــة ويف تاريــخ ‪1427/1/26‬ه ـ مت االتفــاق‬\n      ‫بــن موكلــي واملدعــى عليــه علــى أن يبيــع املدعــى عليــه ملوكلــي البلــك‬\n      ‫رقــم ‪ 50‬املســجل باســم املدعــى عليــه بالصــك رقــم ‪ 4/390/47‬مببلــغ‬\n\n‫‪329‬‬\n\f‫ثمانيــة ماليــن ومائتــي ألــف وثمامنائــة وواحــد وخمســن ريــاال حتســب‬\n‫مــن مســاهمته علــى أن يتــم اإلفــراغ لــه بعــد التصفيــة ومعرفــة مــا لــه ومــا‬\n‫عليــه حســب مــا نصــت عليــه الوثيقــة املشــار إليهــا وقــد صفــى املدعــى‬\n‫عليــه املســاهمة تصفيــة نهائيــة مبوجــب اإلعــان علــى موقــع مكتــب‬\n‫‪ ....‬بنســبة أربــاح بلغــت ‪ %167‬هــذه النســبة متثــل نصــف أربــاح مســاهمة‬\n‫العميــل واالتفــاق بــن املدعــى عليــه والعمــاء انــه يســتحق ‪ %50‬مــن‬\n‫األربــاح باســتثناء موكلــي فــإن االتفــاق بينــه وبــن املدعــى عليــه انــه‬\n‫يســتحق مــن األربــاح ‪ %65‬وبنــاء عليــه فــان أربــاح موكلــي بلغــت ثمانيــة‬\n‫ماليــن وســتمائة وأربــع وثمانــن ألف ـ ًا وبنــاء علــى االتفــاق املشــار إليــه‬\n‫فــان املتبقــي ملوكلــي مبلــغ أربعــة ماليــن وأربعمائــة وثــاث وثمانــن ألف ًا‬\n‫ومائــة وأربعــن ريــاال اطلــب إلــزام املدعى عليه بدفع هــذا املبلغ ملوكلي)‬\n‫هكــذا ادعــى وبعرضهــا علــى املدعــى عليــه وكالــة طلــب مهلــة لإلجابــة‬\n‫‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره ‪ ...‬ســعودي‬\n‫ا عــن ‪...‬ســعودي بالســجل املدنــي‬    ‫بالســجل املدنــي رقــم ‪...‬بصفتــه وكيـ ً‬\n‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العدل مبحافظــة الدرعية‬\n‫برقــم ‪ 3349075‬وتاريــخ ‪1433/01/26‬ه ـ واملخــول لــه فيها حق املطالبة‬\n‫واملرافعــة واملخاصمــة واإلقــرار واإلنــكار وقبــول احلكــم واالعتــراض‬\n‫عليــه واالســتالم ثــم ســألت املدعــي وكالــة عــن تفصيــل املبلــغ املطالــب‬\n‫بــه فقــال إنــه ميثــل رأس املــال مــع الباقــي مــن األربــاح هكذا قــال وبعرض‬\n‫الدعــوى علــى املدعــى عليــه وكالــة قــال ســوف أجيب يف اجللســة القادمة‬\n‫وقــال أطلــب مــن املدعــي وكالــة تســليمي صــورة مــن ســند املســاهمة ‪،‬‬\n‫ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه وكالــة الثانــي‬\n‫وبســؤال املدعــى عليــه وكالــة عــن جوابــه علــى الدعــوى قــال ‪ :‬إن جوابي‬\n\n\n                                                                                        ‫‪330‬‬\n\f      ‫يتلخــص يف هــذه املذكــرة ثــم أبــرز ورقتــن جــاء فيهــا (نــرد علــى مــا جــاء‬\n      ‫بدعــوى املدعــي أنــه صحيــح مســاهم مــع موكلــي باملبلــغ الــذي ذكــره‬\n      ‫يف دعــواه وهــو (‪ )4,000,000‬أربعــة ماليــن ريــال وصحيــح أنــه اشــترى‬\n      ‫البلــك رقــم ‪ 50‬وأنــه اتفــق علــى اســتحقاقه ‪ %65‬أرباحـ ًا ممــا يتحقــق مــن‬\n      ‫الربــح علــى رأس مالــه بــد ًال مــن ‪ %50‬وموكلــي ال ميانــع لــه يف ذلــك ونــود‬\n      ‫أن نوضــح لفضيلتكــم أن مــا ذكــره مــن أن األربــاح بلغــت ‪ %167‬فهــذا‬\n      ‫صحيــح ولكــن هــذه النســبة تســتحق للمســاهم الــذي ســاهم وحصــل‬\n      ‫علــى حصتــه نقــد ًا ولــم يحصــل علــى أراضــي مــن املســاهمة وحصــل‬\n      ‫علــى حصــة مــن األربــاح نقــد ًا أمــا حــال املدعــي يختلــف حيــث حصــل‬\n      ‫علــى جــزء مــن العقــار موضــوع املســاهمة فاألمــر هنــا يختلــف حيــث ال‬\n      ‫يســتحق ســوى حصتــه مــن األربــاح املتفــق عليــه وهــي ‪ %65‬وهــذا هــو‬\n      ‫املتبــع يف تصفيــة املســاهمة فــكل مــن ســاهم وحصــل علــى جــزء مــن‬\n      ‫مســاهمته عقــار مت احتســاب أرباحــه‪ %50‬ونرفــق لفضيلتكــم مجموعــة‬\n      ‫مــن املســاهمني وتصفيــة مســاهماته التــي تؤكــد حصولهــم علــي نســبة‬\n      ‫‪ %50‬فقــط مــن األربــاح أمــا مــن حصــل علــى أربــاح نقــد ًا فقــد حصــل‬\n      ‫عليهــا بنســبة أربــاح ‪ %167‬وهــذا أمــر طبيعــي فهــب أن كل املســاهمني‬\n      ‫حصلــوا علــى مقابــل مســاهمتهم أســهم مــن العقــار فمــن أيــن تأتــي‬\n      ‫األربــاح فاألربــاح تأتــي مــن بيــع العقــار أو جــزء منــه أو تصفيتــه فاملدعــي‬\n      ‫يســتحق أرباحـ ًا مقدارهــا (‪ )2,600,000‬التــي متثــل (‪ )%65‬من مســاهمته‬\n      ‫ومقدارهــا (‪ )4,000,000‬وبالتالــي يكــون للمدعــي قيمــة مســاهمته‬\n      ‫مــع أرباحهــا مبلغـ ًا مقــداره (‪)6,600,000 = 2,600,000 + 4,000,000‬‬\n      ‫يخصــم منــه قيمــة البلــك رقــم (‪ )50‬مبلــغ وقــدره (‪ )8.200.851‬ثمانيــة‬\n      ‫ماليــن ومائتــي ألــف وثمامنائــة وواحــد وخمســن ريــا ًال ‪ ،‬وبالتالــي يصبــح‬\n\n\n‫‪331‬‬\n\f‫مســتحق ًا للمدعــى عليــه مبلغ ـ ًا مقــداره (‪ )1.600.851‬مليون ـ ًا وســتمائة‬\n‫ألــف وثمامنائــة وواحــد وخمســن ريــا ًال ‪ .‬وال مانــع لــدى موكلنــا يف‬\n‫حــال ســدادها أن يفــرغ لــه األرض موضــوع املســاهمة) فســألت املدعــى‬\n‫عليــه وكالــة هــل اشــترى مــوكل املدعــي األرض بالقيمــة التــي ذكــر‬\n‫فقــال ‪ :‬نعــم ثــم طلــب منــه إيضــاح مــا ذكــره يف جوابــه مــن أن نســبة‬\n‫الربــح املذكــورة يف الدعــوى ال تشــمل املدعــي فقــال ‪ :‬إن نســبة الربــح‬\n‫املذكــورة ال تشــمل املدعــي لكونــه أخــذ نصيبــه عقــار ًا وبالتالــي فــإن‬\n‫نظــام تلــك املســاهمة ينبنــي علــى أن مــن أخــذ جــزء ًا مــن نصيبــه عقــار ًا‬\n‫فإنــه ال يحســب عليــه بنفــس نســبة الربــح هكــذا قــال فســألته عــن نســبة‬\n‫الربــح التــي يســتحقها مــوكل املدعــي فقــال ‪ :‬إن نســبة الربــح ‪%65‬‬\n‫هكــذا قــال وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬إن مــا ذكــره‬\n‫غيــر صحيــح ومــا ذكــره مــن أن ذلــك هــو نظــام املســاهمة فهــذا غيــر‬\n‫صحيــح أيض ـ ًا وموكلــي يســتحق نســبة الربــح أســوة ببقيــة الشــركاء‬\n‫وأما النســبة التي ذكر فهي نســبة تقســيم الربح بني املســاهم وصاحب‬\n‫املســاهمة هكــذا قــال فســألت املدعــى عليــه وكالــة عمــا ذكــره مــن‬\n‫أن ذلــك هــو نظــام املســاهمة هــل كان ذلــك بعلــم مــوكل املدعــي فقــال‬\n‫‪ :‬ســوف أراجــع موكلــي وأجيــب يف اجللســة القادمــة ‪ ،‬ويف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وبســؤال املدعــى عليــه‬\n‫وكالــة عــن جوابــه علــى مــا طلــب منــه يف اجللســة املاضيــة مــن أن االتفــاق‬\n‫الــذي ذكــره بخصــوص تقديــر نســبة الربــح كان بعلــم املدعــي فقــال ‪:‬‬\n‫إننــي لــم أمتكــن مــن إحضــار اإلجابــة وســوف أجيــب يف اجللســة القادمــة‬\n‫هكــذا قــال ثــم ســألت املدعــي وكالــة عــن قصــده بقولــه يف اجللســة‬\n‫املاضيــة إن موكلــه يســتحق نســبة أســوة ببقيــة الشــركاء فقــال ‪ :‬إن‬\n\n\n                                                                                      ‫‪332‬‬\n\f      ‫األمــر يحتــاج إلــى إيضــاح وهــو أن نســبة أربــاح األرض كاملــة بلغــت ‪334‬‬\n      ‫‪ %‬يســتحق املســاهمون منهــا ‪ %167‬علــى حســاب أن نصيبهــم هــو ‪%50‬‬\n      ‫مــن الربــح بينمــا موكلــي يســتحق منهــا ‪ %217‬علــى حســاب أن نصيبــه‬\n      ‫هــو ‪ %65‬مــن الربــح حســب االتفــاق الــذي مت بينــه وبــن مــوكل املدعــى‬\n      ‫عليــه وأنــا أقصــد أن موكلــي يســتحق نســبة الربــح مــن إجمالــي األربــاح‬\n      ‫التــي حصلــت يف تلــك املســاهمة ومــا ذكــره املدعــى عليــه وكالــة مــن‬\n      ‫أن نصيــب موكلــي هــو ‪ %65‬مــن رأس املــال فهــذا غيــر صحيــح إذ أن‬\n      ‫تلــك النســبة هــي نســبة تقاســم األربــاح وليســت نســبة الربــح واملســاهمة‬\n      ‫كمــا ذكــرت قــد ربحــت ‪ %334‬فكيــف يتــم حســاب نســبة موكلــي‬\n      ‫علــى هــذا النحــو ‪ ،‬هــذا مــا أردت إيضاحــه هكــذا قــال ‪ ،‬وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬ســوف أرجــع ملوكلــي وأجيــب يف‬\n      ‫اجللســة القادمــة ‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة ولــم يحضــر‬\n      ‫املدعــى عليــه وال وكيلــه رغــم تبلــغ الوكيــل باملوعــد يف اجللســة املاضيــة‬\n      ‫وقــد وردنــا خطــاب بشــرح فضيلــة الرئيــس رقــم ‪ 33/1523906‬مــدون‬\n      ‫مــن قبــل املدعــى عليــه وكالــة وقــد تضمــن رغبتــه يف تأجيــل املوعــد‬\n      ‫إلــى شــهر رمضــان حملاولــة الصلــح بــن الطرفــن هــذا وبعــرض ذلــك‬\n      ‫علــى املدعــي وكالــة قــال ‪ :‬أنــا ال أوافــق علــى تأجيــل اجللســة وأطلــب‬\n      ‫االســتمرار يف نظرهــا لــذا قــررت إكمــال نظــر الدعــوى غيابيـ ًا اســتناد ًا‬\n      ‫للمــادة (‪ )55‬مــن نظــام املرافعــات وبعــد التأمــل فيمــا ســبق مــن الدعــوى‬\n      ‫واإلجابــة وحيــث أقــر املدعــى عليــه وكالــة بصحــة مســاهمة مــوكل‬\n      ‫املدعــي مــع موكلــه باملبلــغ املذكــور وأنــه اشــترى األرض املذكــورة‬\n      ‫بالقيمــة املذكــورة وأقــر بصحــة نســبة الربــح التــي يســتحقها العميــل‬\n      ‫يف املســاهمة ودفــع بــأن مــوكل املدعــي ال يســتحق هــذه النســبة نظــر ًا‬\n\n\n‫‪333‬‬\n\f‫الحتســاب تلــك األرض مــن ضمــن أرباحــه وأن االتفــاق جــرى علــى ذلــك‬\n‫ولكــون ذلــك خــاف األصــل ومبــا أن املدعــى عليــه قــد تخلــف عــن‬\n‫احلضــور يف هــذه اجللســة وهــو بهــذا يعــد عادمـ ًا للبينــة علــى ذلــك الدفــع‬\n‫‪ -1‬لــذا فقــد ثبــت لــدي مــا يلــي ‪ :‬أن بذمــة مــوكل املدعــى عليــه ملــوكل‬\n‫املدعــي مبلــغ أربعــة ماليــن وأربعمائــة وتســعة وســبعني ألف ـ ًا ومائــة‬\n‫وتســعة وأربعــن ريــا ًال متثــل املبلــغ الباقــي بذمــة مــوكل املدعــى عليــه مــن‬\n‫رأس املــال واألربــاح بعــد حســم قيمــة األرض‪ -2 .‬رددت دعــوى املدعــي‬\n‫فيمــا زاد علــى ذلــك وحكمــت بذلــك وهــذا احلكــم يعــد حضوريـ ًا بحــق‬\n‫املدعــى عليــه وبعــرض ذلــك علــى املدعــي وكالــة قــرر القناعــة وســوف‬\n‫يتــم تبليــغ املدعــى عليــه باحلكــم بواســطة احملضريــن ‪ ،‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1433/08/13‬ه ـ‬\n‫(قــال ابــن قدامــة رحمــه اهلل يف املغنــي ( متــى جعــل نصيــب أحــد‬\n‫الشــركاء دراهــم معلومــة أو جعــل مــع نصيبــه دراهــم مثــل أن يشــترط‬\n‫لنفســه جــزء وعشــرة دراهــم بطلــت الشــركة قــال ابــن املنــذر أجمع كل‬\n‫مــن نحفــظ عنــه مــن أهــل العلــم علــى إبطــال القــراض يعنــي املضاربــة إذا‬\n                    ‫شــرط أحدهمــا أو كالهمــا لنفســه دراهــم معلومــة )‬\n‫قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل ( لــو شــرط يف املضاربــة لــرب‬\n‫املال دراهم معينة فإن هذا االتفاق ال يجوز باالتفاق ألن املعاملة مبناها‬\n‫علــى العــدل وهــذه املعامــات مــن جنــس املشــاركات واملشــاركة إمنــا‬\n‫تكــون لــكل مــن الشــريكني جــزء شــائع يف الثلــث والنصــف فــإذا‬\n‫جعــل ألحدهمــا شــيء مقــدر لــم يكــن ذلــك عــد ًال بــل كان ظلمـ ًا ) ا‪.‬ه ـ‬\n‫‪ 83/28‬وحيــث إن رأس املــال قــدره أربعــة ماليــن ريــال وربــح مــوكل‬\n\n\n                                                                                         ‫‪334‬‬\n\f      ‫املدعــي هــو ‪ %217‬وهــو مــا ميثــل ‪ %65‬مــن إجمالــي الربــح البالــغ ‪%334‬‬\n      ‫ليكــون إجمالــي الربــح ثمانيــة ماليــن وســتمائة وثمانــن ألــف ريــال‬\n      ‫(‪ )8680000‬ريــال وبإضافــة رأس املــال يكــون إجمالــي املبلــغ اثنــي‬\n      ‫عشــر مليون ـ ًا وســتمائة وثمانــن ألــف ريــال (‪)12680000‬ريــال يحســم‬\n      ‫منهــا قيمــة األرض ليكــون الباقــي أربعــة ماليــن وأربعمائــة وتســعة‬\n                                     ‫وســبعني ألف ـ ًا ومائــة وتســعة وأربعــن ريــاالً‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االحــد حضــر املدعــي اصالــة ‪... ...‬كما‬\n      ‫حضــر املدعــى عليــه وكالــة ‪...‬وســلم املدعــى عليــه للمدعــي أصالــة يف‬\n      ‫مجلــس احلكــم الشــيك املســحوب علــى البنــك ‪...‬برقــم ‪ 2572‬و تاريــخ‬\n      ‫‪ 2013/5/25‬م بكامــل املبلــغ احملكــوم بــه وقــدره أربعــة ماليــن‬\n      ‫وأربعمائــة وتســعة وســبعون ألفــا ومائــة وتســعة وأربعــون ريــاال وقــرر‬\n      ‫املدعــي أصالــة باســتالمه وحتــى ال يخفــى جــرى احلاقــه و بهــذا تعتبــر‬\n      ‫القضيــة منتهيــة و بــاهلل التوفيــق و صلــى اهلل و ســلم علــى نبينــا محمــد‬\n                                                         ‫حــرر يف ‪1434/7/16‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 332053967‬وتاريــخ ‪1434/2/18‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪... /‬املســجل برقــم ‪33377750‬‬\n      ‫وتاريــخ ‪1433/8/13‬ه ـ اخلــاص بدعــوى‪... /‬وكيــا عــن ‪ ...‬ضــد‪...... /‬‬\n      ‫وكيــا عــن ‪...‬يف مبلــغ مالــي قيمــة مســاهمة علــى النحــو املوضــح يف‬\n      ‫الصــك املتضمــن أنــه ثبــت لــدى فضيلتــه مــا يلــي‪ -1 :‬أن بذمــة مــوكل‬\n      ‫املدعــى عليــه ملــوكل املدعــي مبلــغ أربعــة ماليــن وأربعمائــة وتســعة‬\n\n\n‫‪335‬‬\n\f‫وســبعني ألف ـ ًا ومائــة وتســعة وأربعــن ريــا ًال متثــل املبلــغ الباقــي بذمــة‬\n‫املدعــى عليــه مــن رأس املــال واألربــاح بعــد حســم قيمــة األرض‪ -2 .‬رد‬\n‫دعــوى املدعــي فيمــا زاد علــى ذلــك وحكــم بذلــك وهــذا احلكــم يعــد‬\n‫حضوري ـ ًا بحــق املدعــى عليــه‪ ،‬وحيــث ســبقت دراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا‬\n‫أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا املشــار إليــه‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اجلــواب األخيــر ‪.‬واهلل املوف ــق وصلــى‬\n                                ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":326,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7903d1b315346e2f68b7dd8f12cd34152ffffa24a3ca8713eea392df99c4aba","normalized_text_hash":"eb1a030cc48bc7410cf31e8c5bb2bf3e0e3438d834818310e43eb99fae076aee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p326-3337775"},{"id":"7db503ed-5ba0-5b31-b311-d03ebc2f73ef","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء أرض بالتقسيط -رهن الصك حلن استالم كامل املبلغ -بيع العقار ورهنه للبائع -طلب تسليم املبيع -الشرط املنايف ملقصود العقد -شهادة الشهود وحلف اليمن -احلكم على املدعى عليه بتسليم األرض وعلى املدعى رد الثمن احلال -تنفيذ احلكم .","document_number":"3424705","case_number":"3372501","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/27","year":"1434","subject":"عقار -شراء أرض بالتقسيط -رهن الصك حلن استالم كامل املبلغ -بيع العقار ورهنه للبائع -طلب تسليم املبيع -الشرط املنايف ملقصود العقد -شهادة الشهود وحلف اليمن -احلكم على املدعى عليه بتسليم األرض وعلى املدعى رد الثمن احلال -تنفيذ احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3424705 :‬تاريخه ‪1434/1/27 :‬هـ‬\n                        ‫رقم الدعوى ‪3372501 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34301076‬تاريخه‪1434/08/21 :‬هـ‬\n\n\n      ‫عقــار‪ -‬شــراء أرض بالتقســيط ‪ -‬رهــن الصــك حلــن اســتالم كامــل‬\n      ‫املبلــغ‪ -‬بيــع العقــار ورهنــه للبائــع‪ -‬طلــب تســليم املبيــع‪ -‬الشــرط املنــايف‬\n      ‫ملقصــود العقــد‪ -‬شــهادة الشــهود وحلــف اليمــن‪ -‬احلكــم علــى املدعــى‬\n      ‫عليــه بتســليم األرض وعلــى املدعــى رد الثمــن احلــال‪ -‬تنفيــذ احلكــم ‪.‬‬\n\n\n\n\n                        ‫قولة صلى اهلل عليه وسلم ( املسلمون على شروطهم )‬\n\n\n\n\n      ‫ادعــى املدعــى بأنــه اشــتري مــن املدعــى عليــه قطعــة أرض ( ذكــر‬\n      ‫وصفهــا ) باألقســاط تدفــع عــن طريــق شــيكات للمدعــى عليــه علــى‬\n      ‫أن ال يصــرف املدعــى عليــه الشــيك إال يف تاريــخ القســط وعلــى أن يقــوم‬\n      ‫املدعــى بتســديد رســوم البلديــة وعلــى أن يبقــي الصــك مرهون ـ ًا لــدى‬\n      ‫املدعــى عليــه فــا يفــرغ إال حــن اســتالم كامــل املبلــغ وعلــى أن يســتلم‬\n      ‫املشــترى ( املدعــى ) املبيــع األرض املذكــورة مــن ســاعة التعاقــد‪ -‬لــم‬\n      ‫يســلم املدعــى عليــه األرض للمدعــى‪ -‬طلــب املدعــى إلــزام املدعــى عليــه‬\n      ‫بتســليم األرض موضــع الدعــوى‪ -‬أقــر املدعــى عليــه بالدعــوى وذكــر‬\n      ‫بــأن ســبب عــدم تســليمه لــأرض هــو أنــه اشــترط أن تكــون الشــيكات‬\n      ‫مصدقــه وأن تكــون باســم املؤسســة اخلاصــة باملدعــى‪ -‬أنكــر املدعــى‬\n\n‫‪337‬‬\n\f‫هــذا الشــرط‪ -‬احضــر املدعــى عليــه ثالثــة شــهود وشــهادتهم غيــر‬\n‫موصلــة‪ -‬أحضــر املدعــى ثالثــة شــهود وشــهادتهم موصلــه وجــرى‬\n‫تعديلهــم‪ -‬أبــرز املدعــى عقــد البيــع ورصــد مضمونــة وليــس فيــه‬\n‫اشــتراط تصديــق الشــيكات‪ -‬أقــر املدعــى عليــه بصحــة عقــد البيــع‬\n‫املذكــور‪ -‬طلــب املدعــى عليــه ميــن املدعــى علــى نفــي اشــتراط تصديــق‬\n‫الشــيكات‪ -‬حلــف املدعــى اليمــن‪ -‬حيــث إن اشــتراط تصديــق‬\n‫الشــيكات ينــايف املقصــود مــن تقســيط املبلــغ وألن املســلمون علــى‬\n‫شــروطهم صــدر احلكــم بإلــزام املدعــى عليــه بتســليم األرض موضــع‬\n‫الدعــوى للمدعــي وإلــزام املدعــى بــأن يســلم للمدعــى عليــه األقســاط‬\n‫احلالــة وافهــام املدعــى بــأن لــه مطالبــة املدعــى عليــه بأجــره املثــل مــن‬\n‫تاريــخ العقــد إلــى حــن اســتالم األرض‪ -‬اعتــرض املدعــى عليــه علــى‬\n‫احلكــم‪ -‬لوحــظ علــى احلكــم مبالحظــات أهمهــا أن اإلفهــام املذكــور‬\n‫ال محــل‪ -‬رجــع القاضــي عــن اإلفهــام املذكــور‪ -‬صــدق احلكــم مــن‬\n‫محكمــة االســتئناف‪ -‬جــرى تنفيــذ احلكــم ورصــد ذلــك يف ضبــط‬\n                                                                        ‫القضيــة‬\n\n\n\n‫احلمد اهلل وحده والصالة والسالم على من ال نبي بعده أما بعد لدي أنا‬\n‫‪...‬القاضــي املنتــدب باحملكمــة العامــة بالطائــف بنــاء علــى قــرار معالــي‬\n‫رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 33/9116‬يف ‪1433/4/21‬ه ـ‬\n‫وبنــاء علــى خطــاب فضيلــة رئيــس احملكمــة العامــة بالطائــف رقــم‬\n‫‪ 33786591‬يف ‪1433/4/26‬ه ـ املتضمــن تكليفــي بالعمــل يف املكتــب‬\n‫القضائــي الرابــع يف احملكمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n\n                                                                                      ‫‪338‬‬\n\f      ‫فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ‬\n      ‫‪ 1433/01/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33189562‬وتاريــخ‬\n      ‫‪ 1433/01/29‬ه ـ ويف يــوم اإلثنــن املوافــق‪ 1433/07/07‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 30‬وفيها حضر املدعي أصالة ‪...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪...‬و والوكيــل الشــرعي ‪...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫عــدل الثانيــة بالطائــف برقــم ‪ 4854‬بتاريــخ ‪1433/01/23‬ه ـ واملخولــة‬\n      ‫لــه حــق املرافعــة واملدافعــة واالقــرار واالنــكار وطلــب االميــان وردهــا‬\n      ‫وطلــب البينــة وتقدميهــا و اجلــرح والتعديــل وطلــب االســتئناف وتقــدمي‬\n      ‫اللوائــح االعتراضيــة وحضــر حلضــوره املدعــى عليــه أصالــة ‪ ...‬ســعودي‬\n      ‫ا لقــد اشــتريت‬  ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ادعــى األول قائـ ً‬\n      ‫مــن هــذا احلاضــر يف املجلــس الشــرعي األرض الواقعــة يف حــي جبــرة‬\n      ‫مبدينــة الطائــف واحملــدودة كالتالــي شــما ًال ‪...‬بطــول مائــة وخمســة‬\n      ‫أمتــار وثمانيــة مــن العشــرة وجنوب ـ ًا شــارع بعــرض عشــرين متــر ًا بطــول‬\n      ‫مائــة وخمســة أمتــار وســتة مــن العشــرة مــن املتــر وشــرق ًا بعــرض واحــد‬\n      ‫وعشــرين متــر ًا بطــول أربعــة وســتني متــر ًا وأربعــة مــن العشــر مــن املتــر‬\n      ‫وغرب ـ ًا شــارع بعــرض عشــرة أمتــار بطــول خمســة وســتني متــرا ًواثنــن‬\n      ‫مــن العشــرة مــن املتــر ومســاحتها اإلجماليــة ســتة آالف وثمامنائــة متــرا‬\n      ‫مربع ـ ًا ًوعشــرة مــن الســنتمتر املربــع مببلــغ وقــدره مليــون وثالثمائــة‬\n      ‫وخمســون ألــف ريــال تدفــع مقســطة علــى النحــو التالــي دفعــة أولــى‬\n      ‫مائتــن وخمســن ألــف ريــال عبــارة عــن ســيارة مــن نــوع جيــب تايوتــا‬\n      ‫صنــع عــام ‪2009‬م احتســبت قيمتــه مائــة وخمســة وأربعــن ألــف ريــال‬\n      ‫وشــيك مســحوب علــى البنــك األهلــي برقــم ‪ 3111‬يف ‪1432/12/23‬ه ـ‬\n\n\n‫‪339‬‬\n\f‫مببلــغ مائــه وخمســة أالف ريــال وباقــي املبلــغ يدفــع علــى أقســاط شــهرية‬\n‫نهايــة كل شــهر قيمــة كل قســط خمســن ألــف ريــال تدفــع عــن طريــق‬\n‫شــيكات للمدعــى عليــه علــى أن ال يصــرف املدعــى عليــه الشــيك إال يف‬\n‫تاريخ القســط نهاية كل شــهر وعلى أن أقوم أنا املدعي بتســديد رســوم‬\n‫البلديــة وعلــى أن يبقــى الصــك مرهونــا لــدى املدعــى عليــه فــا يفــرغ لــي‬\n‫إال حــن اســتالم كامــل املبلــغ وعلــى أن اســتالم املبيــع األرض املذكورة‬\n‫مــن ســاعة التعاقــد ولــم يســلمني املدعــى عليــه األرض املذكــورة حتــى‬\n‫اآلن أطلــب الــزام املدعــى عليــه بتســليمي األرض املذكــورة هكــذا‬\n‫ا مــا ذكــره املدعــي‬  ‫ادعــى وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫ا مــا عــدا مــا يخــص الشــيكات‬     ‫يف دعــواه كلــه صحيــح جملــة وتفصيـ ً‬\n‫فإنــي اشــترطت أن تكــون الشــيكات باســم املؤسســة اخلاصــة بــه وأن‬\n‫تكــون مصدقــة ولــم يســتكمل املدعــي هــذان الشــرطان لــذا لــم أســلمه‬\n‫ا‬‫املبيــع حتــى اآلن هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب قائـ ً‬\n‫مــا ذكرتــه هــو الصحيــح واملدعــى عليــه لــم يشــترط علــي أن يكــون‬\n‫الشــيك مصدقــا وكذلــك لــم يشــترط أن تكــون الشــيكات باســم‬\n‫املؤسســة هكــذا أجــاب فجــرى طلــب البينــة مــن املدعــى عليــه علــى‬\n‫مــا ذكــر مــن الشــروط فاســتمهل لذلــك ورفعــت اجللســة وتأجلــت إلــى‬\n‫يــوم االثنــن املوافــق‪1433/07/21 :‬هــ‪ ،‬الســاعة الثامنــة وبــاهلل التوفيــق‬\n‫وختمــت اجللســة يف متــام الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/07‬هـ‬\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫فلــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف والقائــم بعمــل‬\n‫املكتــب القضائــي الرابــع بنــاء علــى خطــاب فضيلــة رئيــس احملكمــة‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫العامــة بالطائــف املســاعد رقــم ‪ 331362127‬يف ‪1433/7/20‬ه ـ‬\n      ‫املتضمــن تكليفــي بالعمــل يف القســم القضائــي الرابــع يف احملكمــة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلتــه برقــم ‪ 3372501‬وتاريــخ‬\n      ‫‪1433/01/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33189562‬وتاريــخ‬\n      ‫‪ 1433/01/29‬ه ـ ففــي هــذا اليــوم االثنــن املوافــق ‪ 1433/7/21‬هـ ويف‬\n      ‫متــام الســاعة الثامنــة صباحــا فتحــت اجللســة وفيهــا حضــر ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ولــم يحضــر املدعــى عليــه‬\n      ‫أصالــة ‪ ...‬وال وكيــل عنــه ولــم يردنــا منــه عــذر ًا رغــم علمــه مبوعــد‬\n      ‫اجللســة وعليــه قــررت رفــع اجللســة مــن أجــل إبــاغ املدعــى عليــه باحلضــور‬\n      ‫ورفعــت اجللســة إلــى يــوم اإلثنــن املوافــق ‪ 1433/11/8‬ه ـ يف متام الســاعة‬\n      ‫العاشــرة صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                   ‫ختمــت اجللســة الســاعة العاشــرة حــرر يف ‪ 1433/6/22‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ ‪ 1433/10/23‬ه ـ واملقيــدة‬\n      ‫يف هــذه احملكمــة برقــم ‪ 33189562‬وتاريــخ ‪1433/10/23‬ه ـ ففــي‬\n      ‫يــوم اإلثنــن املوافــق ‪ 1433/10/23‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n      ‫صباحــا وفيهــا حضــر املدعــى أصالــة ‪...‬املذكــورة هويتــه ســابقا وحضــر‬\n      ‫حلضــوره املدعــى عليــه أصالــة ‪...‬املذكــورة هويتــه ســابقا ( وبنــاء علــى‬\n      ‫املــادة (‪ )166‬مــن نظــام املرافعــات الشــرعية) فقــد مت قــراءة مــا ســبق‬\n      ‫ضبطــه عليهــم فصادقــا عليــه وبســؤال املدعــى عليــه عمــا اســتمهل لــه‬\n      ‫يف اجللســة الســابقة أجــاب قائــا أطلــب إمهالــي إلــى اجللســة القادمــة‬\n      ‫هكــذا أجــاب فأجبتــه لطلبــه ورفعــت اجللســة وتأجلــت إلــى يــوم الثالثــاء‬\n\n\n‫‪341‬‬\n\f‫املوافــق ‪1433/10/24‬ه ـ الســاعة الثامنــة صباحــا وختمــت اجللســة‬\n‫الســاعة الثامنــة و النصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                           ‫محمــد حــرر يف ‪ 1433/10/23‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن الرئيــس برقــم ‪3372501‬واملقيــدة‬\n‫برقــم ‪ 33189562‬ويف يــوم الثالثــاء املوافــق ‪1433/10/24‬ه ـ يف متــام‬\n‫الســاعة الثامنــة صباحــا وفيهــا حضــر الطرفــان وبســؤال املدعــى عليــه‬\n‫عمــا اســتمهل ألجلــه فأجــاب بقولــه إننــي أحضرت الشــهود الذين وعدت‬\n‫بإحضارهــم وأطلــب ســماع مــا لديهــم مــن شــهادة ثــم حضــر ‪...‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪...‬وهــو معلــم متقاعــد يســكن يف وادي‬\n‫العــرج ويبلــغ مــن العمــر ســتة وســبعون ســنة وبســؤاله عمــا لديــه مــن‬\n‫شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أنــه اتصــل بــي ‪ ...‬وقــال‬\n‫لــي اذهــب معــي إلــى جلســة الصلــح بــن ‪...‬و‪...‬ثــم ذهبنــا إلــى اســتراحة‬\n‫‪...‬وكان هــذا بعــد البيــع وكان املدعــى عليــه ‪ ...‬حاضــر بينمــا املدعــي‬\n‫‪ ...‬لــم يحضــر وأحضــر مندوبــه ‪...‬ويف أثنــاء النقــاش قــال ‪...‬أن‪...‬البائــع‬\n‫اشــترط علــى املشــتري ‪...‬تصديــق الشــيكات هــذا مــا لــدي مــن شــهادة‬\n‫ثــم حضــر ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وهــو رجــل متســبب‬\n‫ليــس لديــه عمــل وصاحــب مكتــب عقــار يســكن يف حــي ‪...‬ويبلــغ مــن‬\n‫العمــر أربعــون ســنة واملدعــى عليــه صاحــب لــه واملدعــي جــار لــه وبســؤاله‬\n‫عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أننــي‬\n‫كنــت واملدعــي ‪...‬واملدعــى عليــه ‪...‬يف منــزل املدعــي ‪...‬وقت إمضاء البيع‬\n‫ومت االتفــاق حســب مــا هــو موضــح يف العقــد دون اشــتراط التصديــق‬\n‫للشــيكات وبعــد التوقيــع قلــت ل‪ ...‬اشــتريت قــال نعــم وقلــت ل‪ ...‬قبلــت‬\n\n\n                                                                                      ‫‪342‬‬\n\f      ‫قــال نعــم ثــم تفرقنــا ومــن الغــد ذهبنــا إلــى االســتراحة الســتالمها فطلــب‬\n      ‫منــا إمهالــه إلــى الغــد وبعــد البيــع بأســبوع حضــر إلــى ‪...‬يف املكتــب‬\n      ‫الســتالم الشــيكات وبعــد اطالعــه عليهــا ردهــا ألنهــا غيــر مصدقــه‬\n      ‫وقــال إننــي اشــترطت التصديــق هــذا مــا لــدي مــن شــهادة ثــم حضــر ‪...‬‬\n      ‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وهــو موظف حكومــي متقاعد‬\n      ‫ويســكن يف حــي وادي ‪...‬ويبلــغ مــن العمــر ســتة وثالثــون ســنة وليــس لــه‬\n      ‫عالقــة بأحــد الطرفــن وبســؤاله عمــا لديــه مــن شــهادة أجــاب بقولــه‬\n      ‫أشــهد بــاهلل العلــي العظيــم أننــي لــم أحضــر املبايعــة بــن الطرفــن وإمنــا‬\n      ‫دخلــت مصلح ـ ًا بينهمــا بعــد البيــع بشــهرين وال علــم لــي عــن اشــتراط‬\n      ‫املدعــى عليــه ‪...‬تصديــق الشــيكات هــذا مــا لــدي مــن شــهادة ثــم قــرر‬\n      ‫املدعــي ‪...‬أنــه ال يطلــب تزكيــة الشــهود وال يطعــن فيهــم وأن شــهادة‬\n      ‫‪...‬و ‪...‬ليــس فيهــا مــا يثبــت للمدعــى عليــه شــيء وكلهــا بعــد البيــع و‬\n      ‫أمــا شــهادة ‪...‬فهــي يف صاحلــي هكــذا قــرر كمــا قــرر املدعــى عليــه‬\n      ‫أن الشــاهد الثانــي ‪...‬يف جلســة الصلــح قــرر بقولــه بعــد أن ســألته ألــم‬\n      ‫اشــترط علــى املدعــي ‪...‬أن يســلمني شــيكات مصدقــة قــال بلــى وكان‬\n      ‫هــذا بحضــور الشــاهدين ‪...‬و ‪...‬هكــذا قــرر وبعــرض ذلــك علــى الشــاهد‬\n      ‫‪...‬قــال غيــر صحيــح أننــي قلــت ذلــك وإمنــا كان االشــتراط لتصديــق‬\n      ‫الشــيكات ال حقــا وليــس يف جلســة البيــع األصليــة وإمنــا كان ذلــك‬\n      ‫بعــد أن حضــر املدعــى عليــه ‪...‬لتســلم الشــيكات قــال لــي أنــه اشــترط‬\n      ‫تصديــق الشــيكات هكــذا أجــاب وبســؤال املدعــى عليــه هــل لديــه‬\n      ‫مزيــد مــن البينــة قــال لــم يحضــر جلســة البيــع ســوى ‪...‬وأنــا والشــاهد‬\n      ‫‪...‬واكتفــي مبــا قدمــت وبســؤال املدعــي هــل لديــه مــا يضيفــه قــال نعــم‬\n      ‫إن لــدي شــهود وأطلــب إمهالــي إلحضارهــم لــذا رفعــت اجللســة حتــى‬\n\n\n‫‪343‬‬\n\f‫يــوم األحــد املوافــق ‪1433/12/26‬ه ـ الســاعة التاســعة صباحــا وختمــت‬\n‫اجللســة الســاعة التاســعة صباحــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/10/24‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف‬\n‫وبناء على املعاملة احملالة لنا من الرئيس برقم ‪3372501‬واملقيدة برقم‬\n‫‪ 33189562‬ففــي يــوم االثنــن املوافــق ‪1433/11/1‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر الطرفــان وبســؤال املدعــي عمــا‬\n‫اســتمهل ألجلــه أجــاب بقولــه أننــي أحضــرت الشــاهدين وأطلــب ســماع‬\n‫مــا لديهــم ثــم حضــر ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وعمــره‬\n‫أربعــة وثالثــون ســنة ويعمــل يف جــوازات محافظــة الطائــف ويســكن‬\n‫يف حــي جبــره وهــو جــار للمدعــي وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫بقولــه أشــهد بــاهلل العلــي العظيــم أننــي حضــرت إلى مكتــب ‪...‬للعقارات‬\n‫وكان فيــه ‪...‬و‪ ...‬وكانــوا يتفاوضــون علــى البيــع وعندمــا أردت اخلــروج‬\n‫اســتوقفني ‪...‬وقــال أريــد منــك أن تشــهد علــى املبايعــة وقمــت بســؤال‬\n‫‪...‬عــن املــراد بيعــه فقــال اســتراحة قلــت لــه كــم مســاحتها قــال ســتة‬\n‫أالف وقلــت لــه كــم املبلــغ قــال مليــون وثالثمائــة وخمســون ألــف ريــال‬\n‫يســلمها لــي عــن طريــق شــيك مســحوب علــى مصــرف األهلــي مببلــغ‬\n‫مائــة وخمســة أالف ريــال ومبلــغ مائــة وخمســة وأربعــون ألــف ريــال قيمــة‬\n‫ســيارة جيــب وســلمه ‪...‬صــورة الشــيك واالســتمارة ووقــع عليهــا ثــم اتفقــا‬\n‫علــى تقســيط بقيــة املبلــغ كل شــهر خمســون ألــف ريــال ولــم يذكــرا‬\n‫لــي هــل هــو شــيك أم نقــد وكانــوا قــد اتفقــوا علــى ذلــك ســابقا وإمنــا‬\n‫أتــوا للمكتــب للتوثيــق هــذا مــا لــدي مــن شــهادة ثــم حضــر ‪...‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪...‬وعمــره ســبعة وأربعــون ســنة ويعمــل يف‬\n\n\n                                                                                   ‫‪344‬‬\n\f      ‫قطــاع التعليــم ويســكن حــي ‪...‬وهــو مــن جيــران املدعــي وبســؤاله عمــا‬\n      ‫لديــه مــن شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أننــي كنــت‬\n      ‫حاضــرا يف مكتــب ‪...‬للعقــارات وقــت توقيــع العقــد وكان الطرفــان قــد‬\n      ‫اتفقــا ســابقا وكنــت حاضــرا عندمــا كان ‪...‬يســأل املدعــى عليــه ‪...‬عــن‬\n      ‫البيعــة مــا هــي وكــم مســاحتها وكــم قيمتهــا فأفادنــا بأنهــا اســتراحة‬\n      ‫مبســاحة ســتة أالف متــر مربــع بقيمــة إجماليــة قدرهــا مليــون وثالثمائــة‬\n      ‫وخمســون ألــف ريــال علــى أقســاط عبــارة عــن شــيك مســحوب علــى‬\n      ‫مصــرف األهلــي مببلــغ مائــة وخمســة أالف ريــال ومبلــغ مائــة وخمســة‬\n      ‫وأربعــون ألــف ريــال قيمــة ســيارة جيــب وباقــي املبلــغ علــى دفعــات شــهرية‬\n      ‫بقيمــة خمســون ألــف ريــال ولــم يتطرقــا للشــيكات وال علــم لــي هــل هــي‬\n      ‫نقــد أم شــيكات مصدقــة أم ال هــذا مــا لــدي مــن شــهادة وبعرض شــهادة‬\n      ‫الشــهود علــى املدعــى عليــه قــال أنــا ال أعرفهــم وأمــا ‪...‬فحضــر بعــد مــا‬\n      ‫مت كل شــيء وال علــم لــه بشــيء وأمــا ‪...‬فقــد حضــر متأخــر ولــم يحضــر‬\n      ‫اتفاقنــا وأنــا قــد وقعــت يف بيــت ‪...‬وليــس يف املكتــب كمــا يقولــون‬\n      ‫ولضيــق الوقــت رفعــت اجللســة إلحضــار املزكــن ودراســة القضيــة حتــى‬\n      ‫يــوم االثنــن املوافــق ‪1433/11/15‬ه ـ الســاعة العاشــرة صباحــا وختمــت‬\n      ‫اجللســة الســاعة احلاديــة عشــر صباحــا وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/11/1‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق ‪1434/01/04‬هـ افتتحت‬\n      ‫اجللســة الســاعة التاســعة صباحــا وفيهــا حضــر الطرفان املدونــة هويتهما‬\n      ‫ســابقا وبســؤال املدعــي عمــا اســتمهل ألجلــه وهــل أحضــر املزكــن‬\n      ‫فأجــاب بقولــه إننــي أحضــرت بينــة جديــدة وأطلــب ســماع شــهادة مــن‬\n      ‫أحضرت ثم حضر ‪...‬ســعودي اجلنســية بالســجل املدني رقم ‪ ...‬ويســكن‬\n\n\n‫‪345‬‬\n\f‫يف حــي ‪...‬وعمــره ســبعه وأربعــون عامــا وهــو عســكري متقاعــد وأخ‬\n‫للمدعــي ويعــرف املدعــى عليــه معرفــه ســطحية وليــس بينهمــا عالقــة‬\n‫وبســؤاله عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم‬\n‫أننــي حضــرت إلــى مكتــب ‪...‬للعقــارات وقــت توقيــع العقــد وقــد اتفــق‬\n‫الطرفــان مســبقا وذكــرا لــي وأنــا اســمع أنهمــا اتفقــا علــى أن تتــم البيعة‬\n‫لالســتراحة الواقعــة بجبــره مببلــغ مليــون وثالثمائــة وخمســون ألــف ريــال‬\n‫يدفــع منهــا مقدمــا مبلــغ مائتــن وخمســون ألــف ريــال عــن طريــق شــيك‬\n‫بقيمــة مائــة وخمســة آالف وســيارة جيــب مقيمــة بقيمــة مائــة وخمســة‬\n‫وأربعــون ألــف ريــال وبقيــة املبلــغ مقســط شــهريا بشــيكات قيمــة كل‬\n‫شــيك خمســون ألــف ريــال ولــم يشــترطا أن تكــون مصدقــة كمــا أننــي‬\n‫أنــا مــن أحضــر مفاتيــح الســيارة للمدعــى عليــه وســلمتها إيــاه واســتلمها‬\n‫يف نفــس اليــوم وســافر يف الســيارة إلــى جــدة كمــا قمــت بالتوقيــع علــى‬\n‫العقــد كشــاهد هــذا مــا لــدي مــن شــهادة وبعــرض ذلــك علــى املدعــى‬\n‫عليــه أجــاب بقولــه أننــي ال أطعــن يف الشــاهد غيــر أن مــا ذكــره غيــر‬\n‫صحيــح وقــد حضــر بعــد توقيعنــا للعقــد شــخصيا هكــذا أجــاب وبطلــب‬\n‫املزكــن مــن املدعــى عليــه أحضــر كل مــن ‪...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪...‬وبســؤاله عمــا لديــه أجــاب بقولــه إننــي أزكــي الشــاهدين ‪...‬و‪...‬‬\n‫وأنهــم عــدول يف أقوالهــم وأقبــل شــهادتهم وهــي مرضيــة لــي وعلــي‬\n‫هكــذا قــرر وقــررت رفــع اجللســة إلحضــار مزكــي آخــر يزكــي بقيــة‬\n‫الشــهود ولضبــط ملخــص العقــد املبــرم بينهمــا وحــدد للطرفــن جلســة‬\n‫يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ الســاعة العاشــرة صباحــا وختمــت‬\n‫اجللســة الســاعة التاســعة والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/04‬ه ـ‬\n\n\n                                                                                     ‫‪346‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ ‪ 1433/01/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33189562‬وتاريــخ ‪ 1433/01/29‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1434/01/27‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n      ‫صباحــا وفيهــا حضــر الطرفــان املدونــة هويتهمــا ســابقا وقــرر املدعــي‬\n      ‫بقولــه أننــي أحضــرت املزكــن جلميــع الشــهود ثــم حضــر ‪...‬ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪...‬كمــا حضــر ‪...‬ســعودية اجلنســية بالســجل‬\n      ‫املدنــي رقــم ‪...‬وقــرروا جميعــا بقولهــم أننــا نعــرف الشــهود ‪...‬و‪ ......‬و‪...‬‬\n      ‫ونزكيهــم ونقبــل شــهادتهم لنــا وعلينــا وال نعلــم عنهــم إال خيــرا ثــم جــرى‬\n      ‫ســؤال املدعــى عليــه هــل تقبــل ميــن املدعــي علــى عــدم اشــتراط تصديــق‬\n      ‫الشــيكات فأجــاب بقولــه نعــم ثــم جــرى عــرض اليمــن علــى املدعــي‬\n      ‫فاســتعد ببذلهــا بعــد أن أذنــت لــه واهلل العلــي العظيــم الــذي ال لــه اال هــو‬\n      ‫أننــي اشــتريت األرض الواقعــة يف حــي جبــره مــن املدعــى عليــه بقيمــة‬\n      ‫إجماليــة وقدرهــا مليــون وثالثمائــة خمســون ألــف ريــال تدفــع مائتــن‬\n      ‫وخمســون ألــف ريــال دفعــه أولــى وبقيمــة املبلــغ خمســون ألــف ريــال كل‬\n      ‫شــهر تدفــع يف نهايتــه عــن طريــق شــيكات ولــم نشــترط تصديقهــا واهلل‬\n      ‫العظيــم هكــذا حلــف ثــم جــرى الرجــوع إلــى أوراق املعاملــة فوجــدت‬\n      ‫فيهــا عقــد موقــع مــن قبــل الطرفــن والشــاهد ‪...‬والشــاهد ‪...‬والشــاهد‬\n      ‫‪...‬واملدون على أوراق مكتب ‪...‬للعقار برقم ‪ 0007‬يف ‪1432/12/23‬هـ‬\n      ‫املتضمــن بيــع األرض املذكــورة يف حــي ‪...‬بقيمــة إجماليــه قدرهــا مليــون‬\n      ‫وثالثمائــة وخمســون ألــف ريــال علــى الطريقة التي ذكرهــا املدعي دون‬\n      ‫اشــتراط تصديــق الشــيكات وبعرضــه عليهمــا صــادق عليــه الطرفــان‬\n\n\n‫‪347‬‬\n\f‫‪ .‬فبنــاء مــن الدعــوى واإلجابــة وملــا أبــرزه املدعــي مــن عقــد املبايعــة‬\n‫ومصادقــة املدعــى عليــه جملــة وتفصيــا وحيــث ال بينــه للمدعــى عليــه‬\n‫موصلــة ملــا دفــع بــه مــن اشــتراط تصديــق الشــيكات وحيــث رضــي‬\n‫بيمــن خصمــه فأداهــا وأحضــر معهــا بينــه إضافيــة تشــهد يف جملتهــا‬\n‫علــى عــدم اشــتراط وتصديــق الشــيكات وحيــث أن اشــتراط تصديــق‬\n‫الشــيكات ينــايف املقصــود مــن تقســيط املبلــغ ممــا ال يتصــور الرضــى‬\n‫بــه مــن قبــل املشــتري عــادة ولقولــه صلــى اهلل عليــه وســلم (املســلمون‬\n‫علــى شــروطهم) ولذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بتســليم‬\n‫املدعــي األرض الواقعــة يف حــي ‪...‬ومتكينــه مــن االنتفــاع بهــا كمــا‬\n‫أفهمــت املدعــي بــأن عليــه أن يســلم املدعــى عليــه املبلــغ احلــال يف ذمتــه‬\n‫وقــدره ســتمائة ألــف ريــال وأفهمتــه بــأن لــه الرجــوع علــى املدعــى عليــه‬\n‫للمطالبــة بأجــرة األرض طيلــة الفتــرة املاضيــة وبعرضــه عليهمــا قــرر‬\n‫املدعــي قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم قناعتــه فأفهمتــه بــأن‬\n‫لــه حــق االعتــراض بطلــب االســتئناف وذلــك خــال ثالثــون يومــا مــن‬\n‫تاريــخ اســتالمه للحكــم وذلــك بتقــدمي الئحــة اعتراضيــة وأن مضــت‬\n‫املــدة دون تقدميــة الالئحــة ســقط حقــه يف االعتــراض بطلــب االســتئناف‬\n‫وأكتســب احلكــم القطعيــة وختمــت اجللســة الســاعة العاشــرة والنصف‬\n‫صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ ‪1433/01/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33189562‬وتاريــخ ‪ 1433/01/29‬ه ـ ففــي يــوم‬\n\n\n                                                                                     ‫‪348‬‬\n\f      ‫األحــد املوافــق‪ 1434/07/23‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــر‬\n      ‫ظهــرا وكان قــد وردنــا قــرار محكمــة االســتئناف برقــم ‪34240677‬‬\n      ‫وتاريــخ ‪1434/6/13‬ه ـ املتضمــن مــا نصــه (احلمــد هلل وحــده والصــاة‬\n      ‫والســام علــى مــن ال نبــي بعــد وبعــد فقــد جــرى منــا نحــن قضــاة الدائــرة‬\n      ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف يف منطقــة مكــة املكرمــة‬\n      ‫اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالطائــف برقــم ‪ 34698143‬وتاريــخ ‪1434/4/22‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة العامــة بالطائــف‬\n      ‫برقــم ‪ 3424708‬وتاريــخ ‪1434/1/27‬ه ـ املتضمــن دعــوى ‪...‬ضــد ‪...‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر اعادتهــا‬\n      ‫لفضيلتــه ملالحظــة مــا يلــي ‪ .1‬البيانــات التــي اخــذت ال محــل لهــا وكان‬\n      ‫االولــى االقتصــار علــى رصــد عقــد البيــع ومراجعــة واجــراء املقتضــى‬\n      ‫الشــرعي ‪ .2‬االقتصــار يف احلكــم علــى مــا جــاء بدعــوى املدعــي‬\n      ‫ومراجعــة حكمــه يف االفهــام ‪ .3‬اســتيفاء تصديــق رئيــس احملكمــة‬\n      ‫علــى الصــك ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬ختمــه وتوقيعه‪.‬أ‪.‬هــ) وأجيــب علــى‬\n      ‫مــا ابــداه أصحــاب الفضيلــة مــن ملحوظــات فأمــا الفقــرة األولــى بأنــه‬\n      ‫مت رصــد البيانــات اســتظهارا للحــق وقــد جــرى رصــد مضمــون العقــد‬\n      ‫ســابقا وعرضــه عليهمــا وصادقــا عليــه جملــة وتفصيــا كمــا حلــف‬\n      ‫املدعــي علــى عــدم اشــتراط تصديــق الشــيكات بطلــب مــن خصمــه‪.‬‬\n      ‫وأمــا الفقــرة الثانيــة فأنــي اقــرر بتراجعــي عمــا قمــت بــه مــن افهــام‬\n      ‫للمدعــي مبطالبــة املدعــى عليــه باألجــرة ‪ .‬أمــا الفقــرة الثالثــة فقــد جــرى‬\n\n\n‫‪349‬‬\n\f‫إكمــال الــازم مــن حيــث تصديــق فضيلــة رئيــس احملكمــة وأمــرت‬\n‫ببعــث املعاملــة إلــى محكمــة االســتئناف لالطــاع علــى االجــراء االخيــر‬\n‫واتخــاذ الــازم وختمــت اجللســة يف متــام الســاعة الثانيــة عشــر والنصــف‬\n‫ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه‬\n                                      ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم اإلثنــن املوافق‪1434/10/12‬ه ـ افتتحــت اجللســة‬\n‫الســاعة التاســعة والنصــف صباحــا وكان قــد وردنــا قــرار محكمــة‬\n‫االستئناف برقم ‪ 34301076‬وتاريخ ‪1434/8/21‬هـ واملتضمن املوافقة‬\n‫علــى احلكــم الصــادر برقــم ‪ 3424705‬وتاريــخ ‪1434/1/27‬ه ـ بعــد‬\n‫االجــراء االخيــر قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬‬\n‫ختمــه وتوقيعــه قاضــي ‪...‬ختمــه وتوقيعــه لــذا اكتســب احلكــم القطعيــة‬\n‫وأمــرت بالتهميــش بذلــك علــى ســجله حتــى ال يخفــى وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪ 1434/10/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم اخلميــس املوافــق‪ 1435/01/11‬ه ـ افتتحــت اجللســة‬\n‫الســاعة احلاديــة عشــرة والنصــف صباحــا وفيهــا حضــر املدعــى عليــه‬\n‫أصالــه وكان قــد وردنــا خطــاب مديــر شــعبة تنفيــذ األحــكام رق‬\n‫‪/51‬ع يف ‪1435/01/09‬ه ـ املتضمــن أنــه مت تســليم األرض للمدعــي‬\n‫وبعــث مبلــغ ســتمائة ألــف ريــال بشــيك مصــدق لصالــح املدعــى عليــه‬\n‫حســب منطــوق احلكــم وباإلطــاع علــى املعاملــة وجــد شــيك مطبــوع‬\n‫علــى مطبوعــات مؤسســة النقــد العربــي الســعودي برقــم ‪ 028544‬يف‬\n\n\n                                                                                ‫‪350‬‬\n\f      ‫‪1435/01/08‬ه ـ يتضمــن الدفــع ألمــر ‪ ...‬مبلــغ ســتمائة الــف ريــال جــرى‬\n      ‫تســليم املدعــى عليــه هــذا الشــيك وأمــرت بالتهميــش علــى صكــه‬\n      ‫وســجله حتــى ال يخفــى وبذلــك تكــون القضيــة منتهيــة يف مــا يتعلــق‬\n      ‫مبنطــوق احلكــم وختمــت اجللســة الســاعة الثانيــة عشــرة ظهــرا وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1435/01/11‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقية الثانية مبحكمة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n      ‫احملكمــة العامــة بالطائــف برقــم ‪ 34698143‬وتاريــخ ‪1434/7/30‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3424705‬وتاريــخ ‪1434/1/27‬ه ـ ‪ ،‬املتضمــن‬\n      ‫دعــوى ‪...‬ضــد ‪ ،...‬وبدراســة الصــك وصورة ضبطــه والئحته االعتراضية‬\n      ‫تقــرر املوافقــة علــى احلكــم بعــد االجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                          ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪351‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":337,"source_page_end":351,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cc4bfe5bb85c27b7de50f36a3b69c8664ff5ef3a87e8a08c978e8cf0582c8c9","normalized_text_hash":"bf46d603345d3c76767f49fa579d766cbfaf901d2bd326fae2d125c63c058ae2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p337-3424705"},{"id":"6bcf81e4-7d61-5aaf-b5f3-bc445f3c313c","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء أمر منحة أرض -طلب تسليم وثيقه املنحة -بيع املجهول -بيع ما ال ميلك -احلكم برد املبلغ املدفوع وببطان بيع","document_number":"3433023","case_number":"3441153","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"عقار -شراء أمر منحة أرض -طلب تسليم وثيقه املنحة -بيع املجهول -بيع ما ال ميلك -احلكم برد املبلغ املدفوع وببطان بيع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3433023 :‬تاريخه ‪1434/2/9 :‬هـ رقم‬\n                          ‫الدعوى ‪3441153 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3451488‬تاريخه‪1434/3/1 :‬هـ‬\n\n\n ‫عقــار ‪ -‬شــراء أمــر منحــة أرض ‪ -‬طلــب تســليم وثيقــه املنحــة ‪ -‬بيــع‬\n ‫املجهــول ‪ -‬بيــع مــا ال ميلــك ‪ -‬احلكــم بــرد املبلــغ املدفــوع وببطــان بيــع‬\n                                                                     ‫أمــر املنحــة ‪.‬‬\n\n\n\n\n              ‫‪ -1‬نهي النبي صلى اهلل عليه وسلم عن بيع ما ال ميلك ‪.‬‬\n ‫‪ -2‬تعميم معالي وزير العدل رقم ‪/13‬ت‪ 1970/‬يف ‪1423/3/16‬هـ املشــار‬\n ‫فيــه الــى الفتــوى الصــادرة مــن اللجنــة الدائمــة للبحــوث العلميــة‬\n ‫واإلفتــاء املتضمنــة عــدم جــواز بيــع األرض املمنوحــة حتــى يســتلمها‬\n                                       ‫صاحبهــا مــن اجلهــة املختصــة ‪.‬‬\n\n\n\n ‫ادعــى املدعــى بأنــه اشــترى مــن املدعــى عليــه أمــر منحــه أرض مــن‬\n ‫األمانــة‪ -‬وذكــر املدعــى رقــم أمــر املنحــة‪ -‬كمــا ذكــر املدعــى مبلــغ‬\n ‫الشــراء وأنــه ســلمه للمدعــى عليــه كام ـاً‪ -‬قــرر املدعــى أنــه ال يعلــم‬\n ‫موقــع األرض وال حدودهــا وال أطوالهــا وال مســاحتها‪ -‬أقــر املدعــى‬\n ‫عليــه مبــا جــاء يف الدعــوى‪ -‬قــرر املدعــى عليــه أنــه قبــل ســنتني ذكــر‬\n ‫للمدعــى أنــه محتــاج لهــذه األرض ألنــه ال يوجــد لديــه بيــت وأنــه مســتعد‬\n ‫بإرجــاع املبلــغ الــذى اســتلمه للمدعــى‪ -‬كمــا ذكــر املدعــى عليــه أن‬\n\n                                                                                        ‫‪352‬‬\n\f      ‫املدعــى قبــل شــهرين أرســل لــه شــخصا وقــرر أنــه يطلــب مبلغ ـ ًا زائــد ًا‬\n      ‫علــى املبلــغ الــذى ســلمه‪ -‬ابــرز املدعــى عليــه اســتمارة بيانــات قطعــه‬\n      ‫األرض املمنوحــة‪ -‬حيــث قــرر املدعــى انــه اشــترى أمــر منحــة أرض ال‬\n      ‫يعــرف موقعهــا وال حدودهــا وأطوالهــا وبنــاء علــى فتــوى اللجنــة الدائمــة‬\n      ‫املتضمنــة عــدم جــواز بيــع األرض املمنوحــة قبــل اســتالمها لذلــك صــدر‬\n      ‫احلكــم بــرد دعــوى املدعــى واحلكــم ببطــان البيــع املذكــور وافهــام‬\n      ‫املدعــى بأنــه لــه املطالبــة باســترداد املبلــغ الــذى دفعــه‪ -‬اعتــرض املدعــى‬\n                         ‫علــى احلكــم‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بحائــل املســاعد برقــم ‪ 3441153‬وتاريــخ ‪ 1434/01/24‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34200918‬وتاريــخ ‪ 1434/01/24‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/02/09‬ه ـ فتحــت اجللســة األولــى الســاعة‬\n      ‫‪ 08 : 30‬وفيهــا حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬وادعــى علــى احلاضــر معــه ‪...‬ســجل رقــم ‪...‬قائــا يف دعــواه عليــه‬\n      ‫إنــه بتاريــخ ‪1428/9/20‬ه ـ اشــتريت مــن هــذا احلاضــر أمــر منحــة أرض‬\n      ‫صــادر مــن أمانــة منطقــة حائــل لعــام ‪1418‬ه ـ ورقمهــا ‪ 12803‬مببلــغ‬\n      ‫ســبعة عشــر ألــف ريــال ســلمتها كاملــة وقــد صــدرت وثيقــة التملــك‬\n      ‫مــن األمانــة لكــي يقــوم بتســويرها ثــم يصــدر لــه الصــك ولــذا فإنــي‬\n      ‫أطلــب ســؤال املدعــى عليــه والزامــه بتســليمي هــذه الوثيقــة حتــى أقــوم‬\n      ‫بتســوير األرض وإفــراغ األرض باســمي ألنــه ال ميلــك منهــا أي جــزء علمــا‬\n\n‫‪353‬‬\n\f‫أننــي ال أعلــم موقــع األرض وال حدودهــا وال أطوالهــا وال مســاحتها وإمنــا‬\n‫اشــتريت ورقــة منحــة أرض فقــط هــذه دعــواي وبســؤال املدعــى عليــه‬\n‫أجــاب قائــا مــا ذكــره املدعــي أننــي بعــت عليــه رقــم أرض ممنوحــة‬\n‫لــي مببلــغ ســبعة عشــر ألــف ريــال اســتلمتها فهــذا صحيــح ولكــن قبــل‬\n‫ســنتني رجعــت علــى املدعــي فقلــت يــا‪ ...‬أريــد أن أرجــع لــك حقــك ألنــي‬\n‫محتــاج هــذه األرض وال عنــدي بيــت فقــال لــي املدعــي ال أريــد فلوســي‬\n‫وال أريــد األرض وقبــل شــهرين أرســل لــي املدعــي أشــخاصا يطلــب بــدل‬\n‫الســبعة عشــر ألــف ريــال مبلــغ خمســن ألــف ريــال هــذا مــا حصــل واآلن‬\n‫أنــا غيــر مســتعد بإعطائــه وثيقــة األرض ألنــي لــم أملكهــا ومســتعد‬\n‫بإعــادة املبلــغ الــذي دفعــه حــاال هــذه إجابتــي ثــم أبــرز املدعــى عليــه‬\n‫اســتمارة بيانــات قطعــة أرض ممنوحــة صــادرة مــن مديــر إدارة املنــح‬\n‫بأمانــة منطقــة حائــل رقــم القطعــة ‪ 4424‬رقــم املخطــط ‪ 202‬بنــاء علــى‬\n‫قــرار التخصيــص رقــم ‪/463‬ح يف ‪1433/04/20‬هـ ـ واخلطــاب موجــة‬\n‫إلــى مديــر مكتــب ‪ ...‬لالستشــارات الهندســية لتســليم األرض للمواطــن‬\n‫‪...‬ويف أســفل االســتمارة خطــاب مديــر مكتــب ‪...‬املتضمــن مت تســليم‬\n‫املواطــن املذكــور قطعــة ومت اســتحصال املبلــغ املســتحق‪ ،‬أمــا أطــوال‬\n‫القطعــة ومســاحتها كمــا يلــي شــماال قطعــة رقــم ‪ 4422‬بطــول ‪ 30‬م‬\n‫وجنوبــا م ‪ 9060‬بطــول ‪30‬م شــرقا شــارع عــرض ‪15‬م بطــول ‪ 21‬م وغربــا‬\n‫قطعــة رقــم ‪ 4423‬بطــول ‪ 21‬م وإجمالــي مســاحتها ‪ 630‬م‪ 2‬هــذا مــا‬\n‫تضمنتــه اســتمارة بيانــات القطعــة ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة واإلطــاع علــى أوراق املعاملــة وحيــث إن املدعــي قــد أقــر يف‬\n‫دعــواه أنــه قــد أشــترى أمــر منحــة علــى أرض ال يعــرف موقعهــا وحدودها‬\n‫وأطوالهــا وحيــث إن دعــواه غيــر محــررة والبيــع علــى مجهــول هــذا بيــع‬\n\n\n                                                                                    ‫‪354‬‬\n\f      ‫باطــل كمــا أن املدعــى عليــه لــم يســتقر ملكــه علــى األرض وقــت‬\n      ‫البيــع واســتناد ًا علــى تعميــم معالــي وزيــر العــدل رقــم ‪/13‬ت ‪1970/‬‬\n      ‫يف ‪ 1423/03/16‬هـ ـ واملشــار فيــه إلــى الفتــوى الصــادرة مــن اللجنــة‬\n      ‫الدائمــة للبحــوث العلميــة واإلفتــاء وتتضمــن ‪ :‬عــدم جــواز بيــع األرض‬\n      ‫املمنوحــة حتــى يســتلمها صاحبهــا مــن اجلهــة املختصــة ومــا حصــل مــن‬\n      ‫بيــع لهــا قبــل ذلــك فهــو باطــل ولنهيــه صلــى اهلل عليــه وســلم عــن بيــع مــا‬\n      ‫ال ميلــك لذلــك كلــه فقــد رددت دعــوى املدعــي بخصــوص طلــب تســليمه‬\n      ‫وثيقــة املنحــة وحكمــت ببطــان هــذا البيــع وأفهمــت املدعــى بــان لــه‬\n        ‫املطالبــة باســترداد املبلــغ الــذي دفعــه هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عــدم القناعــة وطلــب‬\n      ‫متكينــه مــن تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وأفهمتــه أنــه ســوف‬\n      ‫يتــم تســليمه نســخة مــن احلكــم بعــد التوقيــع إن شــاء اهلل كمــا أفهمتــه‬\n      ‫بــأن مــدة االعتــراض وقدرهــا ثالثــون يومــا ســوف تبــدأ مــن هــذا اليــوم‬\n      ‫وأن عليــه تقــدمي الئحتــه خــال هــذه املــدة وإذا مضــت هــذه املــدة ولــم‬\n      ‫يتقــدم بالئحتــه فتســقط معارضتــه ففهــم ذلــك وأمــا املدعــى عليــه فقــرر‬\n      ‫القناعــة وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434/02/09‬هـ ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن رئيــس احملكمة العامة بحائل املســاعد برقم‬\n      ‫‪ 34200918‬وتاريخ‪1434/2/20‬ه ـ واملقيــدة لدينــا برقم ‪ 34451126‬يف‬\n      ‫‪1434/2/23‬ه ـ املرفــق بهــا الصــك رقــم ‪ 3433023‬يف ‪1434/02/9‬ه ـ‬\n      ‫الصــادر مــن فضيلــة القاضــي‪... /‬اخلــاص بدعــوى ‪...‬ضــد ‪...‬يف ملكيــة‬\n\n\n‫‪355‬‬\n\f‫عقــار علــى الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه ببطــان هــذا البيــع وأفهــم املدعــي بــأن لــه املطالبــة باســترداد‬\n‫املبلــغ الــذي دفعــة ‪ ،‬و بدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة ‪ :‬جــرت املصادقــة علــى مــا حكــم بــه‬\n     ‫فضيلتــه ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪0‬‬\n\n\n\n\n                                                                                   ‫‪356‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":352,"source_page_end":356,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a1459e8deb8ccdc8e5abfc7fd90a067d6c252ca91b8099fe37666b25ce71a34","normalized_text_hash":"b7546ee8fa7917088a7d2e5bbce45b7b46a73cf28168d044e36a6058aba7b2c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p352-3433023"},{"id":"cb0fe084-c148-561b-8a90-041c5ae9a700","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -بيع عقار مبوجب صك -إيقاف الصك ألن اإلفراغ كان مبوجب وكالة مزورة -التداخل يف الدعوى للمصلحة -قيام املتداخل ببيع العقار محل الدعوى -بطان عقد البيع لتخلف شرط التملك وتسليم املبالغ قيمة العقار ألهلها وصرف النظر عن أتعاب احملاماة .","document_number":"3436000","case_number":"33149668","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1343/2/12","year":"1434","subject":"عقار -بيع عقار مبوجب صك -إيقاف الصك ألن اإلفراغ كان مبوجب وكالة مزورة -التداخل يف الدعوى للمصلحة -قيام املتداخل ببيع العقار محل الدعوى -بطان عقد البيع لتخلف شرط التملك وتسليم املبالغ قيمة العقار ألهلها وصرف النظر عن أتعاب احملاماة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3436000 :‬تاريخه ‪1343/2/12:‬هـ رقم‬\n                               ‫الدعوى ‪33149668 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 34269903:‬تاريخه‪1434/07/16:‬هـ‬\n\n\n        ‫عقــار‪ -‬بيــع عقــار مبوجــب صــك‪ -‬إيقــاف الصــك ألن اإلفــراغ كان‬\n        ‫مبوجــب وكالــة مــزورة‪ -‬التداخــل يف الدعــوى للمصلحــة‪ -‬قيــام‬\n        ‫املتداخــل ببيــع العقــار محــل الدعــوى‪ -‬بطــان عقــد البيــع لتخلــف‬\n        ‫شــرط التملــك وتســليم املبالــغ قيمــة العقــار ألهلهــا وصــرف النظــر‬\n                                                             ‫عــن أتعــاب احملامــاة ‪.‬‬\n\n\n\n\n        ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم ( التبــع مــا ليــس عنــدك ) رواه بــن‬\n                                                                             ‫ماجــه والترمذي‬\n        ‫‪ -2‬قــال يف الشــرح الكبيــر ‪ 55/11‬الرابــع‪ -‬أي مــن شــروط انعقــاد البيــع‪-‬‬\n        ‫أن يكــون مملــوك ًا لــه أي البائــع‪ -‬أو مــا ذونــا لــه يف بيعــه فــإن بــاع ملــك‬\n              ‫غيــرة بغيــرة اذنــه او اشــتري بعــن مالــه شــيئ ًا بغيــر اذنــه لــم يصــح )‬\n                                                                   ‫‪ -3‬االقرار حجه ملزمة‬\n                                                        ‫‪ -4‬ما بني على باطل أخذ حكمه‬\n\n\n\n        ‫ادعــى املدعــى وكالــة بــأن موكلــه اشــتري قطعــة أرض مــن املدعــى‬\n        ‫عليــه مببلــغ مائتــي ألــف ريــال وعندمــا أراد موكلــه التصــرف يف األرض‬\n        ‫بالبيــع أفيــد عــن طريــق كتابــة العــدل بــأن الصــك موقــوف بســبب أن‬\n\n‫‪357‬‬\n\f‫االفــراغ مــن قبــل األمانــة للمالــك األول ثــم للمدعــى عليــه كان مبوجــب‬\n‫وكالــة مــزورة‪ -‬طلــب املدعــى وكالــة الــزام املدعــى عليــه بتســليم‬\n‫موكلــه كامــل املبلــغ الــذي دفعــه وقــدرة مائتــا الــف ريــال ودفــع اتعــاب‬\n‫احملامــاة عشــرين ألــف ريــال‪ -‬صــادق املدعــى عليه علــى ما جاء يف دعوى‬\n‫املدعــي وكالــة ودفــع بــأن شــراءه ثــم بيعــة األرض علــى املدعــى أصالــة‬\n‫كان موثقـ ًا لــدى كتابــة العــدل‪ -‬جــرى االستفســار عــن ســجل الصــك‬\n‫وورد اجلــواب مــن كتابــة العــدل املتضمــن ايقــاف الصــك حيــث إن أصــل‬\n‫امللــك منحــة ملواطنــة ومت بيعهــا بوكالــة مــزورة‪ -‬طلــب الطرفــان إدخــال‬\n‫وكيــل البائــع طرفـ ًا يف الدعــوى ‪ -‬حضــر وكيــل البائــع األول وصــادق‬\n‫علــى الدعــوى وأن موكلــه قــام ببيــع األرض موضــع الدعــوى علــى‬\n‫املدعــى عليــه مببلــغ مائــة وعشــرين ألــف ريــال واســتلم كامــل الثمــن‬\n‫نقــد ًا واســتلم موكلــه اتعابــه خمســة االف ريــال ثــم ســلم باقــي الثمــن‬\n‫لصاحــب األرض الــذي قــام بتوكيــل موكلــة مناولــة لرجــل أرســل مــن‬\n‫طرفــة لكــون امللــك الصحيــح التــام مــع االذن مــن املالــك يف التصــرف‬\n‫ببيعــة شــرط مــن شــروط البيــع ولقولــه صلــى اهلل عليــه وســلم حلكيــم‬\n‫بــن حــزام التبــع مــا ليــس عنــدك رواه ابــن ماجــه والترمــذي لــذا صــدر‬\n‫احلكــم بإبطــال عقــد املبايعــة األول بــن املتداخــل واملدعــى عليــه وابطال‬\n‫عقــد املبايعــة الثانــي بــن املدعــى عليــه واملدعــى والــزام املدعــى عليــه‬\n‫بتســليم املدعــى مائتــي ألــف ريــال والــزام املتداخــل أصالــة وكيــل البائــع‬\n‫األول بتســليم املدعــى عليــه مائــة وعشــرين ألــف ريــال وصــرف النظــر‬\n‫عــن طلــب املدعــى وكالــة احلكــم بأتعــاب احملامــاة علــى املدعــى عليــه‬\n‫لكــون التصــرف الــذي صــدر منــه ال يلــزم ضمان ـاً‪ -‬وافهــم املتداخــل‬\n‫وكالــه بــأن ملوكلــه الرجــوع علــى مــن غــره لطلــب مــا لــزم بدفعــه‪-‬‬\n\n\n                                                                                     ‫‪358‬‬\n\f      ‫وافهــم املدعــى وكالــة بــان ملوكلــه الرجــوع بطلــب اتعــاب احملامــاة ممــن‬\n      ‫فــرط وحتمــل بطــان البيــع‪ -‬كمــا قــرر القاضــي التهميــش علــى صــك‬\n      ‫صــورة صــك العقــار مبوجــب احلكــم بعــد اكتســابه للقطعيــة‪ -‬لــم يقنــع‬\n      ‫املدعــى عليــه وال املتداخــل‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بجــازان برقــم ‪ 33149668‬وتاريــخ ‪1433/02/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33381886‬وتاريــخ ‪ 1433/02/27‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/03/15‬ه ـ أفتتحــت اجللســة الســاعة ‪: 35‬‬\n      ‫‪ 09‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ا عــن ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬بالوكالــة رقــم ‪1537‬‬      ‫‪...‬وكيـ ً‬\n      ‫بتاريــخ ‪1433/02/01‬ه ـ اجللــد ‪ 791‬الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بجــازان املخــول لــه فيهــا املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامة‬\n      ‫الدعــاوي ضــد الغيــر وإنهــاء مــا يلــزم حضــوري يف كل دعــوى تقــام‬\n      ‫مــن املــوكل أو ضــده أمــام أي محكمــة ويف أي جهــة وإنهــاء كافــة‬\n      ‫اإلجــراءات املتعلقــة بذلــك ولــه احلــق يف ســماع الدعــوى والــرد عليهــا‬\n      ‫واإلقــرار واإلنــكار والصلــح وطلــب وقبــول احلكــم ونفيــة واإلعتــراض‬\n      ‫عليــه وطلــب متييــزه واالســتالم والتســليم ومراجعــة اجلهــات احلكوميــة‬\n      ‫ذات العالقــة بــكل مــا يلــزم والتوقيــع عنــي وكالــه خاصــة فيمــا ذكــر‬\n      ‫وعليه جرى التصديق والتوقيع ولم يحضر حلضوره املدعى عليه وال من‬\n      ‫ينوبــه ولــم يتقــدم بعــذر مقبــول ويف جلســة أخــرى حضــر املدعــي وكالــة‬\n\n‫‪359‬‬\n\f‫مبوجــب الوكالــة الصــادرة مــن كتابة العدل الثانيــة بجازان رقم ‪1537‬‬\n‫يف ‪1433/2/1‬ه ـ واملخــول لــه فيهــا حــق املطالبــة واملرافعــة واملدافعــة‬\n‫واملخاصمــة وإقامــة الدعــاوي ضــد الغيــر وإنهــاء مــا يلــزم يف كل دعــوى‬\n‫تقــام أمــام أي محكمــة ويف أي جهــة وإنهــاء كافــة اإلجــراءات املتعلقــة‬\n‫بذلــك ولــه احلــق يف ســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار‬\n‫والصلــح وطلــب وقبــول احلكــم ونفيــه واإلعتــراض عليــه وطلــب التمييــز‬\n‫واإلســتالم والتســليم ومراجعــة اجلهــات احلكوميــة ذات العالقــة وطلــب‬\n‫تبليــغ املدعــى عليــه مــرة أخــرى فأجبتــه لطلبــه وقــررت رفــع اجللســة ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه أصالــة ‪...‬ســعودي‬\n‫جلنســية بالســجل املدنــي رقــم ‪...‬وجــرى ســؤال املدعــي عــن دعــواه ادعــى‬\n‫قائــا ‪ :‬لقــد اشــترى موكلــي قطعــة أرض اململوكــة بالصــك رقــم ‪29‬‬\n‫وتاريــخ ‪1430/10/16‬ه ـ مــن املدعــى عليــه مببلــغ مائتــن ألــف ريــال (‬\n‫‪ 200000‬ريــال ) وعندمــا أراد موكلــي التصــرف يف األرض بالبيــع أفيــد‬\n‫عــن طريــق كتابــة العــدل بــأن الصــك موقــوف وذلــك بســبب أن اإلفــراغ‬\n‫مــن قبــل األمانــة للمالــك األول ومــن املالــك األول للمدعــى عليــه كانــت‬\n‫مبوجــب وكالــة مــزورة ال تخــول حــق القبــول والبيــع وبهــذا يصبــح البيــع‬\n‫األول مبنــي علــى باطــل ولــذا أطلــب إلــزام املدعــى عليــه بتســليم موكلــي‬\n‫كامــل املبلــغ الــذي كان ثمنــا لهــذا العقــار وهــو مبلــغ ( ‪ 200000‬ريــال‬\n‫) كمــا أطلــب إلزامــه بدفــع أتعــاب احملامــاة بقيمــة عشــرين ألــف ريــال‬\n‫( ‪ 20000‬ريــال ) ملوكلــي هكــذا ادعــى وبعــرض ذك علــى علــى املدعــى‬\n‫عليــه أجــاب قائــا ‪ :‬مــا ذكــره املدعــي مــن أننــي قــد بعــت علــى موكلــه‬\n‫قطعــة األرض املدونــة بياناتهــا أعــاه مببلــغ ( ‪ 200000‬ريــال ) فصحيــح‬\n‫وقــد مت ذلــك موثقــا لــدى كتابــة العــدل األولــى بجــازان ومــا ذكــره‬\n\n\n                                                                                   ‫‪360‬‬\n\f      ‫املدعــي مــن كــون البيــع الســابق الــذي قمــت بــه كان بيعــا غيــر صحيــح‬\n      ‫فــا علــم لــي بذلــك ألن مبايعتــي األولــى صحيحــة وقــد متــت كذلــك‬\n      ‫موثقــة عــن طريــق كتابــة العــدل األولــى بجــازان هكــذا أجــاب فجــرى‬\n      ‫االطــاع علــى أصــل الصــك الصــادر مــن كتابــة العــدل األولــى بجــازان‬\n      ‫رقــم ‪ 29‬وتاريــخ ‪143/10/16‬ه ـ فقــررت الكتابــة إلــى كتابــة العــدل‬\n      ‫األولــى بجــازان لإلفــادة عــن ســريان مفعــول الصــك ومطابقتــه لســجله‬\n      ‫واإلفــادة عــن ســبب إيقــاف التصــرف يف العقــار وتزويدنــا بصــورة مــن‬\n      ‫ســجل العقــار ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n      ‫وقــد وردنــا خطــاب رئيــس كتابــة العــدل رقــم‪ 331357233‬وتاريــخ‬\n      ‫‪1433/8/11‬ه ـ املتضمــن ( نعيــد لكــم خطابكــم رقــم ‪331300391‬‬\n      ‫يف ‪1433/7/12‬ه ـ بشــأن االستفســار عــن ســريان الصــك رقــم ‪ 29‬يف‬\n      ‫‪1430 /10 /16‬هـ وبالرجوع إلى ســجل الصك تبني لنا أن أصل الصك‬\n      ‫ا‬‫منحــة مــن األمانــة للمواطنــة‪ ... /‬بالســجل ‪...‬حضــر ‪...‬بالســجل ‪...‬وكيـ ً‬\n      ‫عــن ‪ ...‬بالســجل ‪...‬مبوجــب الوكالــة رقــم ‪ 1107‬يف ‪1430/10/10‬ه ـ‬\n      ‫وحيــث أنهــا قــد زورت الوكالــة يف اســتخراج املنحــة وذلــك حســب إفــادة‬\n      ‫رئيــس كتابــة العــدل الثانيــة بالريــاض بخطــاب رقــم ‪ 331413974‬يف‬\n      ‫‪1433/7/27‬ه ـ ويجــد فضيلتكــم برفقــة خطابنــا هــذا صــورة مــن‬\n      ‫كامــل معاملــة املنحــة األســاس وبقيــة املرفقــات)أ ‪.‬هــ‪ .‬ثم طلــب الطرفان‬\n      ‫إدخــال البائــع األول يف هــذه الدعــوى ‪...‬بالســجل املدنــي ‪...‬فأجبتهمــا‬\n      ‫لطلبهمــا وقــررت طلــب حضــوره يف اجللســة القادمــة وقــررت رفــع اجللســة‬\n      ‫إلــى يــوم ‪1434/2/10‬هـ ـ وكان ختــام هــذه اجللســة عنــد الســاعة ‪00‬‬\n      ‫‪ 10:‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪ 1433/12/29‬ه ـ‬\n\n\n‫‪361‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/02/10‬ه ـ‬\n‫افتتحت اجللسة الساعة ‪ 10 : 45‬وفيها حضر املدعي وكالة واملدعى‬\n‫عليــه أصالــة واملتداخــل معهــم وكالــة ‪...‬ســعودي بالســجل املدنــي رقــم‬\n‫‪ 1020825269‬وكيــا عــن ‪...‬بالوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجــازان رقــم ‪ 34151397‬وتاريــخ ‪1434/2/9‬ه ـ واملخــول لــه‬\n‫فيهــا حــق املطالبــة واملرافعــة واملدافعــة وســماع الدعــوى والــرد عليهــا‬\n‫واإلقــرار واإلنــكار والصلــح واملطالبــة بتنفيــذ األحــكام وبعــرض مــا‬\n‫ســبق ضبطــه علــى املتداخــل وكالــة أجــاب قائــا‪ :‬مــا ذكــره املدعــي‬\n‫واملدعــى عليــه يف هــذه الدعــوى صحيــح وقــد قــام موكلــي ببيــع هــذه‬\n‫القطعــة مــن األرض اململوكــة بالصــك رقــم ‪ 29‬علــى املدعــى عليــه مببلــغ‬\n‫مائــة وعشــرين ألــف ريــال ( ‪ 120‬ألــف ريــال ) واســتلم كامــل الثمــن‬\n‫نقــدا وقــد اســتلم موكلــي أتعابــه بقيمــة خمســة آالف ريــال ( ‪5000‬‬\n‫ألــف ريــال ) ثــم ســلم باقــي الثمــن لصاحــب األرض الــذي قــام بتوكيــل‬\n‫موكلــي مناولــة لرجــل أرســل مــن طرفــه ويف هــذه اجللســة جــرى االطــاع‬\n‫علــى صــك االرض رقــم ‪ 29‬يف ‪1430/10/16‬ه ـ ونــص احلاجــة منــه ( بأن‬\n‫األرض املذكــورة أرض حكوميــة حتــت تصــرف األمانــة وقــد تنازلــت‬\n‫عنهــا ‪...‬املضافــة بحفيظــة زوجهــا ‪ 257483‬يف ‪1415/6/12‬ه ـ ســجل‬\n‫الريــاض وســجلها ‪...‬حضر‪.../‬بالســجل ‪...‬وكيــا عــن‪... /‬بالســجل‬\n‫‪...‬مبوجــب الوكالــة ‪ 1107‬يف ‪1430/10/10‬ه ـ جلــد‪ 9‬الصــادرة مــن‬\n‫عــدل الثانيــة بالريــاض بصفتــه وكيــا عــن ‪... /‬بالســجل ‪111862528‬‬\n‫بالوكالــة ‪ 72‬يف ‪1428/4/25‬ه ـ الصــادرة مــن كتابــة عــدل الطائــف‬\n‫املخولــة لــه حــق توكيــل الغيــر واســتالم املنحــة بنــاء علــى األمــر الســامي‬\n‫الكــرمي رقــم ‪/218‬م يف ‪1425/3/5‬ه ـ ) ثــم همــش علــى ظهــر الصــك‬\n\n\n                                                                                       ‫‪362‬‬\n\f      ‫( وانتقــل كامــل العقــار املذكــور يف هــذا الصــك إلــى ملــك ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب احلفيظــة رقــم ‪/...‬جــازان وتاريــخ ‪1410/4/17‬هـ ســجل‬\n      ‫‪...‬بثمــن قــدره مائــة وأربعــون ألــف ريــال وذلــك مبوجــب مــا ضبــط بعــدد‬\n      ‫‪ 203‬يف ‪1430/10/29‬ه ـ صحيفــة ‪ 98‬مجلــد‪ 5/438‬لعــام ‪1430‬ه ـ ثــم‬\n      ‫انتقــل كامــل العقــار املذكــور يف هذا الصك إلى ملك باســم ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب احلفيظــة رقــم ‪ /...‬جــازان وتاريــخ ‪1406/11/16‬ه ـ‬\n      ‫ســجل ‪...‬بثمــن قــدره مائتــان ألــف ريــال وذلــك مبوجــب مــا ضبــط بعــدد‬\n      ‫‪ 107‬يف ‪1431/2/10‬ه ـ ) أ‪.‬ه ـ صحيفــة ‪ 81‬مجلــد ‪ 2/447‬لعــام ‪1431‬هـ‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة واملدعــى عليــه واملتداخــل وكالــة‬\n      ‫صادقــوا علــى صحــة املبايعــة وقــررا املدعــى عليــه واملتداخــل وكالــة بأن‬\n      ‫املبلــغ املــدون علــى ظهــر الصــك غيــر صحيــح والصحيــح أن مبلــغ الشــراء‬\n      ‫األول كان بقيمــة مائــة وعشــرين ألــف ريــال ( ‪ 120000‬ألــف ريــال )‬\n      ‫كمــا جــرى االطــاع علــى صــورة خطــاب رئيــس كتابــة العــدل الثانيــة‬\n      ‫بالريــاض رقــم ‪143473‬وتاريــخ ‪1433/7/29‬ه ـ املرفــق صورتــه بخطــاب‬\n      ‫كتابــة عــدل جــازان األولــى إلينــا واملتضمــن ( نفيدكــم أنــه بالبحــث‬\n      ‫يف ســجالت اإلدارة لدينــا تبــن أن الوكالــة املشــار إليهــا أعــاه واملرفــق‬\n      ‫صورتهــا ليــس لهــا ســجل صحيــح ضمــن الســجالت لدينــا ونســبتها‬\n      ‫إلــى هــذه اإلدارة غيــر صحيــح ) أ‪.‬ه ـ ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫حلكيــم بــن حــزام ( ال تبيــع مــا ليــس عنــدك ) رواه ابــن ماجــة والترمــذي‬\n      ‫‪.‬ولكــون امللــك الصحيــح التــام للمبيــع مــع اإلذن مــن املالــك يف التصــرف‬\n      ‫ببيعــه شــرط مــن شــروط البيــع كمــا نــص عليــه الفقهــاء قــال يف الشــرح‬\n      ‫الكبيــر ( الرابــع ـ ـ أي مــن شــروط انعقــاد البيــع ـ ـ أن يكــون مملــوكا‬\n      ‫لــه ـ ـ أي للبائــع ـ ـ أو مأذونــا لــه يف بيعــه فــإن بــاع ملــك غيــره بغيــر إذنــه أو‬\n\n\n‫‪363‬‬\n\f‫اشــترى بعــن مالــه شــيئا بغيــر إذنــه لــم يصــح ) الشــرح الكبيــر ( ‪55/11‬‬\n‫) وإلقــرار كل طــرف باســتالم الثمــن يف املبايعــات واإلقــرار حجة ملزمة‬\n‫إذا صــدر مــن صاحــب أهليــة مقبــرة شــرعا ولكــون الوكيــل قــد خــول‬\n                                 ‫لــه يف وكالتــه حــق ( اإلقــرار ) ‪ (( .‬يتبــع ))‬\n‫وألن مــا يبنــى علــى باطــل أخــذ حكمــه وجلميــع مــا تقــدم فقــد ثبــت‬\n‫لــدي أن املتداخــل أصالــة ‪...‬قــد تصــرف يف بيــع العقــار اململــوك بالصــك‬\n‫رقــم ‪ 29‬وهــو ال ميلكــه ولــم يــأذن لــه مالكــه األصلــي بالتصــرف فيــه‬\n‫بالبيــع ‪ ،‬وقــد حكمــت مبــا يلــي ‪ :‬أوال ‪ /‬أبطلــت عقــد املبايعــة األول‬\n‫بــن ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬و‪...‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪...‬والــذي انعقــد بتاريــخ ‪1430/10/29‬ه ـ ‪.‬ثانيــا ‪ /‬أبطلــت‬\n‫عقــد املبايعــة الثانــي بــن ‪...‬و ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬والــذي‬\n‫انعقــد بتاريــخ ‪1431/2/10‬ه ـ ‪.‬ثالثــا ‪ /‬ألزمــت املدعــى عليــه ‪ ...‬بتســليم‬\n‫املدعــي أصالــة ‪...‬مبلغــا وقــدره مائتــي ألــف ريــال ( ‪ 200000‬ألــف ريــال )‬\n‫حــاال رابعــا ‪ /‬ألزمــت املتداخــل أصالــة ‪ (...‬وكيــل البائــع األول ) بتســليم‬\n‫املدعــى عليــه ‪...‬مبلغــا وقــدره مائــة وعشــرين ألــف ريــال ( ‪ 120000‬ألــف‬\n‫ريــال )‪.‬خامســا ‪ /‬صرفــت النظــر عــن طلــب املدعــي وكالــة احلكــم‬\n‫بأتعــاب احملامــاة علــى املدعــى عليــه لكــون التصــرف الــذي صــدر منــه‬\n‫صحيــح اليلــزم ضمانــا ‪ ،‬وبذلــك حكمــت ‪ ،‬وبعــرض احلكــم علــى‬\n‫أطــراف الدعــوى قنــع بــه املدعــي وكالــة ولــم يقنــع بــه املدعــى عليــه‬\n‫ولــم يقنــع بــه املتداخــل وكالــة فأفهمــت املعتــرض منهــم بــأن لــه اســتالم‬\n‫صــورة مــن صــك احلكــم حــاال وأن لــه مــدة ( ‪ 30‬يومــا ) لتقــدمي الئحتــه‬\n‫االعتراضيــة ‪ ،‬فــإن انقضــت املــدة ولــم يتقــدم خاللهــا ســقط حقــه‬\n‫يف االعتــراض واكتســب احلكــم القطعيــة كمــا أفهمــت املتداخــل‬\n\n\n                                                                                      ‫‪364‬‬\n\f      ‫وكالــة بــأن ملوكلــه الرجــوع علــى مــن غــره لطلــب مــا ألــزم بدفعــه‬\n      ‫مبوجــب احلكــم كمــا أفهمــت املدعــي وكالــة بــأن ملوكلــه الرجــوع‬\n      ‫بطلــب أتعــاب احملامــاة ممــن فــرط وحتمــل ببطــان البيــع كمــا قــررت‬\n      ‫التهميــش علــى صــك العقــار مبوجــب هــذا احلكــم بعــد اكتســابه‬\n      ‫للقطعيــة ‪ ،‬وكان ختــام هــذه اجللســة عنــد الســاعة ‪ 11 : 30‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                           ‫حــرر يف ‪ 1434/02/10‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/08/06‬ه ـ ويف‬\n      ‫متــام الســاعة ‪ 12 : 30‬افتتحــت اجللســة وقــد عــادت املعاملــة رفــق خطــاب‬\n      ‫رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم ‪ 34156474017‬يف‬\n      ‫تاريــخ ‪1434/07/25‬ه ـ مرفقــا بهــا قــرار الدائــرة احلقوقيــة األولــى رقــم‬\n      ‫‪ 34269903‬يف ‪1434/07/16‬ه ـ واملتضمــن نــص احلاجــة منــه وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مذيــا عليــه‬\n      ‫بتوقيــع قضــاة االســتئناف ‪ ...:‬و ‪ ...‬و ‪...‬و حتــى ال يخفــى جــرى احلاقــة‬\n      ‫وأمرنــا بالتهميــش وكان ختــام هــذه اجللســة الســاعة ‪ 12 : 45‬وبــاهلل‬\n      ‫التوفيق ‪ ،‬وصلى اهلل وسلم على نبينا محمد‪ .‬حرر يف ‪1434/08/06‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بجــازان برقــم ‪ 33381886‬وتاريــخ‬\n      ‫‪1434/06/18‬هــ‪ ،‬املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n      ‫‪...‬برقــم ‪ 3436000‬وتاريــخ ‪1434/02/12‬ه ـ اخلــاص بدعــوى ‪ ... /‬ضــد‬\n      ‫‪... /‬يف أرض املتضمــن احلكــم مبــا هــو مــدون بالصــك ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n\n\n‫‪365‬‬\n\f‫تقــرر الدائــرة املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى‬\n                                      ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪366‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":357,"source_page_end":366,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5194931ed79d6ca6a1e80504d7d9ef5b58711917ba0e6bed0663cfe4f8890473","normalized_text_hash":"995f4b2b59c81226ce6a44dd02712a2daf65347010308f2ddc75b710d4cee4bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p357-3436000"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"768c6da8-5713-53d2-be80-0591d00151d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -التملك الصوري للعقار -صندوق التنمية العقاري -اتفاق على سداد أقساط قرض -سداد أجرة سكن عائلي مشترك -صورية متلك العقار -شهادة غير منتجه يف الدعوى -ضم صورة صك سابق إلى الدعوى القائمة -حتول العقد الصوري إلى حقيقي - صرف النظر عن الدعوى ما أستند إليه القاضي من املبادئ العامة وقواعد العدالة يف تسبيب","document_number":"33473941","case_number":"5048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/20","year":"1434","subject":"عقار -التملك الصوري للعقار -صندوق التنمية العقاري -اتفاق على سداد أقساط قرض -سداد أجرة سكن عائلي مشترك -صورية متلك العقار -شهادة غير منتجه يف الدعوى -ضم صورة صك سابق إلى الدعوى القائمة -حتول العقد الصوري إلى حقيقي - صرف النظر عن الدعوى ما أستند إليه القاضي من املبادئ العامة وقواعد العدالة يف تسبيب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33473941:‬تاريخه ‪1433/12/20:‬هـ‬\n                              ‫رقم الدعوى ‪5048 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3362490‬تاريخه‪1433/02/06 :‬هـ‬\n\n\n       ‫عقــار ‪ -‬التملــك الصــوري للعقــار ‪ -‬صنــدوق التنميــة العقــاري ‪ -‬اتفــاق‬\n       ‫على ســداد أقســاط قرض ‪ -‬ســداد أجرة ســكن عائلي مشــترك ‪ -‬صورية‬\n       ‫متلــك العقــار ‪ -‬شــهادة غيــر منتجــه يف الدعــوى ‪ -‬ضــم صــورة صــك‬\n       ‫ســابق إلــى الدعــوى القائمــة ‪ -‬حتــول العقــد الصــوري إلــى حقيقــي ‪-‬‬\n                                                       ‫صــرف النظــر عــن الدعــوى‬\n\n\n\n\n       ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                             ‫حكمه‬\n\n\n\n       ‫تقــدم املدعــي بدعــوى ضــد املدعــى عليــه «شــقيقه» بــأن مــن اجلــاري يف‬\n       ‫ملكــه البيــت املســجل باســمه مبوجــب صــك شــرعي وقــد نــال ألجلــه‬\n       ‫قرضــا مــن صنــدوق التنميــة العقــاري وكان يعمــل يف مدينــة أخــرى‬\n       ‫ووالــده وبعــض أخوتــه يســكنون يف البيــت محــل النــزاع ومــن بينهــم‬\n       ‫املدعــى عليــه ويف عــام ‪1410‬ه ـ اتفــق خمســة مــن اإلخــوة ومعهــم املدعــى‬\n       ‫عليــه علــى أن يقومــوا باملشــاركة يف دفــع جــزء مــن قســط القــرض‬\n       ‫الســنوي ويكــون علــى كل واحــد منهــم ألفــان وأربعمئــة ريــال يدفعهــا‬\n       ‫كل ســنة وألن املدعــى عليــه بقــي يف العقــار أحــدى عشــرة ســنة فيطلــب‬\n       ‫إلزامــه بدفــع أربعــة وعشــرين ألــف ريــال ‪ ،‬أنكــر املدعــى عليــه الدعــوى‬\n‫‪309‬‬\n\f‫ودفــع بــأن املنــزل ملــك لوالــده حقيقــة آلــت أرضــه إليــه مبنحــة مــن األمانة‬\n‫وألنــه ســبق وأن اقتــرض مــن صنــدوق التنميــة فقــد طلــب مــن املدعــي أن‬\n‫يتقــدم بطلــب قــرض عليهــا فجــرى تســجيل األرض باســمه صوريــا وإال‬\n‫فــإن مــن بنــاه والــده وقــد دفــع قســطني وأعفــي مــن قســطني ولــو طلــب‬\n‫والــده منــه دفــع أي مبلــغ لوافــق ويف أزمــة اخلليــج وملــا كثــرت العوائــل يف‬\n‫البيــت طلــب والــده مــن اإلخــوة أن يرســل كل منهــم ألفــن وخمســمئة‬\n‫ريــال شــهريا فاجتمــع لديــه مبلغــا وطلــب املدعــي الــزواج فدفــع لــه‬\n‫ســتني ألــف ريــال ثــم طلــب مــن والــده تســليمه الصــك فلمــا ســلمه لــم‬\n‫يــرده إليــه حتــى اآلن حتــى قــام والــده بإقامــة دعــوى ضــده إلثبــات متلــك‬\n‫البيــت ‪ -‬حضــر والــد املتداعيــن وقــرر بــأن مــا ورد يف دعــوى املدعــي‬\n‫غيــر صحيــح وأن الصحيــح بــأن أوالده قامــوا بإعطائــه مــاال أيــام أزمــة‬\n‫اخلليــج عــدا املدعــي فلــم يســلمه شــيئا بــل وهبــه ســتني ألــف ريــال لزواجــه‬\n‫وأنــه مــن قــام ببنــاء البيــت بــا مشــاركة مــن املدعــي ‪ -‬أحضــر املدعــي‬\n‫شــاهدا أحــد إخوتــه وشــهد باتفــاق اإلخــوة علــى أن يدفــع كل واحــد‬\n‫منهــم ألفــن وأربعمئــة ريــال لســداد القــرض عــن املدعــي ‪ -‬بعــرض‬\n‫الشــهادة علــى املدعــى عليــه أنكرهــا ‪ -‬جــرى اطــاع الدائــرة علــى‬\n‫صــورة صــك املتضمــن دعــوى والــد املدعــي ضــده وقــد أقــر فيــه صراحــة‬\n‫بــأن اإلفــراغ لــه كان صوريــا وأحيلــت املعاملــة ملكتــب الصلــح وتضمــن‬\n‫ثبــوت الصلــح بينهمــا علــى إبقــاء العقــار مســجال باســم املدعــي مقابــل‬\n‫مئــة ألــف ريــال ‪ -‬عليــه وحيــث حضــر والــد املتداعيــن وأفــاد أن أصــل‬\n‫متلــك البيــت احلقيقــي لــه ومتلــك املدعــي للعقــار متلــكا صوريــا وصــادق‬\n‫املدعــي علــى ذلــك بــل اصطلــح مــع أبيــه علــى أن يدفــع لــه مئــة ألــف ريــال‬\n‫ودفعهــا لــذا لــم حتصــل ملكيــة املدعــي للبيــت متلــكا حقيقيــا إال بعــد‬\n\n\n                                                                                        ‫‪310‬‬\n\f      ‫الصلــح وألن مطالبــة املدعــي باســتحقاق املبلــغ املدعــى بــه قبــل متلكــه‬\n      ‫للبيــت متلــكا حقيقــا لذلــك كلــه فقــد قــررت الدائــرة صــرف النظــر‬\n      ‫عــن دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه مــن هــذه القضيــة ‪ -‬قــرر‬\n      ‫املدعــي االعتــراض فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باخلــرج برقــم ‪ 5048‬وتاريــخ ‪ 1431/08/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3120003‬وتاريــخ ‪ 1431/08/01‬ه ـ ففــي‬\n      ‫يــوم االربعــاء املوافــق‪ 1432/04/25‬ه ـ أفتتحــت اجللســة وفيهــا حضــر‬\n      ‫‪ ................‬سعودي اجلنسية مبوجب السجل املدني رقم ……………‪.‬‬\n      ‫وادعــى علــى احلاضــر معه ‪ ................... /‬ســجله املدني رقــم ‪...................‬‬\n      ‫قائــا يف دعــواه إن مــن اجلــاري يف ملكــي وحتــت تصــريف كامــل البيــت‬\n      ‫الفيــا مكونــة مــن دوريــن مســتقلني يقــع يف حــي الســعودية يف اخلــرج‬\n      ‫اململوكــة لــي بالصــك الصــادر مــن كتابــة عــدل اخلــرج برقــم ‪1/230‬‬\n      ‫يف ‪1403/4/11‬ه ـ وقــد اقترضــت عليهــا مــن صنــدوق التنميــة العقاريــة‬\n      ‫مبلغــا قــدره ثالثمائــة ألــف ريــال وكنــت أعمــل يف املنطقــة الشــرقية‬\n      ‫وقــد رغــب والــدي ســكن الفيــا وطلــب مــن أخوتــي الســكن معــه ومــن‬\n      ‫ضمنهــم املدعــى عليــه ويف عــام ‪1410‬ه ـ اتفقنــا نحــن األخــوة اخلمســة‬\n      ‫أنــا ‪ ...........‬واملدعــى عليــه و‪ ...........‬و‪ .......‬و‪ .........‬و‪ ............‬علــى تقســيم‬\n      ‫القســط الســنوي لصنــدوق التنميــة العقاريــة البالــغ اثنــا عشــر ألــف ريــال‬\n\n‫‪311‬‬\n\f‫علينــا نحــن اخلمســة فبلــغ نصيــب الواحــد ألفــان وأربعمائــة ريــال يدفعهــا‬\n‫كل شــخص عــن كل ســنة وقــد بقــي املدعــى عليــه يف الســكن مــن‬\n‫عــام ‪1410‬ه ـ إلــى عــام ‪1421‬ه ـ وبلــغ إجمالــي ماعليــه عشــر ســنني أي‬\n‫أربعــة وعشــرون ألــف ريــال وصنــدوق التنميــة العقاريــة الزال يطالبنــي‬\n‫أطلــب احلكــم علــى املدعــى عليــه وإلزامــه بــأن يدفــع هــذا املبلــغ لــي‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه قــال ال صحــة جلميــع ماذكــره‬\n‫املدعــي جملــة وتفصيــا وذلــك أن البيــت يف األســاس لوالدنــا وأرضــه‬\n‫منحــه عــن طريــق بلديــة اخلــرج كغيرهــا مــن أراضــي حــي الســعودية‬\n‫وســبق للوالــد أن أقتــرض مــن صنــدوق التنميــة العقاريــة يف املدينــة (‬\n‫محافظــة خيبــر) وألن املدعــي يف ذلــك الوقــت يحمــل بطاقــة األحــوال‬\n‫جعــل والدنــا البيــت بإســم املدعــي صوريــا ووالــدي هــو الــذي يدفــع‬\n‫قــرض صنــدوق التنميــة ودفــع قســطني وأعفــي مــن قســطني وهــو الــذي‬\n‫يتصــرف يف البيــت ولــو طلــب منــا دفــع أي مبلــغ دفعنــاه وقــد اجتمعــت‬\n‫عوائلنــا يف البيــت عــام ‪1410‬ه ـ يف بدايــة أزمــة اخلليــج األولــى ولــم أكــن‬\n‫وقتهــا متزوج ـ ًا وحــن كثــرت العائلــة يف املنــزل حيــث أنــا أربعــة أخــوة‬\n‫يف اجلبهــة وعوائــل أخوانــي عنــد والــدي طلــب منــا الوالــد أن يرســل كل‬\n‫واحــد منــا شــهريا ألفــن وخمســمائة ريــال واجتمــع عنــد والدنــا مبلغــا‬\n‫وقــد طلــب املدعــي الــزواج فدفــع عنــه الوالــد ســتني ألــف ريــال ثــم أن‬\n‫املدعــي طلــب مــن والــدي أن يســلم صــك البيــت مــن أجــل أن يســقط‬\n‫قــرض الصنــدوق فســلمه لــه ولــم يعــده لوالــدي حتــى أقــام والــدي دعــوى‬\n‫ضــد املدعــي وذلــك مــن أجــل إثبــات متلكــه للبيــت متلــك ًا حقيقيــا حيــث‬\n‫أن متلــك املدعــي متلــكا صوريــا هكــذا اجاب كماحضــر ‪................. /‬‬\n‫ســجله املدنــي رقــم ‪ ..................‬وهــو والــد املدعــي واملدعــى عليــه وجــرى‬\n\n\n                                                                                         ‫‪312‬‬\n\f      ‫ســؤاله عمــا لديــه فقــال إن جميــع أقــوال املدعــي غيــر صحيحــة وأنــا‬\n      ‫حــن كنــت يف البيــت قــام األخــوة األربعــة ‪ ...‬و‪...‬و‪ ...‬و‪...‬مبواصلتــي باملــال‬\n      ‫وقــت األزمــة أمــا املدعــي فإنــه مقيــم مــع عائلتــه يف الشــرقية ولــم يدفــع‬\n      ‫ولــو ريــاال واحــدا بــل إننــي دفعــت عنــه يف زواجــه ســتني ألــف ريــال وأنــا‬\n      ‫الــذي قمــت ببنــاء العقــار ووقــف عنــد العظــم وهــو بإســم املدعــي ألننــي‬\n      ‫ســبق أن اقترضــت مــن صنــدوق التنميــة العقاريــة والأرى املدعي يســتحق‬\n      ‫املبلــغ الــذي يطالــب بــه ألنــه لــم يخســر ولــو ريــاال واحــدا وبعرضــه علــى‬\n      ‫املدعــي قــال الصحيــح ماذكــرت ولــدي البينــة علــى ذلــك أخــي ‪........‬‬\n      ‫وســبق حضــوره ‪ ........‬يف يــوم لــم يحــدد فيــه جلســة ومت تدويــن شــهادته‬\n      ‫يف حينــه ووعــد باحلضــور هــذا اليــوم وهــذا نــص شــهادته أشــهد هلل أننــا‬\n      ‫اجتمعنــا نحــن األخــوة أنــا ‪ ........‬و‪ .........‬و‪ ..........‬و‪ ............‬و‪ ...........‬عــام‬\n      ‫‪1410‬ه ـ واتفقنــا علــى أن يدفــع كل واحــد منــا يف كل ســنة ألفــن‬\n      ‫وأربعمائــة ريــال لســداد قــرض صنــدوق التنميــة العقاريــة علــى املنــزل‬\n      ‫الــذي نســكن فيــه مــع والدنــا والقــرض بإســم املدعــي ‪ .......‬ويف عــام‬\n      ‫‪1425‬ه ـ ورد لنــا إنــذار مــن صنــدوق التنميــة لإلســراع بســداد قــرض‬\n      ‫الصنــدوق وبلــغ إجمالــي األقســاط احلالــة مئتــان وثالثــون ألــف ريــال ولــم‬\n      ‫يســدد القــرض إلــى اآلن هــذا مالــدي وبــه أشــهد) ويف الســاعة الواحــدة‬\n      ‫وخمســة وثالثــن دقيقــة أحضــر ‪ ......................‬وجــرى ســؤال املدعــى‬\n      ‫عليــه عــن شــهادة الشــاهد فقــال الأقــول يف الشــاهد شــيئا وشــهادته‬\n      ‫غيــر صحيحــة ألنــه متعاطــف ومتاليــن مــع املدعــي ولــم جنتمــع ولــم نتفــق‬\n      ‫علــى دفــع مبلــغ معــن ولضيــق الوقــت والتأمــل رفعــت اجللســة وعليــه‬\n      ‫حصــل التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1432/04/25‬ه ـ‬\n\n\n‫‪313‬‬\n\f‫ويف يــوم الثالثــاء املوافــق‪ 1433/04/13‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــر املدعــي وحضــر حلضــوره املدعــى عليــه وجــرى اإلطــاع علــى‬\n‫أوراق املعاملــة ومــن بينهــا صــورة الصــك الصــادر مــن هــذه احملكمــة‬\n‫برقــم ‪ 42/8/54‬يف ‪1428/8/12‬ه ـ ويتضمــن إقامــة دعــوى مــن والــد‬\n‫املدعــي (هنــا) ‪ .....................‬ضــد املدعــي ويطلــب املدعــي مــن املدعــى‬\n‫عليــه أن يفــرغ الصــك رقــم ‪ 3/230‬يف ‪1403/4/11‬ه ـ الصــادر مــن‬\n‫كتابــة عــدل اخلــرج لــه ألن بقــاء الصــك بإســم املدعــى عليــه (املدعــي‬\n‫هنــا) كان صوريــا وقــد أجــاب املدعــى عليــه بقولــه صحيــح أن اإلفــراغ‬\n‫بإســمي صوريــا وأحيلــت املعاملــة ملكتــب الصلــح وذيــل الصــك بــأن‬\n‫املدعــي واملدعــى عليــه اصطلحــا علــى أن يدفــع املدعــى عليــه (املدعــي‬\n‫هنــا ) ألبيــه مائــة ألــف ريــال ويبقــى الصــك بإســم املدعــى عليــه (املدعــي‬\n‫هنــا) ومبناقشــة املدعــي عــن ذلــك قــال إن والــدي مت حتريضــة مــن‬\n‫املدعــى عليــه ‪ ...‬ورغبــة منــي يف عــدم اســتمرار الدعــوى بينــي وبــن‬\n‫والــدي اســتعديت بدفــع مائــة ألــف ريــال ودفعتهــا لــه وليــس لــدي بينــة‬\n‫ســوى أخــي ‪ ........‬ومســتعد بإحضــار معدلــن لــه وأكمــل بينتــي باليمــن‬\n‫علــى صحــة دعــواي وبعرضــه علــى املدعــى عليــه قــال كمــا ذكــرت أن‬\n‫شــهادة اخــي ‪ ......‬غيــر صحيحــة فســألته هــل لديــه طعــن يف اخيــه ‪.........‬‬\n‫فقــال ليــس لــدي بينــة غيــر بيــان والــدي وألن القضيــة حتتــاج ملزيــد تأمــل‬\n‫رفعــت اجللســة وعليــه حصــل التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/13‬ه ـ‬\n‫ويف يــوم االثنــن املوافــق ‪1433/12/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي وحضــر حلضــوره املدعــى عليــه وجــرى تأمــل الدعــوى واإلجابــة‬\n‫وحيــث حضــر والــد املدعــي ووالــد املدعــى عليــه وأفــاد أن أصــل متلــك‬\n\n\n                                                                                      ‫‪314‬‬\n\f      ‫البيــت احلقيقــي بإســمه هــو ومتلــك املدعــي متلــكا صوريــا وصــادق‬\n      ‫املدعــي علــى ذلــك بــل اصطلــح مــع أبيــه علــى أن يدفــع لــه مائــة ألــف‬\n      ‫ريــال ودفعهــا ولــم تتــم ملكيــة املدعــي للبيــت متلــكا حقيقيــا إال بعــد‬\n      ‫دفــع املبلــغ واملدعــي يطالــب بإســتحقاق املبلــغ املدعــى بــه قبــل متلكــه‬\n      ‫للبيــت متلــكا حقيقــا لذلــك كلــه فقــد صــرف النظــر عــن دعــوى‬\n      ‫املدعــي وأخليــت ســبيل املدعــى عليــه مــن هــذه القضيــة وبــه حكمــت‬\n      ‫حتريــرا يف ‪1433/12/20‬ه ـ وبعرضــه علــى الطرفــن قنــع املدعــى عليــه‬\n      ‫ولــم يقنــع املدعــي وطلــب رفعــه حملكمــة االســتئناف بالئحــة فأجيــب‬\n      ‫لطلبــه وأفهــم باملراجعــة هــذا اليــوم بإســتالم نســخة مــن احلكــم لتقــدمي‬\n      ‫الئحــة اعتــراض عليهــا يف مــدة اقصاهــا ثالثــون يومــا مــن التاريــخ‬\n      ‫املذكــور وإن لــم يتقــدم بإعتــراض خــال تلــك املــدة فيســقط حقــه يف‬\n      ‫االســتئناف ويكتســب احلكــم القطعيــة وصلــى اهلل علــى نبينــا محمــد‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق ‪1434/6/24‬ه ـ افتتحــت‬\n      ‫اجللســة بعــد أن عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقــرار‬\n      ‫رقــم ‪ 34173321‬يف ‪1434/3/28‬ه ـ واخلاصــة بدعــوى ‪ ...‬ضــد ‪ ...‬وجــاء‬\n      ‫فيــه بعــد املقدمــة وبدراســة الصــك وصــورة ضبطــه والالئحــة وأوراق‬\n      ‫املعاملــة لوحــظ أن املدعــي ذكــر يف الالئحــة اإلعتراضيــة وجــود حكــم‬\n      ‫مميــز باألجــرة فيناقــش عــن ذلــك وترفــق صــورة لهــذا الصــك ومــا عليــه‬\n      ‫مــن تظهيــرات واهلل املوفــق وجوبــا عليــه فقــد أفــاد املدعــي أن لــه دعــوى‬\n      ‫مماثلــة منظــورة لــدى فضيلــة الشــيخ ‪ . ...................‬املكتــب القضائــي‬\n      ‫العاشــر ضــد أخيــه ‪ ................‬وبنــاء عليــه فقــد جــرى منــا مخاطبــة‬\n      ‫فضيلة الشيخ ‪ ...........‬بإرفاق ما لديه وذلك بخطابنا رقم ‪341509806‬‬\n      ‫وتاريــخ ‪1434/6/21‬ه ـ فوردنــا جــواب فضيلتــه برقــم ‪341509806‬‬\n\n\n‫‪315‬‬\n\f‫وتاريــخ ‪1434/6/24‬ه ـ املرفــق بــه صــورة مــن الصــك الصــادر منــه برقــم‬\n‫‪ 32146958‬وتاريــخ ‪1432/6/28‬ه ـ كمــا أرفــق تظهيــر محكمــة‬\n‫االســتئناف بالقــرار رقــم ‪ 3362490‬وتاريــخ ‪1433/2/6‬ه ـ املتضمــن‬\n‫املصادقــة علــى احلكــم الصــادر منــه وبذلــك فإنــه لــم يظهــر لــي خــاف‬\n                                         ‫مــا حكمــت بــه واهلل املوفــق للصــواب ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n‫مــن رئيــس احملكمــة العامــة باخلــرج املكلــف الشــيخ‪........................../‬‬\n‫برقــم ‪ 34463597‬وتاريــخ ‪1434/6/25‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلتــه واملســجل برقــم ‪ 33473941‬وتاريــخ ‪1433/12/20‬ه ـ‬\n‫اخلــاص بدعــوى‪ ............../‬ضــد‪ .................../‬يف مبلــغ مالــي علــى الصفــة‬\n‫املوضحــة بالصــك واملتضمــن حكــم فضيلتــه كمــا هــو موضــح يف‬\n‫الصــك وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لــم يظهــر مايوجــب االعتــراض علــى احلكــم‪ .‬واهلل املوفق وصلى‬\n                                    ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                         ‫‪316‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":309,"source_page_end":316,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7850453ced637e1e9c0d69b1919e7c994a3d4a653499ebd2b8b75459a9d855d8","normalized_text_hash":"82ff9b6de07c33dc07f14a5f1d42e7c5925e93a85f9d18f0fbea6b9d54b5da17","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p309-33473941"},{"id":"7a2b8967-7d08-5acc-92e4-6fb6d5a6bf48","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -اعتداء على أرض بوضع كيبل -مطالبة باإلزالة والتعويض يف اتعاب التقاضي -دفع بوجود ترخيص من جهة مخولة وطلب الرجوع للجهة املانحة للترخيص -تقرير أهل اخلبرة -احلكم على املباشر واملستفيد -إلزام املدعى عليها باإلزالة والتعويض.","document_number":"34241641","case_number":"346844","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":"الدائرة احلقوقية الرابعة يف محكمة الاستئناف مبكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/14","year":"1434","subject":"عقار -اعتداء على أرض بوضع كيبل -مطالبة باإلزالة والتعويض يف اتعاب التقاضي -دفع بوجود ترخيص من جهة مخولة وطلب الرجوع للجهة املانحة للترخيص -تقرير أهل اخلبرة -احلكم على املباشر واملستفيد -إلزام املدعى عليها باإلزالة والتعويض.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34241641:‬تاريخه ‪1434/06/14:‬ه‬\n                           ‫رقم الدعوى ‪346844:‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34297233:‬تاريخه‪1434/08/15:‬هـ‬\n\n\n      ‫عقــار ‪ -‬اعتــداء علــى أرض بوضــع كيبــل ‪ -‬مطالبة باإلزالة والتعويض‬\n      ‫يف اتعــاب التقاضــي ‪ -‬دفــع بوجــود ترخيــص مــن جهــة مخولــة وطلــب‬\n      ‫الرجــوع للجهــة املانحــة للترخيــص ‪ -‬تقريــر أهــل اخلبــرة ‪ -‬احلكــم‬\n         ‫علــى املباشــر واملســتفيد ‪ -‬إلــزام املدعــى عليهــا باإلزالــة والتعويــض‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه‪.‬‬\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد أحــد مشــغلي شــبكة االتصــاالت بأنهــا‬\n      ‫اعتــدت علــى جهــة مــن أرضــه حيــث أدخلــت يف أرضــه كيبــا وطلــب‬\n      ‫إلــزام الشــركة بإزالتــه وتعويضــه عــن فتــرة بقــاء الكيبــل يف أرضــه‬\n      ‫وأجــرة أتعابــه يف القضيــة ‪ -‬أقــر وكيــل املدعــى عليهــا بوجــود الكيبــل‬\n      ‫ودفــع بــأن موكلتــه ال تقــوم بذلــك إال بنــاء علــى ترخيــص مــن وزارة‬\n      ‫النقــل وأنهــا ال تعلــم إن كان الكيبــل يختــرق أرضــه أم ال وأن عليــه‬\n      ‫أن يثبــت بــأن موكلتــه جتــاوزت حــدود الترخيــص املمنــوح لهــا ليســتحق‬\n      ‫مــا يدعيــه ‪ -‬أبــرز املدعــي صــك امللكيــة وجــرى االستفســار عــن ســجله‬\n      ‫فظهــر بأنــه ســاري املفعــول ‪ -‬جــرت الكتابــة لهيئــة اخلبــراء للتحقــق مــن‬\n\n‫‪317‬‬\n\f‫اختــراق الكيبــل ألرض املدعــي فعــادت اإلفــادة بأنــه جــرى الشــخوص‬\n‫للموقــع وبتطبيــق الصــك ظهــر بــأن الكيبــل يختــرق أرض املدعــي‬\n‫جــرى تقديــر األجــرة الشــهرية املســتحقة للمدعــي أمــا تقديــر أجــرة‬\n‫أتعابــه فيتعــذر عليهــم ذلــك حتــى االنتهــاء مــن القضيــة ‪ -‬بعــرض القــرار‬\n‫علــى املدعــي قــرر القناعــة بــه أمــا وكيــل املدعــى عليهــا فقــد طلــب‬\n‫صــرف النظــر عــن دعــوى املدعــي وإفهامــه بــأن لــه الرجــوع علــى اجلهــة‬\n‫املانحــة للترخيــص ‪ -‬قــرر املدعــي بأنــه يقصــر مطالبتــه بإزالــة الكيبــل‬\n‫وتعويضــه عــن الفتــرة املاضيــة ‪ -‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وملصادقــة املدعــى عليــه علــى أن الكيبــل يعــود ملوكلتــه وأنــه‬\n‫مت وضعــه يف املــدة التــي ذكــر املدعــي بنــاء علــى ترخيــص وزارة النقــل‬\n‫وملــا جــاء يف قــرار قســم اخلبــراء مــن أن الكيبــل ميــر بــأرض املدعــي‬\n‫بالطــول املذكــور يف التقريــر وتقديــر أجرتــه وألن املباشــر لالعتــداء‬\n‫واملســتفيد منــه هــي املدعــى عليهــا والكيبــل يعــود لهــا والعبــرة مبــن‬\n‫باشــر االعتــداء وباحتســاب املــدة املاضيــة وجــدت اثنــن وخمســن شــهر ًا‬\n‫حتــى تاريــخ ‪1434/06/15‬ه ـ وأجرتهــا مبلــغ مائــة وثالثــن ألــف ريــال‬\n‫لــذا فقــد أفهمــت املدعــى عليــه وكالــة أنــه يلــزم موكلتــه رفــع الكيبــل‬\n‫عــن أرض املدعــي موضــع الدعــوى يف موعــد أقصــاه ‪1434/6/15‬ه ـ‬\n‫ودفــع أجــرة املــدة املاضيــة وقدرهــا مائــة وثالثــون ألــف ريــال ويف حــال‬\n‫تأخرهــا عــن رفــع الكيبــل يف املوعــد احملــدد فيلزمهــا دفــع أجرة شــهرية‬\n‫قدرهــا ألفــان وخمســمائة ريــال شــهري ًا ومبــا تقــدم حكمــت ‪ -‬وبعــرض‬\n‫ذلــك علــى الطرفــن أبــدى املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه‬\n‫فلــم يقنــع باحلكــم فأفهــم بالتعليمــات ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                    ‫االســتئناف‪.‬‬\n\n\n                                                                                   ‫‪318‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬مســاعد رئيــس احملكمــة‬\n      ‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 346844‬وتاريــخ‬\n      ‫‪1434/01/05‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3431147‬وتاريــخ‬\n      ‫‪1434/1/5‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/01/20‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر (‪ )........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )........‬كمــا حضــر (‪)........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬بالوكالــة عــن (‪)........‬‬\n      ‫ا عــن (‪ )........‬و(‪ )........‬و(‪ )........‬و(‪)........‬‬\n                                                          ‫ا عــن نفســه ووكي ـ ً‬\n                                                                               ‫أصي ـ ً‬\n      ‫و(‪ )........‬و(‪ )........‬و(‪ )........‬و(‪ )........‬و(‪ )........‬بصفتهــم مــن أعضــاء‬\n      ‫مجلــس (‪ )........‬مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف‬\n      ‫بــوزارة التجــارة والصناعــة برقــم ‪ 6827‬وتاريــخ ‪1433/10/23‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح‬\n      ‫وحضــور اجللســات وإقامــة وســماع الدعــاوى وجــرى ســؤال املدعــي عــن‬\n      ‫دعــواه فقــال لقــد قامــت املدعــى عليهــا باالعتــداء علــى أرضــي الواقعــة‬\n      ‫يف (‪ )........‬باملدينــة اململوكــة لــي بالصــك الصــادر مــن كتابــة عــدل‬\n      ‫املدينــة برقــم ‪ 5/6/215‬وتاريــخ ‪1421/4/7‬ه ـ حيــث اعتــدت علــى اجلهة‬\n      ‫اجلنوبيــة مــن أرضــي احملــدودة بطريــق ينبــع املدينــة الســريع حيــث دخلــت‬\n      ‫يف أرضــي بعمــق ثالثــة أمتــار وبطــول أربعــن متــر ًا مــن أرضــي وذلــك‬\n      ‫بوضــع كيبــل أرضــي فيهــا بتاريــخ ‪1430/2/15‬ه ـ ومــن ذلــك التاريــخ‬\n      ‫وأنــا أطالبهــم برفــع يدهــم عــن أرضــي وتعويضــي عــن ذلــك وهــم يعدونــي‬\n\n‫‪319‬‬\n\f‫بذلــك لكــن لــم يلتزمــوا بــه أطلــب إلزامهــم برفــع يدهــم عــن أرضــي‬\n‫وترحيــل الكيبــل وتعويضــي عــن أجــرة األرض للمــدة املاضيــة وأجــرة‬\n‫أتعابــي يف مطالبتهــم هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى‬\n‫عليــه أبــرز ورقــة قــال إن جوابــي مــدون فيهــا وباالطــاع عليهــا وجــدت‬\n‫تتضمــن مــا يلــي أو ًال ‪ :‬إن موكلتنــا ال ميكــن أن تقــوم بأعمــال متديــد‬\n‫الكيبــات وحفــر األراضــي العامــة دون احلصــول علــى ترخيــص صــادر‬\n‫ـاء‬\n ‫مــن اجلهــات الرســمية حيــث مت إنشــاء الكيبــل محــل هــذه الدعــوى بنـ ً‬\n‫علــى ترخيــص صــادر مــن اإلدارة العامــة للطــرق والنقــل مبنطقــة املدينــة‬\n‫املنــورة بــوزارة النقــل برخصــة رقــم ‪ 1182/06‬وتاريــخ ‪1430/02/15‬ه ـ‬\n‫واملوقعــة مــن قبــل مديــر عــام إدارة الطــرق والنقــل مبنطقــة املدينــة املنــورة‬\n‫ثاني ًا ‪ :‬إن موكلتنا حريصة كل احلرص على إعطاء كل ذي حق حقه‬\n‫عنــد ثبــوت وقــوع تتجــاوز مــن طرفهــا وضــرر فعلــي علــى الغيــر وحيــث‬\n‫أن املدعــي لــم يقــدم البينــة علــى مــا ادعــاه مــن وقــوع تعــدي مــن قبــل‬\n‫موكلتنــا علــى األرض التــي يدعــي ملكيتهــا ولــم يقــدم أي مســتندات‬\n‫يثبــت فيهــا وقــوع التعــدي الــذي يدعيــه خــال املــدة التــي يدعيهــا وحيــث‬\n‫أن موكلتنــا ممنوحــة الترخيــص املرفــق مــن وزارة النقــل والــذي يخولهــا‬\n‫صالحيــة القيــام بأعمــال متديــدات محــل الدعــوى فــإن علــى املدعــي‬\n‫إثبــات وقــوع التعــدي وإثبــات جتــاوز موكلتنــا حلــدود الترخيــص املمنــوح‬\n‫لهــا و إال فليــس لــه وجــه حــق يف توجيــه هــذا اإلدعــاء علــى موكلتنــا‬\n‫وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه واملدعــى عليهــا‬\n‫قــد اعتــدت بالطــول الــذي ذكــرت علــى أرضــي التــي أملكهــا مبوجــب‬\n‫الصــك الــذي ذكــرت وأبــرز أصــل صــك امللكيــة الصــادر مــن كتابــة‬\n‫عــدل املدينــة برقــم ‪ 5/6/215‬وتاريخــه ‪1421/04/07‬ه ـ املتضمــن‬\n\n\n                                                                                         ‫‪320‬‬\n\f      ‫متلــك املدعــي للقطعــة رقــم ‪ 1855‬مــن املخطــط رقــم ‪/1‬ف‪/1411/‬ه ـ‬\n      ‫الواقــع يف (‪/ )........‬ه ـ واحملــدودة شــما ًال القطعــة رقــم ‪ 1856‬بطــول‬\n      ‫أربعــن متــر ًا وشــرق ًا شــارع‪ 2 0‬متــر ًا بطــول عشــرين متــر ًا وغربـ ًا البعــض‬\n      ‫القطعــة رقــم ‪ 1852‬والبعــض القطعــة رقــم ‪ 1851‬بطــول عشــرين متــر ًا‬\n      ‫ومجمــوع مســاحتها ثمامنائــة متــر مربــع واملهمــش عليــه بنــزع ملكيــة‬\n      ‫جــزء مــن العقــار واقــع يف اجلهــة اجلنوبيــة وحــدود وذرعــة اجلــزء املتبقــي‬\n      ‫مــن العقــار جنوبـ ًا البعــض طريــق املدينــة ينبــع الســريع بعــرض مائــة متــر‬\n      ‫والبعــض اجلــزء املتبقــي مــن القطعــة ‪ 1856‬بطــول مــن شــرق لغــرب تســعة‬\n      ‫وعشــرين متــر ًا وســتة وســتني ســنتيمتر ثــم عشــرة أمتــار وثالثــة وتســعني‬\n      ‫ســنتيمتر وشــما ًال القطعــة رقــم ‪ 1854‬بطــول أربعــن متــر ًا وشــرق ًا شــارع‬\n      ‫عــرض عشــرين متــر بطــول أربعــة عشــر متــر ًا وخمســة عشــر ســنتيمتر‬\n      ‫وغرب ـ ًا البعــض اجلــزء املتبقــي مــن القطعــة رقــم ‪ 1852‬والبعــض القطعــة‬\n      ‫رقــم ‪ 1851‬بطــول عشــرين متــر واملســاحة اإلجماليــة ســبعمائة وخمســة‬\n      ‫عشــر متــر ًا وخمســة ســنتيمترات مربعــة كمــا أضــاف املدعــي بــأن‬\n      ‫املدعــى عليهــا قــد انحرفــت عــن املســار املخصــص لهــا مــن قبــل وزارة‬\n      ‫النقــل وهــو داخــل حــرم الطريــق وخرجــت عــن ذلــك ودخلــت يف أرضــي‬\n      ‫بعمــق ثالثــة أمتــار هكــذا قــرر ثــم طلــب الطرفــان الكتابــة لقســم‬\n      ‫اخلبــراء للوقــوف علــى املوقــع وتطبيــق صــك املدعــي واإلفــادة عمــا ذكره‬\n      ‫املدعــي والتأكــد مــن مــكان الكيبــل وهــل هــو داخــل أرض املدعــي أم‬\n      ‫يف اجلــزء املنــزوع منــه لصالــح حــرم الطريــق ثــم يف جلســة أخــرى وردتنــا‬\n      ‫إفــادة قســم اخلبــراء رقــم ‪ 3431147‬وتاريــخ ‪1434/04/03‬ه ـ املتضمــن‬\n      ‫أنــه أثنــاء الوقــوف علــى الطبيعــة كان الكيبــل مدفون ـ ًا ومت حتديــد‬\n      ‫مســاره مــن قبــل منــدوب شــركة (‪ )........‬املشــارك واتضــح مــن ذلــك أنــه‬\n\n\n‫‪321‬‬\n\f‫ميــر داخــل أرض املدعــي وباالطــاع علــى طيــات املعاملــة وجــد خطــاب‬\n‫مديــر عــام إدارة الطــرق والنقــل مبنطقــة املدينــة املنــورة رقــم ‪672706‬‬\n‫يف ‪1432/01/25‬ه ـ املتضمــن أن الكيبــل مــدار الدعــوى يختــرق أرض‬\n‫املدعــي بعمــق ( ‪70‬ســم ) ومســافة ( ‪20‬م ) لــذا تقــدر األجــرة الشــهرية‬\n‫للجــزء املتعــدى عليــه مببلــغ وقــدره ألفــن وخمســمائة ريــال أمــا تقديــر‬\n‫األتعــاب يحتــاج إلــى معرفــة عــدد اجللســات التــي حضرهــا املدعــي أو‬\n‫وكيلــه حتــى انتهــت الدعــوى ليتــم التقديــر علــى ضــوء ذلــك حتري ـ ًا‬\n‫للدقــة وبــراءة لذمــة هــذا وبــاهلل التوفيــق وبعــرض ذلــك علــى الطرفــن‬\n‫قــال املدعــى عليــه ســأرجع ملوكلــي يف ذلــك وأجيبكــم يف اجللســة‬\n‫القادمــة وقــال املدعــي مــا ذكــره قســم اخلبــراء بنــاء علــى مــا جــاء يف‬\n‫خطــاب وزارة النقــل املشــار إليــه مــن أن مســافة الكيبــل عشــرين متــر ًا‬\n‫فقــط فهــذا غيــر صحيــح ألن أرضــي عبــارة عــن قطعتــن مجمــوع طولهــا‬\n‫أربعــن متــر ًا كمــا أنــه يدخــل يف أرضــي بعمــق ثالثــة أمتار تقريبـ ًا وليس‬\n‫كمــا ذكــر خطــاب وزارة النقــل الــذي اعتمــد عليــه قســم اخلبــراء لــذا‬\n‫أطلــب إعــادة النظــر يف ذلــك والتحقــق مــن ذلــك مــن قبــل قســم اخلبــراء‬\n‫ويف تقديــر األجــرة بنــاء علــى اختــاف املســاحة التــي اختزلهــا الكيبــل‬\n‫مــن أرضــي وللكتابــة لقســم اخلبــراء للتحقــق ممــا ذكــره املدعــي مــن‬\n‫طــول املســاحة التــي اختزلهــا الكيبــل مــن أرض املدعــي وإعــادة النظــر‬\n‫يف التقديــر بنــاء علــى ذلــك رفعــت اجللســة كذلــك كمــا طلبــت مــن‬\n‫املدعــى عليــه إحضــار مهنــدس مختــص لتحديــد مســار الكيبــل أثنــاء‬\n‫الوقــوف مــع قســم اخلبــراء فاســتعد بذلــك ثــم يف جلســة أخــرى حضــر‬\n‫الطرفــان وقــد جــرى االستفســار عــن ســريان مفعــول صــك املدعــي‬\n‫فوردنــا اجلــواب مــن كتابــة العــدل باملدينــة املنــورة برقــم ‪34485079‬‬\n\n\n                                                                                    ‫‪322‬‬\n\f      ‫وتاريــخ ‪1434/3/1‬ه ـ املتضمــن أن الصــك مطابــق لســجله وســاري‬\n      ‫املفعــول كمــا وردنــا خطــاب قســم اخلبــراء رقــم ‪ 34/31147‬وتاريــخ‬\n      ‫‪1434/5/27‬ه ـ املتضمــن أنــه مت الوقــوف مــرة أخــرى علــى املوقــع مــدار‬\n      ‫الدعــوى مــع املدعــي واملدعــى عليــه ميثلهــم مندوبهــم (‪)........‬حيــث أحضر‬\n      ‫جهــاز لتحديــد مســار الكيبــل وكذلــك قــام باحلفــر حتــى ظهــر الكيبل‬\n      ‫علــى الطبيعــة وتبــن لنــا أنــه ميــر داخــل احلــد اجلنوبــي وبطــول أربعــن متــر ًا‬\n      ‫علــى امتــداد احلــد إال أن التقديــر الــوارد يف القــرار الســابق املرفــق رقــم‬\n      ‫‪ 34/31147‬يف ‪1434/3/18‬ه ـ جــاء بعــد الوقــوف واملعاينــة مــع املدعــي‬\n      ‫ومنــدوب الشــركة وعمــل بذلــك محضــر معاينــة مرفــق موقــع مــن قبــل‬\n      ‫املشــاركني وكذلــك مت علــى أســاس مــا جــاء يف قرارنــا املرفــق املــؤرخ‬\n      ‫يف ‪1434/2/25‬ه ـ واعتــراف منــدوب شــركة (‪ )........‬وإشــارة احلســية‬\n      ‫التــي حــدد مبوجبهــا أن مســار الكيبــل يختــرق أرض املدعــي علــى طــول‬\n      ‫احلــد اجلنوبــي ولــم يتــم التقديــر علــى أن املســاحة عشــرون متــر ًا ‪ ،‬أمــا‬\n      ‫بالنســبة إلــى اإلشــارة إلــى خطــاب إدارة الطرق والنقــل رقم ‪ 672706‬يف‬\n      ‫‪1432/8/25‬ه ـ كمســتند أن الكيبــل ميــر بــأرض املدعــي ألن الكيبــل‬\n      ‫كان مدفون ـ ًا وال يوجــد آثــار للحفــر حــن الوقــوف لــذا نــرى أن مبلــغ‬\n      ‫ألفــن وخمســمائة ريــال أجــرة شــهرية لكامــل اجلــزء املتضــرر مــن أرض‬\n      ‫املدعــي مناســب وكايف واهلل املوفــق وبعــرض ذلــك علــى الطرفــن قــال‬\n      ‫املدعــي إننــي قانــع مبــا جــاء يف التقريــر وإن كنــت أراه أقــل مــن التقديــر‬\n      ‫املســتحق كمــا قــرر املدعــى عليه وكالــة أن موكلته ال اعتراض لديها‬\n      ‫علــى قيمــة التقديــر وموضــع الكيبــل وأنــه ميــر بــأرض املدعــي وأضــاف‬\n      ‫لكــن موكلتــي قامــت بتنفيــذ الكيبــل بنــاء علــى ترخيــص وزارة النقــل‬\n      ‫وتــرى أن دعــوى املدعــي تتوجــه علــى وزارة النقــل هكــذا أجــاب ثــم‬\n\n\n‫‪323‬‬\n\f‫قــال املدعــي إننــي أقصــر مطالبتــي يف الوقــت احلاضــر علــى طلــب رفــع‬\n‫الكيبــل عــن األرض ودفــع األجــرة للمــدة املاضيــة وأمــا املطالبــة بأجــرة‬\n‫أتعابــي يف مطالبتهــم فأرجئهــا حتــى انتهــاء القضيــة ألطالــب بهــا بدعــوى‬\n‫مســتقلة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة املدعــى‬\n‫عليــه علــى أن الكيبــل يعــود ملوكلتــه وأنــه مت وضعــه يف املــدة التــي‬\n‫ذكــر املدعــي بنــاء علــى ترخيــص وزارة النقــل وملــا جــاء يف قــرار قســم‬\n‫اخلبــراء مــن أن الكيبــل ميــر بــأرض املدعــي بالطول املذكــور يف التقرير‬\n‫وأن أجرتــه كمــا ذكــر بعاليــه وألن املباشــر لالعتــداء واملســتفيد منــه‬\n‫هــي املدعــى عليهــا والكيبــل يعــود لهــا والعبــرة مبــن باشــر االعتــداء‬\n‫وباحتســاب املــدة املاضيــة وجــدت اثنــن وخمســن شــهر ًا حتــى تاريــخ‬\n‫‪1434/06/15‬ه ـ وأجرتهــا مبلــغ مائــة وثالثــن ألــف ريــال لــذا فقــد‬\n‫أفهمــت املدعــى عليــه وكالــة أنــه يلــزم موكلتــه رفــع الكيبــل عــن‬\n‫أرض املدعــي موضــع الدعــوى يف موعــد أقصــاه ‪1434/6/15‬ه ـ ودفــع‬\n‫أجــرة املــدة املاضيــة وقدرهــا مائــة وثالثــون ألــف ريــال ويف حــال تأخرهــا‬\n‫عــن رفــع الكيبــل يف املوعــد احملــدد فيلزمهــا دفــع أجــرة شــهرية قدرهــا‬\n‫ألفــان وخمســمائة ريــال شــهري ًا ومبــا تقــدم حكمــت وبعــرض ذلــك علــى‬\n‫الطرفــن أبــدى املدعــي قناعتــه باحلكــم أمــا املدعــى عليــه فلــم يقنــع‬\n‫باحلكــم وطلــب االســتئناف وأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/06/07‬ه‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ )........‬القاضــي باحملكمــة العامــة باملدينــة املنــورة والقائــم بعمــل‬\n‫املكتــب القضائــي الثانــي ففــي يــوم اخلميــس املوافــق ‪1434/09/17‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار الصــادر مــن‬\n\n\n                                                                                      ‫‪324‬‬\n\f      ‫الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫رقــم ‪ 34297233‬وتاريــخ ‪1434/08/15‬ه ـ املتضمــن مــا نصــه احلمــد‬\n      ‫هلل والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n      ‫رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫(‪ )........‬مســاعد رئيــس احملكمــة العامــة باملدينــة املنــورة ‪ /‬املســاعد‬\n      ‫واملســجل بعــدد ‪ 34241641‬وتاريــخ ‪1434/06/14‬ه ـ املتضمــن دعــوى‬\n      ‫(‪ )........‬ضــد شــركة (‪ )........‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم وبــاهلل التوفيــق اه ـ قاضــي اســتئناف (‪ )........‬قاضــي اســتئناف‬\n      ‫(‪ )........‬رئيــس الدائــرة (‪ )........‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/9/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ .:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ )........(/‬رئيــس احملكمــة العامــة باملدينــة املنورة‪/‬املســاعد‬\n      ‫واملســجل بعــدد ‪ 34241641‬وتاريــخ ‪1434/6/14‬ه ـ املتضمــن دعــوى‬\n      ‫(‪ )........‬ضــد شــركة (‪ )........‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n           ‫احلكــم‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪325‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":317,"source_page_end":325,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"be7220535e72e98ce15b2ac8b083b53da30e575251dacb980473faf3b47bc532","normalized_text_hash":"612dd7958e0663d60d1691d75089bb745391e8d63149cb2cc6e06921f308133f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p317-34241641"},{"id":"fbaed9bc-b0ed-5bd3-a7f6-9b86ae9b5c4f","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -مضاربة -مساهمة عقارية -االختاف يف احتساب نسبة األرباح يف املساهمة -بطان شرط مبلغ معن مع نسبة الربح -تكرار التخلف عن احلضور يعد قرينة على أن املتخلف عادم ا للبينة -احلكم برأس املال مع االرباح -التهميش على صك احلكم بالتنفيذ وانتهاء القضية .","document_number":"3337775","case_number":"32360972","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/13","year":"1434","subject":"عقار -مضاربة -مساهمة عقارية -االختاف يف احتساب نسبة األرباح يف املساهمة -بطان شرط مبلغ معن مع نسبة الربح -تكرار التخلف عن احلضور يعد قرينة على أن املتخلف عادم ا للبينة -احلكم برأس املال مع االرباح -التهميش على صك احلكم بالتنفيذ وانتهاء القضية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3337775 :‬تاريخه ‪1433/8/13 :‬ه ـ‬\n              ‫\t\t‬   ‫رقم الدعوى ‪32360972 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34217910‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫عقــار ‪ -‬مضاربــة ‪ -‬مســاهمة عقاريــة ‪ -‬االختــاف يف احتســاب نســبة‬\n‫األربــاح يف املســاهمة ‪ -‬بطــان شــرط مبلــغ معــن مــع نســبة الربــح‬\n‫‪ -‬تكــرار التخلــف عــن احلضــور يعــد قرينــة علــى أن املتخلــف عادم ـ ًا‬\n‫للبينــة ‪ -‬احلكــم بــرأس املــال مــع االربــاح ‪ -‬التهميــش علــى صــك‬\n                                    ‫احلكــم بالتنفيــذ وانتهــاء القضيــة ‪.‬‬\n\n\n\n\n                               ‫‪ -1‬املادة (‪ )55‬من نظام املرافعات الشرعية ‪.‬‬\n‫‪ -2‬قــال بــن قدامــه رحمــه اهلل يف املغنــى ‪ ( :‬متــى جعــل نصيــب احــد‬\n‫الشــركاء دراهــم معلومــة أو جعــل مــع نصيبــة دراهــم مثــل ان يشــترط‬\n                           ‫لنفســه جــزء وعشــرة دراهــم بطلــت الشــركة ‪).‬‬\n‫‪ -3‬قــال ابــن املنــذر ‪ ( :‬أجمــع كل مــن نحفــظ عنــه مــن اهــل العلــم علــى‬\n‫ابطــال القــراض يف املضاربــة اذا شــرط احدهمــا او كالهمــا لنفســه‬\n                                                              ‫دراهــم معلومــة )‪.‬‬\n‫‪ -4‬قــال شــيخ االســام ابــن تيميــة رحمــه اهلل ‪( :‬لــو شــرط يف املضاربــة‬\n‫لــرب املــال دراهــم معينــة فــإن هــذا االتفــاق ال يجــوز ألن املعاملــة مبناهــا‬\n‫علــى العــدل وهــذه املعامــات مــن جنــس املشــاركات واملشــاركة امنــا‬\n‫تكــون لــكل مــن الشــريكني جــزء شــائع يف الثلــث والنصــف فــإذا جعــل‬\n‫ألحدهمــا شــيء مقــدر لــم يكــن ذلــك عــد ًال بــل كان ظلمـ ًا ) ‪ .‬الفتاوى‬\n                                                                        ‫(‪.)83/28‬‬\n                                                                                        ‫‪326‬‬\n\f      ‫ادعــى املدعــى وكالــة علــى املدعــى عليــه وكالــة بــأن موكلــه ســاهم‬\n      ‫مــع املدعــى عليــه اصالــة مببلــغ أربعــة ماليــن ريــال يف مخطــط ‪.....‬‬\n      ‫مبكــة املكرمــة وبتاريــخ ‪1427/1/26‬ه ـ مت االتفــاق بــن الطرفــن‬\n      ‫علــى ان يبيــع املدعــى عليــه للمدعــى البلــك رقــم (‪ )50‬مببلــغ ثمانيــة‬\n      ‫ماليــن ومائتــي الــف وثمامنائــة وواحــد وخمســن ريــا ًال مــن مســاهمة‬\n      ‫املدعــى علــى أن يتــم االفــراغ لــه بعــد تصفيــة املســاهمة ‪ - .‬صفــى‬\n      ‫املدعــى عليــه املســاهمة مبوجــب االعــان علــى موقــع املكتــب وبلغــت‬\n      ‫نســبة األربــاح للعمــاء املســاهمني (‪ - )%167‬ذكــر املدعــى وكالــة ان‬\n      ‫ملوكلــه رأس املــال الــذي دفعــه اربعــة ماليــن ريــال مضافـ ًا إليهــا األربــاح‬\n      ‫ثمانيــة ماليــن وســتمائة واربعــة وثمانــن الــف ريــال يحســم منهــا قيمــة‬\n      ‫البلــك رقــم (‪ )50‬املذكــور وعليــه فــإن املتبقــي ملوكلــي يف ذمــة املدعــى‬\n      ‫عليــه اربعــة ماليــن واربعمائــة وثالثــة وثمانــون الفـ ًا ومائــة وأربعــون ريــاال‬\n      ‫طلــب الــزام املدعــى عليــه بســدادها ‪ - .‬اقــر املدعــى عليــه وكالــة بصحــة‬\n      ‫املســاهمة واملبلــغ املدفــوع مــن قبــل املدعــى البالــغ اربعــة ماليــن ريــال‬\n      ‫وعلــى شــراء املدعــى للبــك رقــم (‪ )50‬وعلــى نســبة األربــاح للمدعــى ‪%65‬‬\n      ‫‪ - .‬صــادق املدعــى عليــه وكالــة علــى أن نســبة األربــاح للمســاهمني‬\n      ‫بلغــت ‪ %167‬لكــن هــذه النســبة تســتحق للمســاهم الــذي ســاهم وحصــل‬\n                                     ‫علــى حصتــه نقــدا ولــم يحصــل علــى أرض ‪.‬‬\n      ‫أمــا املدعــى فقــد حصــل علــى جــزء مــن العقــار موضــع املســاهمة فهــو‬\n      ‫ال يســتحق ســوى حصتــه مــن األربــاح املتفــق عليهــا ‪ %65‬هــذا هــو‬\n      ‫املتبــع يف تصفيــة املســاهمة فــكل مــن ســاهم وحصــل علــى جــزء مــن‬\n\n‫‪327‬‬\n\f‫مســاهمته عقــار ًا مت احتســاب ارباحــه ‪ %50‬أمــا مــن حصــل علــى األربــاح‬\n‫نقــدا فنســبته ‪ - %167‬قــرر املدعــى عليــه وكالــة ان للمدعــى اصالــة‬\n‫رأس املــال الــذى دفعــه (‪ + )4.000.000‬األربــاح ‪)2.600.000(%65‬‬\n‫= (‪ )6.600.000‬يخصــم منهــا قيمــة البــك رقــم (‪ )50‬مبلغــا وقــدره‬\n‫(‪ )8.200.851‬وبالتالــي فاملســتحق للمدعــى عليــه يف ذمــة املدعــى‬\n‫(‪ - )1.600.851‬جــري ســؤال املدعــى عليــه وكالــة عــن ايضــاح ان‬\n‫نســبة االربــاح املذكــورة ‪ %167‬ال تشــمل املدعــى ‪ -‬فقــرر املدعــى عليــه‬\n‫وكالــة بقولــه ألن املدعــى أخــذ نصيبــه عقــارا ‪ -‬أنكــر املدعــى وكالــة‬\n‫ذلــك وقــرر بقولــه ان موكلــي يســتحق نســبة الربــح ‪ %167‬أســوه بقيــة‬\n‫املســاهمني ‪ -‬يف جلســة أخــري قــرر املدعــى وكالــة بــأن إجمالــي اربــاح‬\n‫املســاهمة بلغــت ‪ %334‬يســتحق املســاهمون منهــا ‪ %167‬علــى حســاب‬\n‫ان نصيبهــم هــو ‪ %50‬مــن االربــاح وموكلــي يســتحق مــن االربــاح ‪%217‬‬\n‫علــى حســاب ان نصيبــه هــو ‪ %65‬مــن األربــاح حســب االتفــاق بينــه وبــن‬\n‫املدعــى عليــه أصالــة ‪ -‬فموكلــي يســتحق نســبة الربــح مــن اجمــال‬\n‫االربــاح التــي حصلــت يف املســاهمة بخــاف مــا ذكــره املدعــى وكالــة‬\n‫أن نصيــب موكلــي ‪ %65‬مــن راس املــال ‪ -‬بعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة طلــب مهلــة للرجــوع ملوكلــه ‪ - .‬تكــرر تخلــف املدعــى‬\n‫عليــه ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه اصالــة بــان يدفــع للمدعــى‬\n‫أصالــة أربعــة ماليــن وأربعمائــة وتســعة وســبعني ألف ـ ًا ومائــة وتســعة‬\n‫وأربعــن ريــا ًال متثــل املبلــغ الباقــي بذمــة املدعــى عليــه للمدعــى مــن رأس‬\n‫املــال واألربــاح بعــد حســم قيمــة البلــك رقــم (‪ )50‬وصــرف النظــر عمــا‬\n‫زاد عــن ذلــك ممــا جــاء يف دعــوى املدعــى وكالــة ‪ -‬قــرر املدعــى وكالــة‬\n‫قناعتــه باحلكــم ‪ -‬قــدم املدعــى عليــه وكالــة الئحتــه االعتراضيــة ‪-‬‬\n\n\n                                                                                       ‫‪328‬‬\n\f      ‫صــدق احلكــم مــن محكمــة اإلســتئناف ‪ -‬ســدد املدعــى عليــه للمدعــى‬\n                ‫املبلــغ احملكــوم بــه مبوجــب شــيك وبذلــك انتهــت القضيــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده ‪ ،‬وبعــد ‪ ،‬فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32360972‬وتاريخ‪1432/08/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 321075501‬وتاريــخ ‪1432/08/19‬ه ـ حضــر‬\n      ‫‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬بالوكالــة عــن ‪...‬ســعودي بالســجل‬\n      ‫املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫ببريــدة برقــم ‪ 41261‬وتاريــخ ‪1432/08/08‬ه ـ واملخــول لــه فيهــا حــق‬\n      ‫املطالبــة واملخاصمــة واملدافعــة واملرافعــة وإقامــة الدعــاوى وحتريرهــا‬\n      ‫وقبــول احلكــم واالعتــراض عليــه وطلــب االســتئناف والصلــح كمــا‬\n      ‫حضــر حلضــوره ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬بالوكالــة عــن‬\n      ‫‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل الدرعيــة برقــم ‪ 3349075‬وتاريــخ ‪1433/01/26‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املدافعــة واملرافعــة واملخاصمــة وحضــور اجللســات‬\n      ‫وســماع الدعــاوى واإلقــرار واإلنــكار وتقــدمي البينــات وطلــب اليمــن‬\n      ‫ا (دفــع موكلــي‬   ‫واالســتئناف والقناعــة باألحــكام وادعــى األول قائ ـ ً‬\n      ‫للمدعــى عليــه مبلغ ـ ًا وقــدره أربعــة ماليــن ريــال مســاهمة يف مخطــط‬\n      ‫‪ .....‬الواقــع مبكــة املكرمــة ويف تاريــخ ‪1427/1/26‬ه ـ مت االتفــاق‬\n      ‫بــن موكلــي واملدعــى عليــه علــى أن يبيــع املدعــى عليــه ملوكلــي البلــك‬\n      ‫رقــم ‪ 50‬املســجل باســم املدعــى عليــه بالصــك رقــم ‪ 4/390/47‬مببلــغ‬\n\n‫‪329‬‬\n\f‫ثمانيــة ماليــن ومائتــي ألــف وثمامنائــة وواحــد وخمســن ريــاال حتســب‬\n‫مــن مســاهمته علــى أن يتــم اإلفــراغ لــه بعــد التصفيــة ومعرفــة مــا لــه ومــا‬\n‫عليــه حســب مــا نصــت عليــه الوثيقــة املشــار إليهــا وقــد صفــى املدعــى‬\n‫عليــه املســاهمة تصفيــة نهائيــة مبوجــب اإلعــان علــى موقــع مكتــب‬\n‫‪ ....‬بنســبة أربــاح بلغــت ‪ %167‬هــذه النســبة متثــل نصــف أربــاح مســاهمة‬\n‫العميــل واالتفــاق بــن املدعــى عليــه والعمــاء انــه يســتحق ‪ %50‬مــن‬\n‫األربــاح باســتثناء موكلــي فــإن االتفــاق بينــه وبــن املدعــى عليــه انــه‬\n‫يســتحق مــن األربــاح ‪ %65‬وبنــاء عليــه فــان أربــاح موكلــي بلغــت ثمانيــة‬\n‫ماليــن وســتمائة وأربــع وثمانــن ألف ـ ًا وبنــاء علــى االتفــاق املشــار إليــه‬\n‫فــان املتبقــي ملوكلــي مبلــغ أربعــة ماليــن وأربعمائــة وثــاث وثمانــن ألف ًا‬\n‫ومائــة وأربعــن ريــاال اطلــب إلــزام املدعى عليه بدفع هــذا املبلغ ملوكلي)‬\n‫هكــذا ادعــى وبعرضهــا علــى املدعــى عليــه وكالــة طلــب مهلــة لإلجابــة‬\n‫‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة وحضــر حلضــوره ‪ ...‬ســعودي‬\n‫ا عــن ‪...‬ســعودي بالســجل املدنــي‬    ‫بالســجل املدنــي رقــم ‪...‬بصفتــه وكيـ ً‬\n‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العدل مبحافظــة الدرعية‬\n‫برقــم ‪ 3349075‬وتاريــخ ‪1433/01/26‬ه ـ واملخــول لــه فيها حق املطالبة‬\n‫واملرافعــة واملخاصمــة واإلقــرار واإلنــكار وقبــول احلكــم واالعتــراض‬\n‫عليــه واالســتالم ثــم ســألت املدعــي وكالــة عــن تفصيــل املبلــغ املطالــب‬\n‫بــه فقــال إنــه ميثــل رأس املــال مــع الباقــي مــن األربــاح هكذا قــال وبعرض‬\n‫الدعــوى علــى املدعــى عليــه وكالــة قــال ســوف أجيب يف اجللســة القادمة‬\n‫وقــال أطلــب مــن املدعــي وكالــة تســليمي صــورة مــن ســند املســاهمة ‪،‬‬\n‫ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه وكالــة الثانــي‬\n‫وبســؤال املدعــى عليــه وكالــة عــن جوابــه علــى الدعــوى قــال ‪ :‬إن جوابي‬\n\n\n                                                                                        ‫‪330‬‬\n\f      ‫يتلخــص يف هــذه املذكــرة ثــم أبــرز ورقتــن جــاء فيهــا (نــرد علــى مــا جــاء‬\n      ‫بدعــوى املدعــي أنــه صحيــح مســاهم مــع موكلــي باملبلــغ الــذي ذكــره‬\n      ‫يف دعــواه وهــو (‪ )4,000,000‬أربعــة ماليــن ريــال وصحيــح أنــه اشــترى‬\n      ‫البلــك رقــم ‪ 50‬وأنــه اتفــق علــى اســتحقاقه ‪ %65‬أرباحـ ًا ممــا يتحقــق مــن‬\n      ‫الربــح علــى رأس مالــه بــد ًال مــن ‪ %50‬وموكلــي ال ميانــع لــه يف ذلــك ونــود‬\n      ‫أن نوضــح لفضيلتكــم أن مــا ذكــره مــن أن األربــاح بلغــت ‪ %167‬فهــذا‬\n      ‫صحيــح ولكــن هــذه النســبة تســتحق للمســاهم الــذي ســاهم وحصــل‬\n      ‫علــى حصتــه نقــد ًا ولــم يحصــل علــى أراضــي مــن املســاهمة وحصــل‬\n      ‫علــى حصــة مــن األربــاح نقــد ًا أمــا حــال املدعــي يختلــف حيــث حصــل‬\n      ‫علــى جــزء مــن العقــار موضــوع املســاهمة فاألمــر هنــا يختلــف حيــث ال‬\n      ‫يســتحق ســوى حصتــه مــن األربــاح املتفــق عليــه وهــي ‪ %65‬وهــذا هــو‬\n      ‫املتبــع يف تصفيــة املســاهمة فــكل مــن ســاهم وحصــل علــى جــزء مــن‬\n      ‫مســاهمته عقــار مت احتســاب أرباحــه‪ %50‬ونرفــق لفضيلتكــم مجموعــة‬\n      ‫مــن املســاهمني وتصفيــة مســاهماته التــي تؤكــد حصولهــم علــي نســبة‬\n      ‫‪ %50‬فقــط مــن األربــاح أمــا مــن حصــل علــى أربــاح نقــد ًا فقــد حصــل‬\n      ‫عليهــا بنســبة أربــاح ‪ %167‬وهــذا أمــر طبيعــي فهــب أن كل املســاهمني‬\n      ‫حصلــوا علــى مقابــل مســاهمتهم أســهم مــن العقــار فمــن أيــن تأتــي‬\n      ‫األربــاح فاألربــاح تأتــي مــن بيــع العقــار أو جــزء منــه أو تصفيتــه فاملدعــي‬\n      ‫يســتحق أرباحـ ًا مقدارهــا (‪ )2,600,000‬التــي متثــل (‪ )%65‬من مســاهمته‬\n      ‫ومقدارهــا (‪ )4,000,000‬وبالتالــي يكــون للمدعــي قيمــة مســاهمته‬\n      ‫مــع أرباحهــا مبلغـ ًا مقــداره (‪)6,600,000 = 2,600,000 + 4,000,000‬‬\n      ‫يخصــم منــه قيمــة البلــك رقــم (‪ )50‬مبلــغ وقــدره (‪ )8.200.851‬ثمانيــة‬\n      ‫ماليــن ومائتــي ألــف وثمامنائــة وواحــد وخمســن ريــا ًال ‪ ،‬وبالتالــي يصبــح‬\n\n\n‫‪331‬‬\n\f‫مســتحق ًا للمدعــى عليــه مبلغ ـ ًا مقــداره (‪ )1.600.851‬مليون ـ ًا وســتمائة‬\n‫ألــف وثمامنائــة وواحــد وخمســن ريــا ًال ‪ .‬وال مانــع لــدى موكلنــا يف‬\n‫حــال ســدادها أن يفــرغ لــه األرض موضــوع املســاهمة) فســألت املدعــى‬\n‫عليــه وكالــة هــل اشــترى مــوكل املدعــي األرض بالقيمــة التــي ذكــر‬\n‫فقــال ‪ :‬نعــم ثــم طلــب منــه إيضــاح مــا ذكــره يف جوابــه مــن أن نســبة‬\n‫الربــح املذكــورة يف الدعــوى ال تشــمل املدعــي فقــال ‪ :‬إن نســبة الربــح‬\n‫املذكــورة ال تشــمل املدعــي لكونــه أخــذ نصيبــه عقــار ًا وبالتالــي فــإن‬\n‫نظــام تلــك املســاهمة ينبنــي علــى أن مــن أخــذ جــزء ًا مــن نصيبــه عقــار ًا‬\n‫فإنــه ال يحســب عليــه بنفــس نســبة الربــح هكــذا قــال فســألته عــن نســبة‬\n‫الربــح التــي يســتحقها مــوكل املدعــي فقــال ‪ :‬إن نســبة الربــح ‪%65‬‬\n‫هكــذا قــال وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬إن مــا ذكــره‬\n‫غيــر صحيــح ومــا ذكــره مــن أن ذلــك هــو نظــام املســاهمة فهــذا غيــر‬\n‫صحيــح أيض ـ ًا وموكلــي يســتحق نســبة الربــح أســوة ببقيــة الشــركاء‬\n‫وأما النســبة التي ذكر فهي نســبة تقســيم الربح بني املســاهم وصاحب‬\n‫املســاهمة هكــذا قــال فســألت املدعــى عليــه وكالــة عمــا ذكــره مــن‬\n‫أن ذلــك هــو نظــام املســاهمة هــل كان ذلــك بعلــم مــوكل املدعــي فقــال‬\n‫‪ :‬ســوف أراجــع موكلــي وأجيــب يف اجللســة القادمــة ‪ ،‬ويف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وبســؤال املدعــى عليــه‬\n‫وكالــة عــن جوابــه علــى مــا طلــب منــه يف اجللســة املاضيــة مــن أن االتفــاق‬\n‫الــذي ذكــره بخصــوص تقديــر نســبة الربــح كان بعلــم املدعــي فقــال ‪:‬‬\n‫إننــي لــم أمتكــن مــن إحضــار اإلجابــة وســوف أجيــب يف اجللســة القادمــة‬\n‫هكــذا قــال ثــم ســألت املدعــي وكالــة عــن قصــده بقولــه يف اجللســة‬\n‫املاضيــة إن موكلــه يســتحق نســبة أســوة ببقيــة الشــركاء فقــال ‪ :‬إن‬\n\n\n                                                                                      ‫‪332‬‬\n\f      ‫األمــر يحتــاج إلــى إيضــاح وهــو أن نســبة أربــاح األرض كاملــة بلغــت ‪334‬‬\n      ‫‪ %‬يســتحق املســاهمون منهــا ‪ %167‬علــى حســاب أن نصيبهــم هــو ‪%50‬‬\n      ‫مــن الربــح بينمــا موكلــي يســتحق منهــا ‪ %217‬علــى حســاب أن نصيبــه‬\n      ‫هــو ‪ %65‬مــن الربــح حســب االتفــاق الــذي مت بينــه وبــن مــوكل املدعــى‬\n      ‫عليــه وأنــا أقصــد أن موكلــي يســتحق نســبة الربــح مــن إجمالــي األربــاح‬\n      ‫التــي حصلــت يف تلــك املســاهمة ومــا ذكــره املدعــى عليــه وكالــة مــن‬\n      ‫أن نصيــب موكلــي هــو ‪ %65‬مــن رأس املــال فهــذا غيــر صحيــح إذ أن‬\n      ‫تلــك النســبة هــي نســبة تقاســم األربــاح وليســت نســبة الربــح واملســاهمة‬\n      ‫كمــا ذكــرت قــد ربحــت ‪ %334‬فكيــف يتــم حســاب نســبة موكلــي‬\n      ‫علــى هــذا النحــو ‪ ،‬هــذا مــا أردت إيضاحــه هكــذا قــال ‪ ،‬وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬ســوف أرجــع ملوكلــي وأجيــب يف‬\n      ‫اجللســة القادمــة ‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــة ولــم يحضــر‬\n      ‫املدعــى عليــه وال وكيلــه رغــم تبلــغ الوكيــل باملوعــد يف اجللســة املاضيــة‬\n      ‫وقــد وردنــا خطــاب بشــرح فضيلــة الرئيــس رقــم ‪ 33/1523906‬مــدون‬\n      ‫مــن قبــل املدعــى عليــه وكالــة وقــد تضمــن رغبتــه يف تأجيــل املوعــد‬\n      ‫إلــى شــهر رمضــان حملاولــة الصلــح بــن الطرفــن هــذا وبعــرض ذلــك‬\n      ‫علــى املدعــي وكالــة قــال ‪ :‬أنــا ال أوافــق علــى تأجيــل اجللســة وأطلــب‬\n      ‫االســتمرار يف نظرهــا لــذا قــررت إكمــال نظــر الدعــوى غيابيـ ًا اســتناد ًا‬\n      ‫للمــادة (‪ )55‬مــن نظــام املرافعــات وبعــد التأمــل فيمــا ســبق مــن الدعــوى‬\n      ‫واإلجابــة وحيــث أقــر املدعــى عليــه وكالــة بصحــة مســاهمة مــوكل‬\n      ‫املدعــي مــع موكلــه باملبلــغ املذكــور وأنــه اشــترى األرض املذكــورة‬\n      ‫بالقيمــة املذكــورة وأقــر بصحــة نســبة الربــح التــي يســتحقها العميــل‬\n      ‫يف املســاهمة ودفــع بــأن مــوكل املدعــي ال يســتحق هــذه النســبة نظــر ًا‬\n\n\n‫‪333‬‬\n\f‫الحتســاب تلــك األرض مــن ضمــن أرباحــه وأن االتفــاق جــرى علــى ذلــك‬\n‫ولكــون ذلــك خــاف األصــل ومبــا أن املدعــى عليــه قــد تخلــف عــن‬\n‫احلضــور يف هــذه اجللســة وهــو بهــذا يعــد عادمـ ًا للبينــة علــى ذلــك الدفــع‬\n‫‪ -1‬لــذا فقــد ثبــت لــدي مــا يلــي ‪ :‬أن بذمــة مــوكل املدعــى عليــه ملــوكل‬\n‫املدعــي مبلــغ أربعــة ماليــن وأربعمائــة وتســعة وســبعني ألف ـ ًا ومائــة‬\n‫وتســعة وأربعــن ريــا ًال متثــل املبلــغ الباقــي بذمــة مــوكل املدعــى عليــه مــن‬\n‫رأس املــال واألربــاح بعــد حســم قيمــة األرض‪ -2 .‬رددت دعــوى املدعــي‬\n‫فيمــا زاد علــى ذلــك وحكمــت بذلــك وهــذا احلكــم يعــد حضوريـ ًا بحــق‬\n‫املدعــى عليــه وبعــرض ذلــك علــى املدعــي وكالــة قــرر القناعــة وســوف‬\n‫يتــم تبليــغ املدعــى عليــه باحلكــم بواســطة احملضريــن ‪ ،‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1433/08/13‬ه ـ‬\n‫(قــال ابــن قدامــة رحمــه اهلل يف املغنــي ( متــى جعــل نصيــب أحــد‬\n‫الشــركاء دراهــم معلومــة أو جعــل مــع نصيبــه دراهــم مثــل أن يشــترط‬\n‫لنفســه جــزء وعشــرة دراهــم بطلــت الشــركة قــال ابــن املنــذر أجمع كل‬\n‫مــن نحفــظ عنــه مــن أهــل العلــم علــى إبطــال القــراض يعنــي املضاربــة إذا‬\n                    ‫شــرط أحدهمــا أو كالهمــا لنفســه دراهــم معلومــة )‬\n‫قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل ( لــو شــرط يف املضاربــة لــرب‬\n‫املال دراهم معينة فإن هذا االتفاق ال يجوز باالتفاق ألن املعاملة مبناها‬\n‫علــى العــدل وهــذه املعامــات مــن جنــس املشــاركات واملشــاركة إمنــا‬\n‫تكــون لــكل مــن الشــريكني جــزء شــائع يف الثلــث والنصــف فــإذا‬\n‫جعــل ألحدهمــا شــيء مقــدر لــم يكــن ذلــك عــد ًال بــل كان ظلمـ ًا ) ا‪.‬ه ـ‬\n‫‪ 83/28‬وحيــث إن رأس املــال قــدره أربعــة ماليــن ريــال وربــح مــوكل‬\n\n\n                                                                                         ‫‪334‬‬\n\f      ‫املدعــي هــو ‪ %217‬وهــو مــا ميثــل ‪ %65‬مــن إجمالــي الربــح البالــغ ‪%334‬‬\n      ‫ليكــون إجمالــي الربــح ثمانيــة ماليــن وســتمائة وثمانــن ألــف ريــال‬\n      ‫(‪ )8680000‬ريــال وبإضافــة رأس املــال يكــون إجمالــي املبلــغ اثنــي‬\n      ‫عشــر مليون ـ ًا وســتمائة وثمانــن ألــف ريــال (‪)12680000‬ريــال يحســم‬\n      ‫منهــا قيمــة األرض ليكــون الباقــي أربعــة ماليــن وأربعمائــة وتســعة‬\n                                     ‫وســبعني ألف ـ ًا ومائــة وتســعة وأربعــن ريــاالً‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االحــد حضــر املدعــي اصالــة ‪... ...‬كما‬\n      ‫حضــر املدعــى عليــه وكالــة ‪...‬وســلم املدعــى عليــه للمدعــي أصالــة يف‬\n      ‫مجلــس احلكــم الشــيك املســحوب علــى البنــك ‪...‬برقــم ‪ 2572‬و تاريــخ‬\n      ‫‪ 2013/5/25‬م بكامــل املبلــغ احملكــوم بــه وقــدره أربعــة ماليــن‬\n      ‫وأربعمائــة وتســعة وســبعون ألفــا ومائــة وتســعة وأربعــون ريــاال وقــرر‬\n      ‫املدعــي أصالــة باســتالمه وحتــى ال يخفــى جــرى احلاقــه و بهــذا تعتبــر‬\n      ‫القضيــة منتهيــة و بــاهلل التوفيــق و صلــى اهلل و ســلم علــى نبينــا محمــد‬\n                                                         ‫حــرر يف ‪1434/7/16‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 332053967‬وتاريــخ ‪1434/2/18‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪... /‬املســجل برقــم ‪33377750‬‬\n      ‫وتاريــخ ‪1433/8/13‬ه ـ اخلــاص بدعــوى‪... /‬وكيــا عــن ‪ ...‬ضــد‪...... /‬‬\n      ‫وكيــا عــن ‪...‬يف مبلــغ مالــي قيمــة مســاهمة علــى النحــو املوضــح يف‬\n      ‫الصــك املتضمــن أنــه ثبــت لــدى فضيلتــه مــا يلــي‪ -1 :‬أن بذمــة مــوكل‬\n      ‫املدعــى عليــه ملــوكل املدعــي مبلــغ أربعــة ماليــن وأربعمائــة وتســعة‬\n\n\n‫‪335‬‬\n\f‫وســبعني ألف ـ ًا ومائــة وتســعة وأربعــن ريــا ًال متثــل املبلــغ الباقــي بذمــة‬\n‫املدعــى عليــه مــن رأس املــال واألربــاح بعــد حســم قيمــة األرض‪ -2 .‬رد‬\n‫دعــوى املدعــي فيمــا زاد علــى ذلــك وحكــم بذلــك وهــذا احلكــم يعــد‬\n‫حضوري ـ ًا بحــق املدعــى عليــه‪ ،‬وحيــث ســبقت دراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا‬\n‫أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا املشــار إليــه‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اجلــواب األخيــر ‪.‬واهلل املوف ــق وصلــى‬\n                                ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":326,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7903d1b315346e2f68b7dd8f12cd34152ffffa24a3ca8713eea392df99c4aba","normalized_text_hash":"eb1a030cc48bc7410cf31e8c5bb2bf3e0e3438d834818310e43eb99fae076aee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p326-3337775"},{"id":"7db503ed-5ba0-5b31-b311-d03ebc2f73ef","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء أرض بالتقسيط -رهن الصك حلن استالم كامل املبلغ -بيع العقار ورهنه للبائع -طلب تسليم املبيع -الشرط املنايف ملقصود العقد -شهادة الشهود وحلف اليمن -احلكم على املدعى عليه بتسليم األرض وعلى املدعى رد الثمن احلال -تنفيذ احلكم .","document_number":"3424705","case_number":"3372501","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/27","year":"1434","subject":"عقار -شراء أرض بالتقسيط -رهن الصك حلن استالم كامل املبلغ -بيع العقار ورهنه للبائع -طلب تسليم املبيع -الشرط املنايف ملقصود العقد -شهادة الشهود وحلف اليمن -احلكم على املدعى عليه بتسليم األرض وعلى املدعى رد الثمن احلال -تنفيذ احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3424705 :‬تاريخه ‪1434/1/27 :‬هـ‬\n                        ‫رقم الدعوى ‪3372501 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34301076‬تاريخه‪1434/08/21 :‬هـ‬\n\n\n      ‫عقــار‪ -‬شــراء أرض بالتقســيط ‪ -‬رهــن الصــك حلــن اســتالم كامــل‬\n      ‫املبلــغ‪ -‬بيــع العقــار ورهنــه للبائــع‪ -‬طلــب تســليم املبيــع‪ -‬الشــرط املنــايف‬\n      ‫ملقصــود العقــد‪ -‬شــهادة الشــهود وحلــف اليمــن‪ -‬احلكــم علــى املدعــى‬\n      ‫عليــه بتســليم األرض وعلــى املدعــى رد الثمــن احلــال‪ -‬تنفيــذ احلكــم ‪.‬‬\n\n\n\n\n                        ‫قولة صلى اهلل عليه وسلم ( املسلمون على شروطهم )‬\n\n\n\n\n      ‫ادعــى املدعــى بأنــه اشــتري مــن املدعــى عليــه قطعــة أرض ( ذكــر‬\n      ‫وصفهــا ) باألقســاط تدفــع عــن طريــق شــيكات للمدعــى عليــه علــى‬\n      ‫أن ال يصــرف املدعــى عليــه الشــيك إال يف تاريــخ القســط وعلــى أن يقــوم‬\n      ‫املدعــى بتســديد رســوم البلديــة وعلــى أن يبقــي الصــك مرهون ـ ًا لــدى‬\n      ‫املدعــى عليــه فــا يفــرغ إال حــن اســتالم كامــل املبلــغ وعلــى أن يســتلم‬\n      ‫املشــترى ( املدعــى ) املبيــع األرض املذكــورة مــن ســاعة التعاقــد‪ -‬لــم‬\n      ‫يســلم املدعــى عليــه األرض للمدعــى‪ -‬طلــب املدعــى إلــزام املدعــى عليــه‬\n      ‫بتســليم األرض موضــع الدعــوى‪ -‬أقــر املدعــى عليــه بالدعــوى وذكــر‬\n      ‫بــأن ســبب عــدم تســليمه لــأرض هــو أنــه اشــترط أن تكــون الشــيكات‬\n      ‫مصدقــه وأن تكــون باســم املؤسســة اخلاصــة باملدعــى‪ -‬أنكــر املدعــى‬\n\n‫‪337‬‬\n\f‫هــذا الشــرط‪ -‬احضــر املدعــى عليــه ثالثــة شــهود وشــهادتهم غيــر‬\n‫موصلــة‪ -‬أحضــر املدعــى ثالثــة شــهود وشــهادتهم موصلــه وجــرى‬\n‫تعديلهــم‪ -‬أبــرز املدعــى عقــد البيــع ورصــد مضمونــة وليــس فيــه‬\n‫اشــتراط تصديــق الشــيكات‪ -‬أقــر املدعــى عليــه بصحــة عقــد البيــع‬\n‫املذكــور‪ -‬طلــب املدعــى عليــه ميــن املدعــى علــى نفــي اشــتراط تصديــق‬\n‫الشــيكات‪ -‬حلــف املدعــى اليمــن‪ -‬حيــث إن اشــتراط تصديــق‬\n‫الشــيكات ينــايف املقصــود مــن تقســيط املبلــغ وألن املســلمون علــى‬\n‫شــروطهم صــدر احلكــم بإلــزام املدعــى عليــه بتســليم األرض موضــع‬\n‫الدعــوى للمدعــي وإلــزام املدعــى بــأن يســلم للمدعــى عليــه األقســاط‬\n‫احلالــة وافهــام املدعــى بــأن لــه مطالبــة املدعــى عليــه بأجــره املثــل مــن‬\n‫تاريــخ العقــد إلــى حــن اســتالم األرض‪ -‬اعتــرض املدعــى عليــه علــى‬\n‫احلكــم‪ -‬لوحــظ علــى احلكــم مبالحظــات أهمهــا أن اإلفهــام املذكــور‬\n‫ال محــل‪ -‬رجــع القاضــي عــن اإلفهــام املذكــور‪ -‬صــدق احلكــم مــن‬\n‫محكمــة االســتئناف‪ -‬جــرى تنفيــذ احلكــم ورصــد ذلــك يف ضبــط‬\n                                                                        ‫القضيــة‬\n\n\n\n‫احلمد اهلل وحده والصالة والسالم على من ال نبي بعده أما بعد لدي أنا‬\n‫‪...‬القاضــي املنتــدب باحملكمــة العامــة بالطائــف بنــاء علــى قــرار معالــي‬\n‫رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 33/9116‬يف ‪1433/4/21‬ه ـ‬\n‫وبنــاء علــى خطــاب فضيلــة رئيــس احملكمــة العامــة بالطائــف رقــم‬\n‫‪ 33786591‬يف ‪1433/4/26‬ه ـ املتضمــن تكليفــي بالعمــل يف املكتــب‬\n‫القضائــي الرابــع يف احملكمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n\n                                                                                      ‫‪338‬‬\n\f      ‫فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ‬\n      ‫‪ 1433/01/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33189562‬وتاريــخ‬\n      ‫‪ 1433/01/29‬ه ـ ويف يــوم اإلثنــن املوافــق‪ 1433/07/07‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 08 : 30‬وفيها حضر املدعي أصالة ‪...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪...‬و والوكيــل الشــرعي ‪...‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫عــدل الثانيــة بالطائــف برقــم ‪ 4854‬بتاريــخ ‪1433/01/23‬ه ـ واملخولــة‬\n      ‫لــه حــق املرافعــة واملدافعــة واالقــرار واالنــكار وطلــب االميــان وردهــا‬\n      ‫وطلــب البينــة وتقدميهــا و اجلــرح والتعديــل وطلــب االســتئناف وتقــدمي‬\n      ‫اللوائــح االعتراضيــة وحضــر حلضــوره املدعــى عليــه أصالــة ‪ ...‬ســعودي‬\n      ‫ا لقــد اشــتريت‬  ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ادعــى األول قائـ ً‬\n      ‫مــن هــذا احلاضــر يف املجلــس الشــرعي األرض الواقعــة يف حــي جبــرة‬\n      ‫مبدينــة الطائــف واحملــدودة كالتالــي شــما ًال ‪...‬بطــول مائــة وخمســة‬\n      ‫أمتــار وثمانيــة مــن العشــرة وجنوب ـ ًا شــارع بعــرض عشــرين متــر ًا بطــول‬\n      ‫مائــة وخمســة أمتــار وســتة مــن العشــرة مــن املتــر وشــرق ًا بعــرض واحــد‬\n      ‫وعشــرين متــر ًا بطــول أربعــة وســتني متــر ًا وأربعــة مــن العشــر مــن املتــر‬\n      ‫وغرب ـ ًا شــارع بعــرض عشــرة أمتــار بطــول خمســة وســتني متــرا ًواثنــن‬\n      ‫مــن العشــرة مــن املتــر ومســاحتها اإلجماليــة ســتة آالف وثمامنائــة متــرا‬\n      ‫مربع ـ ًا ًوعشــرة مــن الســنتمتر املربــع مببلــغ وقــدره مليــون وثالثمائــة‬\n      ‫وخمســون ألــف ريــال تدفــع مقســطة علــى النحــو التالــي دفعــة أولــى‬\n      ‫مائتــن وخمســن ألــف ريــال عبــارة عــن ســيارة مــن نــوع جيــب تايوتــا‬\n      ‫صنــع عــام ‪2009‬م احتســبت قيمتــه مائــة وخمســة وأربعــن ألــف ريــال‬\n      ‫وشــيك مســحوب علــى البنــك األهلــي برقــم ‪ 3111‬يف ‪1432/12/23‬ه ـ‬\n\n\n‫‪339‬‬\n\f‫مببلــغ مائــه وخمســة أالف ريــال وباقــي املبلــغ يدفــع علــى أقســاط شــهرية‬\n‫نهايــة كل شــهر قيمــة كل قســط خمســن ألــف ريــال تدفــع عــن طريــق‬\n‫شــيكات للمدعــى عليــه علــى أن ال يصــرف املدعــى عليــه الشــيك إال يف‬\n‫تاريخ القســط نهاية كل شــهر وعلى أن أقوم أنا املدعي بتســديد رســوم‬\n‫البلديــة وعلــى أن يبقــى الصــك مرهونــا لــدى املدعــى عليــه فــا يفــرغ لــي‬\n‫إال حــن اســتالم كامــل املبلــغ وعلــى أن اســتالم املبيــع األرض املذكورة‬\n‫مــن ســاعة التعاقــد ولــم يســلمني املدعــى عليــه األرض املذكــورة حتــى‬\n‫اآلن أطلــب الــزام املدعــى عليــه بتســليمي األرض املذكــورة هكــذا‬\n‫ا مــا ذكــره املدعــي‬  ‫ادعــى وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫ا مــا عــدا مــا يخــص الشــيكات‬     ‫يف دعــواه كلــه صحيــح جملــة وتفصيـ ً‬\n‫فإنــي اشــترطت أن تكــون الشــيكات باســم املؤسســة اخلاصــة بــه وأن‬\n‫تكــون مصدقــة ولــم يســتكمل املدعــي هــذان الشــرطان لــذا لــم أســلمه‬\n‫ا‬‫املبيــع حتــى اآلن هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب قائـ ً‬\n‫مــا ذكرتــه هــو الصحيــح واملدعــى عليــه لــم يشــترط علــي أن يكــون‬\n‫الشــيك مصدقــا وكذلــك لــم يشــترط أن تكــون الشــيكات باســم‬\n‫املؤسســة هكــذا أجــاب فجــرى طلــب البينــة مــن املدعــى عليــه علــى‬\n‫مــا ذكــر مــن الشــروط فاســتمهل لذلــك ورفعــت اجللســة وتأجلــت إلــى‬\n‫يــوم االثنــن املوافــق‪1433/07/21 :‬هــ‪ ،‬الســاعة الثامنــة وبــاهلل التوفيــق‬\n‫وختمــت اجللســة يف متــام الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/07‬هـ‬\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫فلــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف والقائــم بعمــل‬\n‫املكتــب القضائــي الرابــع بنــاء علــى خطــاب فضيلــة رئيــس احملكمــة‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫العامــة بالطائــف املســاعد رقــم ‪ 331362127‬يف ‪1433/7/20‬ه ـ‬\n      ‫املتضمــن تكليفــي بالعمــل يف القســم القضائــي الرابــع يف احملكمــة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلتــه برقــم ‪ 3372501‬وتاريــخ‬\n      ‫‪1433/01/29‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33189562‬وتاريــخ‬\n      ‫‪ 1433/01/29‬ه ـ ففــي هــذا اليــوم االثنــن املوافــق ‪ 1433/7/21‬هـ ويف‬\n      ‫متــام الســاعة الثامنــة صباحــا فتحــت اجللســة وفيهــا حضــر ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬ولــم يحضــر املدعــى عليــه‬\n      ‫أصالــة ‪ ...‬وال وكيــل عنــه ولــم يردنــا منــه عــذر ًا رغــم علمــه مبوعــد‬\n      ‫اجللســة وعليــه قــررت رفــع اجللســة مــن أجــل إبــاغ املدعــى عليــه باحلضــور‬\n      ‫ورفعــت اجللســة إلــى يــوم اإلثنــن املوافــق ‪ 1433/11/8‬ه ـ يف متام الســاعة‬\n      ‫العاشــرة صباح ـ ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                   ‫ختمــت اجللســة الســاعة العاشــرة حــرر يف ‪ 1433/6/22‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ ‪ 1433/10/23‬ه ـ واملقيــدة‬\n      ‫يف هــذه احملكمــة برقــم ‪ 33189562‬وتاريــخ ‪1433/10/23‬ه ـ ففــي‬\n      ‫يــوم اإلثنــن املوافــق ‪ 1433/10/23‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n      ‫صباحــا وفيهــا حضــر املدعــى أصالــة ‪...‬املذكــورة هويتــه ســابقا وحضــر‬\n      ‫حلضــوره املدعــى عليــه أصالــة ‪...‬املذكــورة هويتــه ســابقا ( وبنــاء علــى‬\n      ‫املــادة (‪ )166‬مــن نظــام املرافعــات الشــرعية) فقــد مت قــراءة مــا ســبق‬\n      ‫ضبطــه عليهــم فصادقــا عليــه وبســؤال املدعــى عليــه عمــا اســتمهل لــه‬\n      ‫يف اجللســة الســابقة أجــاب قائــا أطلــب إمهالــي إلــى اجللســة القادمــة‬\n      ‫هكــذا أجــاب فأجبتــه لطلبــه ورفعــت اجللســة وتأجلــت إلــى يــوم الثالثــاء‬\n\n\n‫‪341‬‬\n\f‫املوافــق ‪1433/10/24‬ه ـ الســاعة الثامنــة صباحــا وختمــت اجللســة‬\n‫الســاعة الثامنــة و النصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                           ‫محمــد حــرر يف ‪ 1433/10/23‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن الرئيــس برقــم ‪3372501‬واملقيــدة‬\n‫برقــم ‪ 33189562‬ويف يــوم الثالثــاء املوافــق ‪1433/10/24‬ه ـ يف متــام‬\n‫الســاعة الثامنــة صباحــا وفيهــا حضــر الطرفــان وبســؤال املدعــى عليــه‬\n‫عمــا اســتمهل ألجلــه فأجــاب بقولــه إننــي أحضرت الشــهود الذين وعدت‬\n‫بإحضارهــم وأطلــب ســماع مــا لديهــم مــن شــهادة ثــم حضــر ‪...‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪...‬وهــو معلــم متقاعــد يســكن يف وادي‬\n‫العــرج ويبلــغ مــن العمــر ســتة وســبعون ســنة وبســؤاله عمــا لديــه مــن‬\n‫شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أنــه اتصــل بــي ‪ ...‬وقــال‬\n‫لــي اذهــب معــي إلــى جلســة الصلــح بــن ‪...‬و‪...‬ثــم ذهبنــا إلــى اســتراحة‬\n‫‪...‬وكان هــذا بعــد البيــع وكان املدعــى عليــه ‪ ...‬حاضــر بينمــا املدعــي‬\n‫‪ ...‬لــم يحضــر وأحضــر مندوبــه ‪...‬ويف أثنــاء النقــاش قــال ‪...‬أن‪...‬البائــع‬\n‫اشــترط علــى املشــتري ‪...‬تصديــق الشــيكات هــذا مــا لــدي مــن شــهادة‬\n‫ثــم حضــر ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وهــو رجــل متســبب‬\n‫ليــس لديــه عمــل وصاحــب مكتــب عقــار يســكن يف حــي ‪...‬ويبلــغ مــن‬\n‫العمــر أربعــون ســنة واملدعــى عليــه صاحــب لــه واملدعــي جــار لــه وبســؤاله‬\n‫عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أننــي‬\n‫كنــت واملدعــي ‪...‬واملدعــى عليــه ‪...‬يف منــزل املدعــي ‪...‬وقت إمضاء البيع‬\n‫ومت االتفــاق حســب مــا هــو موضــح يف العقــد دون اشــتراط التصديــق‬\n‫للشــيكات وبعــد التوقيــع قلــت ل‪ ...‬اشــتريت قــال نعــم وقلــت ل‪ ...‬قبلــت‬\n\n\n                                                                                      ‫‪342‬‬\n\f      ‫قــال نعــم ثــم تفرقنــا ومــن الغــد ذهبنــا إلــى االســتراحة الســتالمها فطلــب‬\n      ‫منــا إمهالــه إلــى الغــد وبعــد البيــع بأســبوع حضــر إلــى ‪...‬يف املكتــب‬\n      ‫الســتالم الشــيكات وبعــد اطالعــه عليهــا ردهــا ألنهــا غيــر مصدقــه‬\n      ‫وقــال إننــي اشــترطت التصديــق هــذا مــا لــدي مــن شــهادة ثــم حضــر ‪...‬‬\n      ‫ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وهــو موظف حكومــي متقاعد‬\n      ‫ويســكن يف حــي وادي ‪...‬ويبلــغ مــن العمــر ســتة وثالثــون ســنة وليــس لــه‬\n      ‫عالقــة بأحــد الطرفــن وبســؤاله عمــا لديــه مــن شــهادة أجــاب بقولــه‬\n      ‫أشــهد بــاهلل العلــي العظيــم أننــي لــم أحضــر املبايعــة بــن الطرفــن وإمنــا‬\n      ‫دخلــت مصلح ـ ًا بينهمــا بعــد البيــع بشــهرين وال علــم لــي عــن اشــتراط‬\n      ‫املدعــى عليــه ‪...‬تصديــق الشــيكات هــذا مــا لــدي مــن شــهادة ثــم قــرر‬\n      ‫املدعــي ‪...‬أنــه ال يطلــب تزكيــة الشــهود وال يطعــن فيهــم وأن شــهادة‬\n      ‫‪...‬و ‪...‬ليــس فيهــا مــا يثبــت للمدعــى عليــه شــيء وكلهــا بعــد البيــع و‬\n      ‫أمــا شــهادة ‪...‬فهــي يف صاحلــي هكــذا قــرر كمــا قــرر املدعــى عليــه‬\n      ‫أن الشــاهد الثانــي ‪...‬يف جلســة الصلــح قــرر بقولــه بعــد أن ســألته ألــم‬\n      ‫اشــترط علــى املدعــي ‪...‬أن يســلمني شــيكات مصدقــة قــال بلــى وكان‬\n      ‫هــذا بحضــور الشــاهدين ‪...‬و ‪...‬هكــذا قــرر وبعــرض ذلــك علــى الشــاهد‬\n      ‫‪...‬قــال غيــر صحيــح أننــي قلــت ذلــك وإمنــا كان االشــتراط لتصديــق‬\n      ‫الشــيكات ال حقــا وليــس يف جلســة البيــع األصليــة وإمنــا كان ذلــك‬\n      ‫بعــد أن حضــر املدعــى عليــه ‪...‬لتســلم الشــيكات قــال لــي أنــه اشــترط‬\n      ‫تصديــق الشــيكات هكــذا أجــاب وبســؤال املدعــى عليــه هــل لديــه‬\n      ‫مزيــد مــن البينــة قــال لــم يحضــر جلســة البيــع ســوى ‪...‬وأنــا والشــاهد‬\n      ‫‪...‬واكتفــي مبــا قدمــت وبســؤال املدعــي هــل لديــه مــا يضيفــه قــال نعــم‬\n      ‫إن لــدي شــهود وأطلــب إمهالــي إلحضارهــم لــذا رفعــت اجللســة حتــى‬\n\n\n‫‪343‬‬\n\f‫يــوم األحــد املوافــق ‪1433/12/26‬ه ـ الســاعة التاســعة صباحــا وختمــت‬\n‫اجللســة الســاعة التاســعة صباحــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/10/24‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف‬\n‫وبناء على املعاملة احملالة لنا من الرئيس برقم ‪3372501‬واملقيدة برقم‬\n‫‪ 33189562‬ففــي يــوم االثنــن املوافــق ‪1433/11/1‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر الطرفــان وبســؤال املدعــي عمــا‬\n‫اســتمهل ألجلــه أجــاب بقولــه أننــي أحضــرت الشــاهدين وأطلــب ســماع‬\n‫مــا لديهــم ثــم حضــر ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬وعمــره‬\n‫أربعــة وثالثــون ســنة ويعمــل يف جــوازات محافظــة الطائــف ويســكن‬\n‫يف حــي جبــره وهــو جــار للمدعــي وبســؤاله عمــا لديــه مــن شــهادة أجــاب‬\n‫بقولــه أشــهد بــاهلل العلــي العظيــم أننــي حضــرت إلى مكتــب ‪...‬للعقارات‬\n‫وكان فيــه ‪...‬و‪ ...‬وكانــوا يتفاوضــون علــى البيــع وعندمــا أردت اخلــروج‬\n‫اســتوقفني ‪...‬وقــال أريــد منــك أن تشــهد علــى املبايعــة وقمــت بســؤال‬\n‫‪...‬عــن املــراد بيعــه فقــال اســتراحة قلــت لــه كــم مســاحتها قــال ســتة‬\n‫أالف وقلــت لــه كــم املبلــغ قــال مليــون وثالثمائــة وخمســون ألــف ريــال‬\n‫يســلمها لــي عــن طريــق شــيك مســحوب علــى مصــرف األهلــي مببلــغ‬\n‫مائــة وخمســة أالف ريــال ومبلــغ مائــة وخمســة وأربعــون ألــف ريــال قيمــة‬\n‫ســيارة جيــب وســلمه ‪...‬صــورة الشــيك واالســتمارة ووقــع عليهــا ثــم اتفقــا‬\n‫علــى تقســيط بقيــة املبلــغ كل شــهر خمســون ألــف ريــال ولــم يذكــرا‬\n‫لــي هــل هــو شــيك أم نقــد وكانــوا قــد اتفقــوا علــى ذلــك ســابقا وإمنــا‬\n‫أتــوا للمكتــب للتوثيــق هــذا مــا لــدي مــن شــهادة ثــم حضــر ‪...‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪...‬وعمــره ســبعة وأربعــون ســنة ويعمــل يف‬\n\n\n                                                                                   ‫‪344‬‬\n\f      ‫قطــاع التعليــم ويســكن حــي ‪...‬وهــو مــن جيــران املدعــي وبســؤاله عمــا‬\n      ‫لديــه مــن شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم أننــي كنــت‬\n      ‫حاضــرا يف مكتــب ‪...‬للعقــارات وقــت توقيــع العقــد وكان الطرفــان قــد‬\n      ‫اتفقــا ســابقا وكنــت حاضــرا عندمــا كان ‪...‬يســأل املدعــى عليــه ‪...‬عــن‬\n      ‫البيعــة مــا هــي وكــم مســاحتها وكــم قيمتهــا فأفادنــا بأنهــا اســتراحة‬\n      ‫مبســاحة ســتة أالف متــر مربــع بقيمــة إجماليــة قدرهــا مليــون وثالثمائــة‬\n      ‫وخمســون ألــف ريــال علــى أقســاط عبــارة عــن شــيك مســحوب علــى‬\n      ‫مصــرف األهلــي مببلــغ مائــة وخمســة أالف ريــال ومبلــغ مائــة وخمســة‬\n      ‫وأربعــون ألــف ريــال قيمــة ســيارة جيــب وباقــي املبلــغ علــى دفعــات شــهرية‬\n      ‫بقيمــة خمســون ألــف ريــال ولــم يتطرقــا للشــيكات وال علــم لــي هــل هــي‬\n      ‫نقــد أم شــيكات مصدقــة أم ال هــذا مــا لــدي مــن شــهادة وبعرض شــهادة‬\n      ‫الشــهود علــى املدعــى عليــه قــال أنــا ال أعرفهــم وأمــا ‪...‬فحضــر بعــد مــا‬\n      ‫مت كل شــيء وال علــم لــه بشــيء وأمــا ‪...‬فقــد حضــر متأخــر ولــم يحضــر‬\n      ‫اتفاقنــا وأنــا قــد وقعــت يف بيــت ‪...‬وليــس يف املكتــب كمــا يقولــون‬\n      ‫ولضيــق الوقــت رفعــت اجللســة إلحضــار املزكــن ودراســة القضيــة حتــى‬\n      ‫يــوم االثنــن املوافــق ‪1433/11/15‬ه ـ الســاعة العاشــرة صباحــا وختمــت‬\n      ‫اجللســة الســاعة احلاديــة عشــر صباحــا وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1433/11/1‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق ‪1434/01/04‬هـ افتتحت‬\n      ‫اجللســة الســاعة التاســعة صباحــا وفيهــا حضــر الطرفان املدونــة هويتهما‬\n      ‫ســابقا وبســؤال املدعــي عمــا اســتمهل ألجلــه وهــل أحضــر املزكــن‬\n      ‫فأجــاب بقولــه إننــي أحضــرت بينــة جديــدة وأطلــب ســماع شــهادة مــن‬\n      ‫أحضرت ثم حضر ‪...‬ســعودي اجلنســية بالســجل املدني رقم ‪ ...‬ويســكن‬\n\n\n‫‪345‬‬\n\f‫يف حــي ‪...‬وعمــره ســبعه وأربعــون عامــا وهــو عســكري متقاعــد وأخ‬\n‫للمدعــي ويعــرف املدعــى عليــه معرفــه ســطحية وليــس بينهمــا عالقــة‬\n‫وبســؤاله عمــا لديــه مــن شــهادة أجــاب بقولــه أشــهد بــاهلل العلــي العظيــم‬\n‫أننــي حضــرت إلــى مكتــب ‪...‬للعقــارات وقــت توقيــع العقــد وقــد اتفــق‬\n‫الطرفــان مســبقا وذكــرا لــي وأنــا اســمع أنهمــا اتفقــا علــى أن تتــم البيعة‬\n‫لالســتراحة الواقعــة بجبــره مببلــغ مليــون وثالثمائــة وخمســون ألــف ريــال‬\n‫يدفــع منهــا مقدمــا مبلــغ مائتــن وخمســون ألــف ريــال عــن طريــق شــيك‬\n‫بقيمــة مائــة وخمســة آالف وســيارة جيــب مقيمــة بقيمــة مائــة وخمســة‬\n‫وأربعــون ألــف ريــال وبقيــة املبلــغ مقســط شــهريا بشــيكات قيمــة كل‬\n‫شــيك خمســون ألــف ريــال ولــم يشــترطا أن تكــون مصدقــة كمــا أننــي‬\n‫أنــا مــن أحضــر مفاتيــح الســيارة للمدعــى عليــه وســلمتها إيــاه واســتلمها‬\n‫يف نفــس اليــوم وســافر يف الســيارة إلــى جــدة كمــا قمــت بالتوقيــع علــى‬\n‫العقــد كشــاهد هــذا مــا لــدي مــن شــهادة وبعــرض ذلــك علــى املدعــى‬\n‫عليــه أجــاب بقولــه أننــي ال أطعــن يف الشــاهد غيــر أن مــا ذكــره غيــر‬\n‫صحيــح وقــد حضــر بعــد توقيعنــا للعقــد شــخصيا هكــذا أجــاب وبطلــب‬\n‫املزكــن مــن املدعــى عليــه أحضــر كل مــن ‪...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪...‬وبســؤاله عمــا لديــه أجــاب بقولــه إننــي أزكــي الشــاهدين ‪...‬و‪...‬‬\n‫وأنهــم عــدول يف أقوالهــم وأقبــل شــهادتهم وهــي مرضيــة لــي وعلــي‬\n‫هكــذا قــرر وقــررت رفــع اجللســة إلحضــار مزكــي آخــر يزكــي بقيــة‬\n‫الشــهود ولضبــط ملخــص العقــد املبــرم بينهمــا وحــدد للطرفــن جلســة‬\n‫يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ الســاعة العاشــرة صباحــا وختمــت‬\n‫اجللســة الســاعة التاســعة والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/04‬ه ـ‬\n\n\n                                                                                     ‫‪346‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ ‪ 1433/01/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33189562‬وتاريــخ ‪ 1433/01/29‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1434/01/27‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n      ‫صباحــا وفيهــا حضــر الطرفــان املدونــة هويتهمــا ســابقا وقــرر املدعــي‬\n      ‫بقولــه أننــي أحضــرت املزكــن جلميــع الشــهود ثــم حضــر ‪...‬ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪...‬كمــا حضــر ‪...‬ســعودية اجلنســية بالســجل‬\n      ‫املدنــي رقــم ‪...‬وقــرروا جميعــا بقولهــم أننــا نعــرف الشــهود ‪...‬و‪ ......‬و‪...‬‬\n      ‫ونزكيهــم ونقبــل شــهادتهم لنــا وعلينــا وال نعلــم عنهــم إال خيــرا ثــم جــرى‬\n      ‫ســؤال املدعــى عليــه هــل تقبــل ميــن املدعــي علــى عــدم اشــتراط تصديــق‬\n      ‫الشــيكات فأجــاب بقولــه نعــم ثــم جــرى عــرض اليمــن علــى املدعــي‬\n      ‫فاســتعد ببذلهــا بعــد أن أذنــت لــه واهلل العلــي العظيــم الــذي ال لــه اال هــو‬\n      ‫أننــي اشــتريت األرض الواقعــة يف حــي جبــره مــن املدعــى عليــه بقيمــة‬\n      ‫إجماليــة وقدرهــا مليــون وثالثمائــة خمســون ألــف ريــال تدفــع مائتــن‬\n      ‫وخمســون ألــف ريــال دفعــه أولــى وبقيمــة املبلــغ خمســون ألــف ريــال كل‬\n      ‫شــهر تدفــع يف نهايتــه عــن طريــق شــيكات ولــم نشــترط تصديقهــا واهلل‬\n      ‫العظيــم هكــذا حلــف ثــم جــرى الرجــوع إلــى أوراق املعاملــة فوجــدت‬\n      ‫فيهــا عقــد موقــع مــن قبــل الطرفــن والشــاهد ‪...‬والشــاهد ‪...‬والشــاهد‬\n      ‫‪...‬واملدون على أوراق مكتب ‪...‬للعقار برقم ‪ 0007‬يف ‪1432/12/23‬هـ‬\n      ‫املتضمــن بيــع األرض املذكــورة يف حــي ‪...‬بقيمــة إجماليــه قدرهــا مليــون‬\n      ‫وثالثمائــة وخمســون ألــف ريــال علــى الطريقة التي ذكرهــا املدعي دون‬\n      ‫اشــتراط تصديــق الشــيكات وبعرضــه عليهمــا صــادق عليــه الطرفــان‬\n\n\n‫‪347‬‬\n\f‫‪ .‬فبنــاء مــن الدعــوى واإلجابــة وملــا أبــرزه املدعــي مــن عقــد املبايعــة‬\n‫ومصادقــة املدعــى عليــه جملــة وتفصيــا وحيــث ال بينــه للمدعــى عليــه‬\n‫موصلــة ملــا دفــع بــه مــن اشــتراط تصديــق الشــيكات وحيــث رضــي‬\n‫بيمــن خصمــه فأداهــا وأحضــر معهــا بينــه إضافيــة تشــهد يف جملتهــا‬\n‫علــى عــدم اشــتراط وتصديــق الشــيكات وحيــث أن اشــتراط تصديــق‬\n‫الشــيكات ينــايف املقصــود مــن تقســيط املبلــغ ممــا ال يتصــور الرضــى‬\n‫بــه مــن قبــل املشــتري عــادة ولقولــه صلــى اهلل عليــه وســلم (املســلمون‬\n‫علــى شــروطهم) ولذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بتســليم‬\n‫املدعــي األرض الواقعــة يف حــي ‪...‬ومتكينــه مــن االنتفــاع بهــا كمــا‬\n‫أفهمــت املدعــي بــأن عليــه أن يســلم املدعــى عليــه املبلــغ احلــال يف ذمتــه‬\n‫وقــدره ســتمائة ألــف ريــال وأفهمتــه بــأن لــه الرجــوع علــى املدعــى عليــه‬\n‫للمطالبــة بأجــرة األرض طيلــة الفتــرة املاضيــة وبعرضــه عليهمــا قــرر‬\n‫املدعــي قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم قناعتــه فأفهمتــه بــأن‬\n‫لــه حــق االعتــراض بطلــب االســتئناف وذلــك خــال ثالثــون يومــا مــن‬\n‫تاريــخ اســتالمه للحكــم وذلــك بتقــدمي الئحــة اعتراضيــة وأن مضــت‬\n‫املــدة دون تقدميــة الالئحــة ســقط حقــه يف االعتــراض بطلــب االســتئناف‬\n‫وأكتســب احلكــم القطعيــة وختمــت اجللســة الســاعة العاشــرة والنصف‬\n‫صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 3372501‬وتاريــخ ‪1433/01/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33189562‬وتاريــخ ‪ 1433/01/29‬ه ـ ففــي يــوم‬\n\n\n                                                                                     ‫‪348‬‬\n\f      ‫األحــد املوافــق‪ 1434/07/23‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــر‬\n      ‫ظهــرا وكان قــد وردنــا قــرار محكمــة االســتئناف برقــم ‪34240677‬‬\n      ‫وتاريــخ ‪1434/6/13‬ه ـ املتضمــن مــا نصــه (احلمــد هلل وحــده والصــاة‬\n      ‫والســام علــى مــن ال نبــي بعــد وبعــد فقــد جــرى منــا نحــن قضــاة الدائــرة‬\n      ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف يف منطقــة مكــة املكرمــة‬\n      ‫اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالطائــف برقــم ‪ 34698143‬وتاريــخ ‪1434/4/22‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة العامــة بالطائــف‬\n      ‫برقــم ‪ 3424708‬وتاريــخ ‪1434/1/27‬ه ـ املتضمــن دعــوى ‪...‬ضــد ‪...‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر اعادتهــا‬\n      ‫لفضيلتــه ملالحظــة مــا يلــي ‪ .1‬البيانــات التــي اخــذت ال محــل لهــا وكان‬\n      ‫االولــى االقتصــار علــى رصــد عقــد البيــع ومراجعــة واجــراء املقتضــى‬\n      ‫الشــرعي ‪ .2‬االقتصــار يف احلكــم علــى مــا جــاء بدعــوى املدعــي‬\n      ‫ومراجعــة حكمــه يف االفهــام ‪ .3‬اســتيفاء تصديــق رئيــس احملكمــة‬\n      ‫علــى الصــك ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬ختمــه وتوقيعه‪.‬أ‪.‬هــ) وأجيــب علــى‬\n      ‫مــا ابــداه أصحــاب الفضيلــة مــن ملحوظــات فأمــا الفقــرة األولــى بأنــه‬\n      ‫مت رصــد البيانــات اســتظهارا للحــق وقــد جــرى رصــد مضمــون العقــد‬\n      ‫ســابقا وعرضــه عليهمــا وصادقــا عليــه جملــة وتفصيــا كمــا حلــف‬\n      ‫املدعــي علــى عــدم اشــتراط تصديــق الشــيكات بطلــب مــن خصمــه‪.‬‬\n      ‫وأمــا الفقــرة الثانيــة فأنــي اقــرر بتراجعــي عمــا قمــت بــه مــن افهــام‬\n      ‫للمدعــي مبطالبــة املدعــى عليــه باألجــرة ‪ .‬أمــا الفقــرة الثالثــة فقــد جــرى‬\n\n\n‫‪349‬‬\n\f‫إكمــال الــازم مــن حيــث تصديــق فضيلــة رئيــس احملكمــة وأمــرت‬\n‫ببعــث املعاملــة إلــى محكمــة االســتئناف لالطــاع علــى االجــراء االخيــر‬\n‫واتخــاذ الــازم وختمــت اجللســة يف متــام الســاعة الثانيــة عشــر والنصــف‬\n‫ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه‬\n                                      ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم اإلثنــن املوافق‪1434/10/12‬ه ـ افتتحــت اجللســة‬\n‫الســاعة التاســعة والنصــف صباحــا وكان قــد وردنــا قــرار محكمــة‬\n‫االستئناف برقم ‪ 34301076‬وتاريخ ‪1434/8/21‬هـ واملتضمن املوافقة‬\n‫علــى احلكــم الصــادر برقــم ‪ 3424705‬وتاريــخ ‪1434/1/27‬ه ـ بعــد‬\n‫االجــراء االخيــر قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬‬\n‫ختمــه وتوقيعــه قاضــي ‪...‬ختمــه وتوقيعــه لــذا اكتســب احلكــم القطعيــة‬\n‫وأمــرت بالتهميــش بذلــك علــى ســجله حتــى ال يخفــى وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪ 1434/10/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم اخلميــس املوافــق‪ 1435/01/11‬ه ـ افتتحــت اجللســة‬\n‫الســاعة احلاديــة عشــرة والنصــف صباحــا وفيهــا حضــر املدعــى عليــه‬\n‫أصالــه وكان قــد وردنــا خطــاب مديــر شــعبة تنفيــذ األحــكام رق‬\n‫‪/51‬ع يف ‪1435/01/09‬ه ـ املتضمــن أنــه مت تســليم األرض للمدعــي‬\n‫وبعــث مبلــغ ســتمائة ألــف ريــال بشــيك مصــدق لصالــح املدعــى عليــه‬\n‫حســب منطــوق احلكــم وباإلطــاع علــى املعاملــة وجــد شــيك مطبــوع‬\n‫علــى مطبوعــات مؤسســة النقــد العربــي الســعودي برقــم ‪ 028544‬يف‬\n\n\n                                                                                ‫‪350‬‬\n\f      ‫‪1435/01/08‬ه ـ يتضمــن الدفــع ألمــر ‪ ...‬مبلــغ ســتمائة الــف ريــال جــرى‬\n      ‫تســليم املدعــى عليــه هــذا الشــيك وأمــرت بالتهميــش علــى صكــه‬\n      ‫وســجله حتــى ال يخفــى وبذلــك تكــون القضيــة منتهيــة يف مــا يتعلــق‬\n      ‫مبنطــوق احلكــم وختمــت اجللســة الســاعة الثانيــة عشــرة ظهــرا وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1435/01/11‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقية الثانية مبحكمة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n      ‫احملكمــة العامــة بالطائــف برقــم ‪ 34698143‬وتاريــخ ‪1434/7/30‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3424705‬وتاريــخ ‪1434/1/27‬ه ـ ‪ ،‬املتضمــن‬\n      ‫دعــوى ‪...‬ضــد ‪ ،...‬وبدراســة الصــك وصورة ضبطــه والئحته االعتراضية‬\n      ‫تقــرر املوافقــة علــى احلكــم بعــد االجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                          ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪351‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":337,"source_page_end":351,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cc4bfe5bb85c27b7de50f36a3b69c8664ff5ef3a87e8a08c978e8cf0582c8c9","normalized_text_hash":"bf46d603345d3c76767f49fa579d766cbfaf901d2bd326fae2d125c63c058ae2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p337-3424705"},{"id":"6bcf81e4-7d61-5aaf-b5f3-bc445f3c313c","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء أمر منحة أرض -طلب تسليم وثيقه املنحة -بيع املجهول -بيع ما ال ميلك -احلكم برد املبلغ املدفوع وببطان بيع","document_number":"3433023","case_number":"3441153","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"عقار -شراء أمر منحة أرض -طلب تسليم وثيقه املنحة -بيع املجهول -بيع ما ال ميلك -احلكم برد املبلغ املدفوع وببطان بيع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3433023 :‬تاريخه ‪1434/2/9 :‬هـ رقم‬\n                          ‫الدعوى ‪3441153 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3451488‬تاريخه‪1434/3/1 :‬هـ‬\n\n\n ‫عقــار ‪ -‬شــراء أمــر منحــة أرض ‪ -‬طلــب تســليم وثيقــه املنحــة ‪ -‬بيــع‬\n ‫املجهــول ‪ -‬بيــع مــا ال ميلــك ‪ -‬احلكــم بــرد املبلــغ املدفــوع وببطــان بيــع‬\n                                                                     ‫أمــر املنحــة ‪.‬‬\n\n\n\n\n              ‫‪ -1‬نهي النبي صلى اهلل عليه وسلم عن بيع ما ال ميلك ‪.‬‬\n ‫‪ -2‬تعميم معالي وزير العدل رقم ‪/13‬ت‪ 1970/‬يف ‪1423/3/16‬هـ املشــار‬\n ‫فيــه الــى الفتــوى الصــادرة مــن اللجنــة الدائمــة للبحــوث العلميــة‬\n ‫واإلفتــاء املتضمنــة عــدم جــواز بيــع األرض املمنوحــة حتــى يســتلمها‬\n                                       ‫صاحبهــا مــن اجلهــة املختصــة ‪.‬‬\n\n\n\n ‫ادعــى املدعــى بأنــه اشــترى مــن املدعــى عليــه أمــر منحــه أرض مــن‬\n ‫األمانــة‪ -‬وذكــر املدعــى رقــم أمــر املنحــة‪ -‬كمــا ذكــر املدعــى مبلــغ‬\n ‫الشــراء وأنــه ســلمه للمدعــى عليــه كام ـاً‪ -‬قــرر املدعــى أنــه ال يعلــم‬\n ‫موقــع األرض وال حدودهــا وال أطوالهــا وال مســاحتها‪ -‬أقــر املدعــى‬\n ‫عليــه مبــا جــاء يف الدعــوى‪ -‬قــرر املدعــى عليــه أنــه قبــل ســنتني ذكــر‬\n ‫للمدعــى أنــه محتــاج لهــذه األرض ألنــه ال يوجــد لديــه بيــت وأنــه مســتعد‬\n ‫بإرجــاع املبلــغ الــذى اســتلمه للمدعــى‪ -‬كمــا ذكــر املدعــى عليــه أن‬\n\n                                                                                        ‫‪352‬‬\n\f      ‫املدعــى قبــل شــهرين أرســل لــه شــخصا وقــرر أنــه يطلــب مبلغ ـ ًا زائــد ًا‬\n      ‫علــى املبلــغ الــذى ســلمه‪ -‬ابــرز املدعــى عليــه اســتمارة بيانــات قطعــه‬\n      ‫األرض املمنوحــة‪ -‬حيــث قــرر املدعــى انــه اشــترى أمــر منحــة أرض ال‬\n      ‫يعــرف موقعهــا وال حدودهــا وأطوالهــا وبنــاء علــى فتــوى اللجنــة الدائمــة‬\n      ‫املتضمنــة عــدم جــواز بيــع األرض املمنوحــة قبــل اســتالمها لذلــك صــدر‬\n      ‫احلكــم بــرد دعــوى املدعــى واحلكــم ببطــان البيــع املذكــور وافهــام‬\n      ‫املدعــى بأنــه لــه املطالبــة باســترداد املبلــغ الــذى دفعــه‪ -‬اعتــرض املدعــى‬\n                         ‫علــى احلكــم‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بحائــل املســاعد برقــم ‪ 3441153‬وتاريــخ ‪ 1434/01/24‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34200918‬وتاريــخ ‪ 1434/01/24‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/02/09‬ه ـ فتحــت اجللســة األولــى الســاعة‬\n      ‫‪ 08 : 30‬وفيهــا حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬وادعــى علــى احلاضــر معــه ‪...‬ســجل رقــم ‪...‬قائــا يف دعــواه عليــه‬\n      ‫إنــه بتاريــخ ‪1428/9/20‬ه ـ اشــتريت مــن هــذا احلاضــر أمــر منحــة أرض‬\n      ‫صــادر مــن أمانــة منطقــة حائــل لعــام ‪1418‬ه ـ ورقمهــا ‪ 12803‬مببلــغ‬\n      ‫ســبعة عشــر ألــف ريــال ســلمتها كاملــة وقــد صــدرت وثيقــة التملــك‬\n      ‫مــن األمانــة لكــي يقــوم بتســويرها ثــم يصــدر لــه الصــك ولــذا فإنــي‬\n      ‫أطلــب ســؤال املدعــى عليــه والزامــه بتســليمي هــذه الوثيقــة حتــى أقــوم‬\n      ‫بتســوير األرض وإفــراغ األرض باســمي ألنــه ال ميلــك منهــا أي جــزء علمــا‬\n\n‫‪353‬‬\n\f‫أننــي ال أعلــم موقــع األرض وال حدودهــا وال أطوالهــا وال مســاحتها وإمنــا‬\n‫اشــتريت ورقــة منحــة أرض فقــط هــذه دعــواي وبســؤال املدعــى عليــه‬\n‫أجــاب قائــا مــا ذكــره املدعــي أننــي بعــت عليــه رقــم أرض ممنوحــة‬\n‫لــي مببلــغ ســبعة عشــر ألــف ريــال اســتلمتها فهــذا صحيــح ولكــن قبــل‬\n‫ســنتني رجعــت علــى املدعــي فقلــت يــا‪ ...‬أريــد أن أرجــع لــك حقــك ألنــي‬\n‫محتــاج هــذه األرض وال عنــدي بيــت فقــال لــي املدعــي ال أريــد فلوســي‬\n‫وال أريــد األرض وقبــل شــهرين أرســل لــي املدعــي أشــخاصا يطلــب بــدل‬\n‫الســبعة عشــر ألــف ريــال مبلــغ خمســن ألــف ريــال هــذا مــا حصــل واآلن‬\n‫أنــا غيــر مســتعد بإعطائــه وثيقــة األرض ألنــي لــم أملكهــا ومســتعد‬\n‫بإعــادة املبلــغ الــذي دفعــه حــاال هــذه إجابتــي ثــم أبــرز املدعــى عليــه‬\n‫اســتمارة بيانــات قطعــة أرض ممنوحــة صــادرة مــن مديــر إدارة املنــح‬\n‫بأمانــة منطقــة حائــل رقــم القطعــة ‪ 4424‬رقــم املخطــط ‪ 202‬بنــاء علــى‬\n‫قــرار التخصيــص رقــم ‪/463‬ح يف ‪1433/04/20‬هـ ـ واخلطــاب موجــة‬\n‫إلــى مديــر مكتــب ‪ ...‬لالستشــارات الهندســية لتســليم األرض للمواطــن‬\n‫‪...‬ويف أســفل االســتمارة خطــاب مديــر مكتــب ‪...‬املتضمــن مت تســليم‬\n‫املواطــن املذكــور قطعــة ومت اســتحصال املبلــغ املســتحق‪ ،‬أمــا أطــوال‬\n‫القطعــة ومســاحتها كمــا يلــي شــماال قطعــة رقــم ‪ 4422‬بطــول ‪ 30‬م‬\n‫وجنوبــا م ‪ 9060‬بطــول ‪30‬م شــرقا شــارع عــرض ‪15‬م بطــول ‪ 21‬م وغربــا‬\n‫قطعــة رقــم ‪ 4423‬بطــول ‪ 21‬م وإجمالــي مســاحتها ‪ 630‬م‪ 2‬هــذا مــا‬\n‫تضمنتــه اســتمارة بيانــات القطعــة ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة واإلطــاع علــى أوراق املعاملــة وحيــث إن املدعــي قــد أقــر يف‬\n‫دعــواه أنــه قــد أشــترى أمــر منحــة علــى أرض ال يعــرف موقعهــا وحدودها‬\n‫وأطوالهــا وحيــث إن دعــواه غيــر محــررة والبيــع علــى مجهــول هــذا بيــع‬\n\n\n                                                                                    ‫‪354‬‬\n\f      ‫باطــل كمــا أن املدعــى عليــه لــم يســتقر ملكــه علــى األرض وقــت‬\n      ‫البيــع واســتناد ًا علــى تعميــم معالــي وزيــر العــدل رقــم ‪/13‬ت ‪1970/‬‬\n      ‫يف ‪ 1423/03/16‬هـ ـ واملشــار فيــه إلــى الفتــوى الصــادرة مــن اللجنــة‬\n      ‫الدائمــة للبحــوث العلميــة واإلفتــاء وتتضمــن ‪ :‬عــدم جــواز بيــع األرض‬\n      ‫املمنوحــة حتــى يســتلمها صاحبهــا مــن اجلهــة املختصــة ومــا حصــل مــن‬\n      ‫بيــع لهــا قبــل ذلــك فهــو باطــل ولنهيــه صلــى اهلل عليــه وســلم عــن بيــع مــا‬\n      ‫ال ميلــك لذلــك كلــه فقــد رددت دعــوى املدعــي بخصــوص طلــب تســليمه‬\n      ‫وثيقــة املنحــة وحكمــت ببطــان هــذا البيــع وأفهمــت املدعــى بــان لــه‬\n        ‫املطالبــة باســترداد املبلــغ الــذي دفعــه هــذا مــا ظهــر لــي وبــه حكمــت‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عــدم القناعــة وطلــب‬\n      ‫متكينــه مــن تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وأفهمتــه أنــه ســوف‬\n      ‫يتــم تســليمه نســخة مــن احلكــم بعــد التوقيــع إن شــاء اهلل كمــا أفهمتــه‬\n      ‫بــأن مــدة االعتــراض وقدرهــا ثالثــون يومــا ســوف تبــدأ مــن هــذا اليــوم‬\n      ‫وأن عليــه تقــدمي الئحتــه خــال هــذه املــدة وإذا مضــت هــذه املــدة ولــم‬\n      ‫يتقــدم بالئحتــه فتســقط معارضتــه ففهــم ذلــك وأمــا املدعــى عليــه فقــرر‬\n      ‫القناعــة وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434/02/09‬هـ ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن رئيــس احملكمة العامة بحائل املســاعد برقم‬\n      ‫‪ 34200918‬وتاريخ‪1434/2/20‬ه ـ واملقيــدة لدينــا برقم ‪ 34451126‬يف‬\n      ‫‪1434/2/23‬ه ـ املرفــق بهــا الصــك رقــم ‪ 3433023‬يف ‪1434/02/9‬ه ـ‬\n      ‫الصــادر مــن فضيلــة القاضــي‪... /‬اخلــاص بدعــوى ‪...‬ضــد ‪...‬يف ملكيــة‬\n\n\n‫‪355‬‬\n\f‫عقــار علــى الصفــة املوضحــة يف الصــك وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه ببطــان هــذا البيــع وأفهــم املدعــي بــأن لــه املطالبــة باســترداد‬\n‫املبلــغ الــذي دفعــة ‪ ،‬و بدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة ‪ :‬جــرت املصادقــة علــى مــا حكــم بــه‬\n     ‫فضيلتــه ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪0‬‬\n\n\n\n\n                                                                                   ‫‪356‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":352,"source_page_end":356,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a1459e8deb8ccdc8e5abfc7fd90a067d6c252ca91b8099fe37666b25ce71a34","normalized_text_hash":"b7546ee8fa7917088a7d2e5bbce45b7b46a73cf28168d044e36a6058aba7b2c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p352-3433023"},{"id":"cb0fe084-c148-561b-8a90-041c5ae9a700","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -بيع عقار مبوجب صك -إيقاف الصك ألن اإلفراغ كان مبوجب وكالة مزورة -التداخل يف الدعوى للمصلحة -قيام املتداخل ببيع العقار محل الدعوى -بطان عقد البيع لتخلف شرط التملك وتسليم املبالغ قيمة العقار ألهلها وصرف النظر عن أتعاب احملاماة .","document_number":"3436000","case_number":"33149668","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1343/2/12","year":"1434","subject":"عقار -بيع عقار مبوجب صك -إيقاف الصك ألن اإلفراغ كان مبوجب وكالة مزورة -التداخل يف الدعوى للمصلحة -قيام املتداخل ببيع العقار محل الدعوى -بطان عقد البيع لتخلف شرط التملك وتسليم املبالغ قيمة العقار ألهلها وصرف النظر عن أتعاب احملاماة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3436000 :‬تاريخه ‪1343/2/12:‬هـ رقم‬\n                               ‫الدعوى ‪33149668 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 34269903:‬تاريخه‪1434/07/16:‬هـ‬\n\n\n        ‫عقــار‪ -‬بيــع عقــار مبوجــب صــك‪ -‬إيقــاف الصــك ألن اإلفــراغ كان‬\n        ‫مبوجــب وكالــة مــزورة‪ -‬التداخــل يف الدعــوى للمصلحــة‪ -‬قيــام‬\n        ‫املتداخــل ببيــع العقــار محــل الدعــوى‪ -‬بطــان عقــد البيــع لتخلــف‬\n        ‫شــرط التملــك وتســليم املبالــغ قيمــة العقــار ألهلهــا وصــرف النظــر‬\n                                                             ‫عــن أتعــاب احملامــاة ‪.‬‬\n\n\n\n\n        ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم ( التبــع مــا ليــس عنــدك ) رواه بــن‬\n                                                                             ‫ماجــه والترمذي‬\n        ‫‪ -2‬قــال يف الشــرح الكبيــر ‪ 55/11‬الرابــع‪ -‬أي مــن شــروط انعقــاد البيــع‪-‬‬\n        ‫أن يكــون مملــوك ًا لــه أي البائــع‪ -‬أو مــا ذونــا لــه يف بيعــه فــإن بــاع ملــك‬\n              ‫غيــرة بغيــرة اذنــه او اشــتري بعــن مالــه شــيئ ًا بغيــر اذنــه لــم يصــح )‬\n                                                                   ‫‪ -3‬االقرار حجه ملزمة‬\n                                                        ‫‪ -4‬ما بني على باطل أخذ حكمه‬\n\n\n\n        ‫ادعــى املدعــى وكالــة بــأن موكلــه اشــتري قطعــة أرض مــن املدعــى‬\n        ‫عليــه مببلــغ مائتــي ألــف ريــال وعندمــا أراد موكلــه التصــرف يف األرض‬\n        ‫بالبيــع أفيــد عــن طريــق كتابــة العــدل بــأن الصــك موقــوف بســبب أن‬\n\n‫‪357‬‬\n\f‫االفــراغ مــن قبــل األمانــة للمالــك األول ثــم للمدعــى عليــه كان مبوجــب‬\n‫وكالــة مــزورة‪ -‬طلــب املدعــى وكالــة الــزام املدعــى عليــه بتســليم‬\n‫موكلــه كامــل املبلــغ الــذي دفعــه وقــدرة مائتــا الــف ريــال ودفــع اتعــاب‬\n‫احملامــاة عشــرين ألــف ريــال‪ -‬صــادق املدعــى عليه علــى ما جاء يف دعوى‬\n‫املدعــي وكالــة ودفــع بــأن شــراءه ثــم بيعــة األرض علــى املدعــى أصالــة‬\n‫كان موثقـ ًا لــدى كتابــة العــدل‪ -‬جــرى االستفســار عــن ســجل الصــك‬\n‫وورد اجلــواب مــن كتابــة العــدل املتضمــن ايقــاف الصــك حيــث إن أصــل‬\n‫امللــك منحــة ملواطنــة ومت بيعهــا بوكالــة مــزورة‪ -‬طلــب الطرفــان إدخــال‬\n‫وكيــل البائــع طرفـ ًا يف الدعــوى ‪ -‬حضــر وكيــل البائــع األول وصــادق‬\n‫علــى الدعــوى وأن موكلــه قــام ببيــع األرض موضــع الدعــوى علــى‬\n‫املدعــى عليــه مببلــغ مائــة وعشــرين ألــف ريــال واســتلم كامــل الثمــن‬\n‫نقــد ًا واســتلم موكلــه اتعابــه خمســة االف ريــال ثــم ســلم باقــي الثمــن‬\n‫لصاحــب األرض الــذي قــام بتوكيــل موكلــة مناولــة لرجــل أرســل مــن‬\n‫طرفــة لكــون امللــك الصحيــح التــام مــع االذن مــن املالــك يف التصــرف‬\n‫ببيعــة شــرط مــن شــروط البيــع ولقولــه صلــى اهلل عليــه وســلم حلكيــم‬\n‫بــن حــزام التبــع مــا ليــس عنــدك رواه ابــن ماجــه والترمــذي لــذا صــدر‬\n‫احلكــم بإبطــال عقــد املبايعــة األول بــن املتداخــل واملدعــى عليــه وابطال‬\n‫عقــد املبايعــة الثانــي بــن املدعــى عليــه واملدعــى والــزام املدعــى عليــه‬\n‫بتســليم املدعــى مائتــي ألــف ريــال والــزام املتداخــل أصالــة وكيــل البائــع‬\n‫األول بتســليم املدعــى عليــه مائــة وعشــرين ألــف ريــال وصــرف النظــر‬\n‫عــن طلــب املدعــى وكالــة احلكــم بأتعــاب احملامــاة علــى املدعــى عليــه‬\n‫لكــون التصــرف الــذي صــدر منــه ال يلــزم ضمان ـاً‪ -‬وافهــم املتداخــل‬\n‫وكالــه بــأن ملوكلــه الرجــوع علــى مــن غــره لطلــب مــا لــزم بدفعــه‪-‬‬\n\n\n                                                                                     ‫‪358‬‬\n\f      ‫وافهــم املدعــى وكالــة بــان ملوكلــه الرجــوع بطلــب اتعــاب احملامــاة ممــن‬\n      ‫فــرط وحتمــل بطــان البيــع‪ -‬كمــا قــرر القاضــي التهميــش علــى صــك‬\n      ‫صــورة صــك العقــار مبوجــب احلكــم بعــد اكتســابه للقطعيــة‪ -‬لــم يقنــع‬\n      ‫املدعــى عليــه وال املتداخــل‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بجــازان برقــم ‪ 33149668‬وتاريــخ ‪1433/02/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33381886‬وتاريــخ ‪ 1433/02/27‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/03/15‬ه ـ أفتتحــت اجللســة الســاعة ‪: 35‬‬\n      ‫‪ 09‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ا عــن ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬بالوكالــة رقــم ‪1537‬‬      ‫‪...‬وكيـ ً‬\n      ‫بتاريــخ ‪1433/02/01‬ه ـ اجللــد ‪ 791‬الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫بجــازان املخــول لــه فيهــا املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامة‬\n      ‫الدعــاوي ضــد الغيــر وإنهــاء مــا يلــزم حضــوري يف كل دعــوى تقــام‬\n      ‫مــن املــوكل أو ضــده أمــام أي محكمــة ويف أي جهــة وإنهــاء كافــة‬\n      ‫اإلجــراءات املتعلقــة بذلــك ولــه احلــق يف ســماع الدعــوى والــرد عليهــا‬\n      ‫واإلقــرار واإلنــكار والصلــح وطلــب وقبــول احلكــم ونفيــة واإلعتــراض‬\n      ‫عليــه وطلــب متييــزه واالســتالم والتســليم ومراجعــة اجلهــات احلكوميــة‬\n      ‫ذات العالقــة بــكل مــا يلــزم والتوقيــع عنــي وكالــه خاصــة فيمــا ذكــر‬\n      ‫وعليه جرى التصديق والتوقيع ولم يحضر حلضوره املدعى عليه وال من‬\n      ‫ينوبــه ولــم يتقــدم بعــذر مقبــول ويف جلســة أخــرى حضــر املدعــي وكالــة‬\n\n‫‪359‬‬\n\f‫مبوجــب الوكالــة الصــادرة مــن كتابة العدل الثانيــة بجازان رقم ‪1537‬‬\n‫يف ‪1433/2/1‬ه ـ واملخــول لــه فيهــا حــق املطالبــة واملرافعــة واملدافعــة‬\n‫واملخاصمــة وإقامــة الدعــاوي ضــد الغيــر وإنهــاء مــا يلــزم يف كل دعــوى‬\n‫تقــام أمــام أي محكمــة ويف أي جهــة وإنهــاء كافــة اإلجــراءات املتعلقــة‬\n‫بذلــك ولــه احلــق يف ســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار‬\n‫والصلــح وطلــب وقبــول احلكــم ونفيــه واإلعتــراض عليــه وطلــب التمييــز‬\n‫واإلســتالم والتســليم ومراجعــة اجلهــات احلكوميــة ذات العالقــة وطلــب‬\n‫تبليــغ املدعــى عليــه مــرة أخــرى فأجبتــه لطلبــه وقــررت رفــع اجللســة ويف‬\n‫جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه أصالــة ‪...‬ســعودي‬\n‫جلنســية بالســجل املدنــي رقــم ‪...‬وجــرى ســؤال املدعــي عــن دعــواه ادعــى‬\n‫قائــا ‪ :‬لقــد اشــترى موكلــي قطعــة أرض اململوكــة بالصــك رقــم ‪29‬‬\n‫وتاريــخ ‪1430/10/16‬ه ـ مــن املدعــى عليــه مببلــغ مائتــن ألــف ريــال (‬\n‫‪ 200000‬ريــال ) وعندمــا أراد موكلــي التصــرف يف األرض بالبيــع أفيــد‬\n‫عــن طريــق كتابــة العــدل بــأن الصــك موقــوف وذلــك بســبب أن اإلفــراغ‬\n‫مــن قبــل األمانــة للمالــك األول ومــن املالــك األول للمدعــى عليــه كانــت‬\n‫مبوجــب وكالــة مــزورة ال تخــول حــق القبــول والبيــع وبهــذا يصبــح البيــع‬\n‫األول مبنــي علــى باطــل ولــذا أطلــب إلــزام املدعــى عليــه بتســليم موكلــي‬\n‫كامــل املبلــغ الــذي كان ثمنــا لهــذا العقــار وهــو مبلــغ ( ‪ 200000‬ريــال‬\n‫) كمــا أطلــب إلزامــه بدفــع أتعــاب احملامــاة بقيمــة عشــرين ألــف ريــال‬\n‫( ‪ 20000‬ريــال ) ملوكلــي هكــذا ادعــى وبعــرض ذك علــى علــى املدعــى‬\n‫عليــه أجــاب قائــا ‪ :‬مــا ذكــره املدعــي مــن أننــي قــد بعــت علــى موكلــه‬\n‫قطعــة األرض املدونــة بياناتهــا أعــاه مببلــغ ( ‪ 200000‬ريــال ) فصحيــح‬\n‫وقــد مت ذلــك موثقــا لــدى كتابــة العــدل األولــى بجــازان ومــا ذكــره‬\n\n\n                                                                                   ‫‪360‬‬\n\f      ‫املدعــي مــن كــون البيــع الســابق الــذي قمــت بــه كان بيعــا غيــر صحيــح‬\n      ‫فــا علــم لــي بذلــك ألن مبايعتــي األولــى صحيحــة وقــد متــت كذلــك‬\n      ‫موثقــة عــن طريــق كتابــة العــدل األولــى بجــازان هكــذا أجــاب فجــرى‬\n      ‫االطــاع علــى أصــل الصــك الصــادر مــن كتابــة العــدل األولــى بجــازان‬\n      ‫رقــم ‪ 29‬وتاريــخ ‪143/10/16‬ه ـ فقــررت الكتابــة إلــى كتابــة العــدل‬\n      ‫األولــى بجــازان لإلفــادة عــن ســريان مفعــول الصــك ومطابقتــه لســجله‬\n      ‫واإلفــادة عــن ســبب إيقــاف التصــرف يف العقــار وتزويدنــا بصــورة مــن‬\n      ‫ســجل العقــار ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n      ‫وقــد وردنــا خطــاب رئيــس كتابــة العــدل رقــم‪ 331357233‬وتاريــخ‬\n      ‫‪1433/8/11‬ه ـ املتضمــن ( نعيــد لكــم خطابكــم رقــم ‪331300391‬‬\n      ‫يف ‪1433/7/12‬ه ـ بشــأن االستفســار عــن ســريان الصــك رقــم ‪ 29‬يف‬\n      ‫‪1430 /10 /16‬هـ وبالرجوع إلى ســجل الصك تبني لنا أن أصل الصك‬\n      ‫ا‬‫منحــة مــن األمانــة للمواطنــة‪ ... /‬بالســجل ‪...‬حضــر ‪...‬بالســجل ‪...‬وكيـ ً‬\n      ‫عــن ‪ ...‬بالســجل ‪...‬مبوجــب الوكالــة رقــم ‪ 1107‬يف ‪1430/10/10‬ه ـ‬\n      ‫وحيــث أنهــا قــد زورت الوكالــة يف اســتخراج املنحــة وذلــك حســب إفــادة‬\n      ‫رئيــس كتابــة العــدل الثانيــة بالريــاض بخطــاب رقــم ‪ 331413974‬يف‬\n      ‫‪1433/7/27‬ه ـ ويجــد فضيلتكــم برفقــة خطابنــا هــذا صــورة مــن‬\n      ‫كامــل معاملــة املنحــة األســاس وبقيــة املرفقــات)أ ‪.‬هــ‪ .‬ثم طلــب الطرفان‬\n      ‫إدخــال البائــع األول يف هــذه الدعــوى ‪...‬بالســجل املدنــي ‪...‬فأجبتهمــا‬\n      ‫لطلبهمــا وقــررت طلــب حضــوره يف اجللســة القادمــة وقــررت رفــع اجللســة‬\n      ‫إلــى يــوم ‪1434/2/10‬هـ ـ وكان ختــام هــذه اجللســة عنــد الســاعة ‪00‬‬\n      ‫‪ 10:‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم ‪ .‬حــرر يف ‪ 1433/12/29‬ه ـ‬\n\n\n‫‪361‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/02/10‬ه ـ‬\n‫افتتحت اجللسة الساعة ‪ 10 : 45‬وفيها حضر املدعي وكالة واملدعى‬\n‫عليــه أصالــة واملتداخــل معهــم وكالــة ‪...‬ســعودي بالســجل املدنــي رقــم‬\n‫‪ 1020825269‬وكيــا عــن ‪...‬بالوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجــازان رقــم ‪ 34151397‬وتاريــخ ‪1434/2/9‬ه ـ واملخــول لــه‬\n‫فيهــا حــق املطالبــة واملرافعــة واملدافعــة وســماع الدعــوى والــرد عليهــا‬\n‫واإلقــرار واإلنــكار والصلــح واملطالبــة بتنفيــذ األحــكام وبعــرض مــا‬\n‫ســبق ضبطــه علــى املتداخــل وكالــة أجــاب قائــا‪ :‬مــا ذكــره املدعــي‬\n‫واملدعــى عليــه يف هــذه الدعــوى صحيــح وقــد قــام موكلــي ببيــع هــذه‬\n‫القطعــة مــن األرض اململوكــة بالصــك رقــم ‪ 29‬علــى املدعــى عليــه مببلــغ‬\n‫مائــة وعشــرين ألــف ريــال ( ‪ 120‬ألــف ريــال ) واســتلم كامــل الثمــن‬\n‫نقــدا وقــد اســتلم موكلــي أتعابــه بقيمــة خمســة آالف ريــال ( ‪5000‬‬\n‫ألــف ريــال ) ثــم ســلم باقــي الثمــن لصاحــب األرض الــذي قــام بتوكيــل‬\n‫موكلــي مناولــة لرجــل أرســل مــن طرفــه ويف هــذه اجللســة جــرى االطــاع‬\n‫علــى صــك االرض رقــم ‪ 29‬يف ‪1430/10/16‬ه ـ ونــص احلاجــة منــه ( بأن‬\n‫األرض املذكــورة أرض حكوميــة حتــت تصــرف األمانــة وقــد تنازلــت‬\n‫عنهــا ‪...‬املضافــة بحفيظــة زوجهــا ‪ 257483‬يف ‪1415/6/12‬ه ـ ســجل‬\n‫الريــاض وســجلها ‪...‬حضر‪.../‬بالســجل ‪...‬وكيــا عــن‪... /‬بالســجل‬\n‫‪...‬مبوجــب الوكالــة ‪ 1107‬يف ‪1430/10/10‬ه ـ جلــد‪ 9‬الصــادرة مــن‬\n‫عــدل الثانيــة بالريــاض بصفتــه وكيــا عــن ‪... /‬بالســجل ‪111862528‬‬\n‫بالوكالــة ‪ 72‬يف ‪1428/4/25‬ه ـ الصــادرة مــن كتابــة عــدل الطائــف‬\n‫املخولــة لــه حــق توكيــل الغيــر واســتالم املنحــة بنــاء علــى األمــر الســامي‬\n‫الكــرمي رقــم ‪/218‬م يف ‪1425/3/5‬ه ـ ) ثــم همــش علــى ظهــر الصــك‬\n\n\n                                                                                       ‫‪362‬‬\n\f      ‫( وانتقــل كامــل العقــار املذكــور يف هــذا الصــك إلــى ملــك ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب احلفيظــة رقــم ‪/...‬جــازان وتاريــخ ‪1410/4/17‬هـ ســجل‬\n      ‫‪...‬بثمــن قــدره مائــة وأربعــون ألــف ريــال وذلــك مبوجــب مــا ضبــط بعــدد‬\n      ‫‪ 203‬يف ‪1430/10/29‬ه ـ صحيفــة ‪ 98‬مجلــد‪ 5/438‬لعــام ‪1430‬ه ـ ثــم‬\n      ‫انتقــل كامــل العقــار املذكــور يف هذا الصك إلى ملك باســم ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب احلفيظــة رقــم ‪ /...‬جــازان وتاريــخ ‪1406/11/16‬ه ـ‬\n      ‫ســجل ‪...‬بثمــن قــدره مائتــان ألــف ريــال وذلــك مبوجــب مــا ضبــط بعــدد‬\n      ‫‪ 107‬يف ‪1431/2/10‬ه ـ ) أ‪.‬ه ـ صحيفــة ‪ 81‬مجلــد ‪ 2/447‬لعــام ‪1431‬هـ‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة واملدعــى عليــه واملتداخــل وكالــة‬\n      ‫صادقــوا علــى صحــة املبايعــة وقــررا املدعــى عليــه واملتداخــل وكالــة بأن‬\n      ‫املبلــغ املــدون علــى ظهــر الصــك غيــر صحيــح والصحيــح أن مبلــغ الشــراء‬\n      ‫األول كان بقيمــة مائــة وعشــرين ألــف ريــال ( ‪ 120000‬ألــف ريــال )‬\n      ‫كمــا جــرى االطــاع علــى صــورة خطــاب رئيــس كتابــة العــدل الثانيــة‬\n      ‫بالريــاض رقــم ‪143473‬وتاريــخ ‪1433/7/29‬ه ـ املرفــق صورتــه بخطــاب‬\n      ‫كتابــة عــدل جــازان األولــى إلينــا واملتضمــن ( نفيدكــم أنــه بالبحــث‬\n      ‫يف ســجالت اإلدارة لدينــا تبــن أن الوكالــة املشــار إليهــا أعــاه واملرفــق‬\n      ‫صورتهــا ليــس لهــا ســجل صحيــح ضمــن الســجالت لدينــا ونســبتها‬\n      ‫إلــى هــذه اإلدارة غيــر صحيــح ) أ‪.‬ه ـ ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫حلكيــم بــن حــزام ( ال تبيــع مــا ليــس عنــدك ) رواه ابــن ماجــة والترمــذي‬\n      ‫‪.‬ولكــون امللــك الصحيــح التــام للمبيــع مــع اإلذن مــن املالــك يف التصــرف‬\n      ‫ببيعــه شــرط مــن شــروط البيــع كمــا نــص عليــه الفقهــاء قــال يف الشــرح‬\n      ‫الكبيــر ( الرابــع ـ ـ أي مــن شــروط انعقــاد البيــع ـ ـ أن يكــون مملــوكا‬\n      ‫لــه ـ ـ أي للبائــع ـ ـ أو مأذونــا لــه يف بيعــه فــإن بــاع ملــك غيــره بغيــر إذنــه أو‬\n\n\n‫‪363‬‬\n\f‫اشــترى بعــن مالــه شــيئا بغيــر إذنــه لــم يصــح ) الشــرح الكبيــر ( ‪55/11‬‬\n‫) وإلقــرار كل طــرف باســتالم الثمــن يف املبايعــات واإلقــرار حجة ملزمة‬\n‫إذا صــدر مــن صاحــب أهليــة مقبــرة شــرعا ولكــون الوكيــل قــد خــول‬\n                                 ‫لــه يف وكالتــه حــق ( اإلقــرار ) ‪ (( .‬يتبــع ))‬\n‫وألن مــا يبنــى علــى باطــل أخــذ حكمــه وجلميــع مــا تقــدم فقــد ثبــت‬\n‫لــدي أن املتداخــل أصالــة ‪...‬قــد تصــرف يف بيــع العقــار اململــوك بالصــك‬\n‫رقــم ‪ 29‬وهــو ال ميلكــه ولــم يــأذن لــه مالكــه األصلــي بالتصــرف فيــه‬\n‫بالبيــع ‪ ،‬وقــد حكمــت مبــا يلــي ‪ :‬أوال ‪ /‬أبطلــت عقــد املبايعــة األول‬\n‫بــن ‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬و‪...‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪...‬والــذي انعقــد بتاريــخ ‪1430/10/29‬ه ـ ‪.‬ثانيــا ‪ /‬أبطلــت‬\n‫عقــد املبايعــة الثانــي بــن ‪...‬و ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬والــذي‬\n‫انعقــد بتاريــخ ‪1431/2/10‬ه ـ ‪.‬ثالثــا ‪ /‬ألزمــت املدعــى عليــه ‪ ...‬بتســليم‬\n‫املدعــي أصالــة ‪...‬مبلغــا وقــدره مائتــي ألــف ريــال ( ‪ 200000‬ألــف ريــال )‬\n‫حــاال رابعــا ‪ /‬ألزمــت املتداخــل أصالــة ‪ (...‬وكيــل البائــع األول ) بتســليم‬\n‫املدعــى عليــه ‪...‬مبلغــا وقــدره مائــة وعشــرين ألــف ريــال ( ‪ 120000‬ألــف‬\n‫ريــال )‪.‬خامســا ‪ /‬صرفــت النظــر عــن طلــب املدعــي وكالــة احلكــم‬\n‫بأتعــاب احملامــاة علــى املدعــى عليــه لكــون التصــرف الــذي صــدر منــه‬\n‫صحيــح اليلــزم ضمانــا ‪ ،‬وبذلــك حكمــت ‪ ،‬وبعــرض احلكــم علــى‬\n‫أطــراف الدعــوى قنــع بــه املدعــي وكالــة ولــم يقنــع بــه املدعــى عليــه‬\n‫ولــم يقنــع بــه املتداخــل وكالــة فأفهمــت املعتــرض منهــم بــأن لــه اســتالم‬\n‫صــورة مــن صــك احلكــم حــاال وأن لــه مــدة ( ‪ 30‬يومــا ) لتقــدمي الئحتــه‬\n‫االعتراضيــة ‪ ،‬فــإن انقضــت املــدة ولــم يتقــدم خاللهــا ســقط حقــه‬\n‫يف االعتــراض واكتســب احلكــم القطعيــة كمــا أفهمــت املتداخــل‬\n\n\n                                                                                      ‫‪364‬‬\n\f      ‫وكالــة بــأن ملوكلــه الرجــوع علــى مــن غــره لطلــب مــا ألــزم بدفعــه‬\n      ‫مبوجــب احلكــم كمــا أفهمــت املدعــي وكالــة بــأن ملوكلــه الرجــوع‬\n      ‫بطلــب أتعــاب احملامــاة ممــن فــرط وحتمــل ببطــان البيــع كمــا قــررت‬\n      ‫التهميــش علــى صــك العقــار مبوجــب هــذا احلكــم بعــد اكتســابه‬\n      ‫للقطعيــة ‪ ،‬وكان ختــام هــذه اجللســة عنــد الســاعة ‪ 11 : 30‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                           ‫حــرر يف ‪ 1434/02/10‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/08/06‬ه ـ ويف‬\n      ‫متــام الســاعة ‪ 12 : 30‬افتتحــت اجللســة وقــد عــادت املعاملــة رفــق خطــاب‬\n      ‫رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم ‪ 34156474017‬يف‬\n      ‫تاريــخ ‪1434/07/25‬ه ـ مرفقــا بهــا قــرار الدائــرة احلقوقيــة األولــى رقــم‬\n      ‫‪ 34269903‬يف ‪1434/07/16‬ه ـ واملتضمــن نــص احلاجــة منــه وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مذيــا عليــه‬\n      ‫بتوقيــع قضــاة االســتئناف ‪ ...:‬و ‪ ...‬و ‪...‬و حتــى ال يخفــى جــرى احلاقــة‬\n      ‫وأمرنــا بالتهميــش وكان ختــام هــذه اجللســة الســاعة ‪ 12 : 45‬وبــاهلل‬\n      ‫التوفيق ‪ ،‬وصلى اهلل وسلم على نبينا محمد‪ .‬حرر يف ‪1434/08/06‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بجــازان برقــم ‪ 33381886‬وتاريــخ‬\n      ‫‪1434/06/18‬هــ‪ ،‬املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n      ‫‪...‬برقــم ‪ 3436000‬وتاريــخ ‪1434/02/12‬ه ـ اخلــاص بدعــوى ‪ ... /‬ضــد‬\n      ‫‪... /‬يف أرض املتضمــن احلكــم مبــا هــو مــدون بالصــك ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n\n\n‫‪365‬‬\n\f‫تقــرر الدائــرة املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى‬\n                                      ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪366‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":357,"source_page_end":366,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5194931ed79d6ca6a1e80504d7d9ef5b58711917ba0e6bed0663cfe4f8890473","normalized_text_hash":"995f4b2b59c81226ce6a44dd02712a2daf65347010308f2ddc75b710d4cee4bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p357-3436000"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
